def validate_utf8_sequence(byte_sequence: list[int]) -> bool:
    """
    Validate if byte sequence forms valid UTF-8

    :param byte_sequence: list of byte sequence
    """
    if not byte_sequence:
        return False
    try:
        bytes(byte_sequence).decode('utf-8')
        return True
    except UnicodeDecodeError:
        return False

def filehash(text):
    """
    Generate a hash value for the passed string or bytes. This is used for the file name of a downloaded archived response
    """
    hash = 0
    for ch in text:
        if isinstance(ch, int):
            hash = (hash * 281 ^ ch * 997) & 17592186044415
        else:
            hash = (hash * 281 ^ ord(ch) * 997) & 17592186044415
    return str(hash)

@staticmethod
def to_camel_case(s: str) -> str:
    """
        Converts string to ``CamelCase``

        Args:
            s (str): string to convert such as ``snake_case_word`` or ``pascalCaseWord``

        Returns:
            str: string converted to ``CamelCaseWord``
        """
    s = s.strip()
    if not s:
        return ''
    result = s
    if '_' in result:
        return ''.join((word.title() for word in result.split('_')))
    return result[:1].upper() + result[1:]

def IsStrCanonicalInt(string):
    """
  Returns True if |string| is a canonical integer form str.
  The canonical form is such that str(int(string)) == string.
  """
    if type(string) is not str:
        return False
    try:
        i = int(string)
        return str(i) == string
    except:
        return False

def get_max_dims(array, str_isarray=False, max_dims=None, dim_no=0):
    """Returns max sizes of nested *array* on the all levels of nestedness.

    :param array: nested lists or tuples.
    :param str_isarray: if True, strings are treated as arrays of chars and
        form additional dimension.
    :param max_dims: for internal use only. Leave it as it is.
    :param dim_no: for internal use only. Leave it as it is.
    """
    if max_dims is None:
        max_dims = []
    max_dims_len = len(max_dims)
    res = max_dims
    isnew = dim_no == len(max_dims)
    if not isnew:
        max_dim = max_dims[dim_no]
        if max_dim is None:
            res = None
    if res is not None:
        array_len = None
        isstr = isinstance(array, str)
        try:
            if not str_isarray and isstr:
                raise TypeError()
            array_len = len(array)
        except TypeError:
            res = None
        if isnew:
            max_dims.append(array_len)
        elif array_len is None:
            max_dims[dim_no:] = [array_len]
        else:
            if array_len > max_dim:
                max_dims[dim_no] = array_len
            if isstr:
                max_dims[dim_no + 1:] = [None]
        if res is not None and (not isstr):
            dim_no_ = dim_no + 1
            for el in array:
                if not get_max_dims(el, str_isarray=str_isarray, max_dims=max_dims, dim_no=dim_no_):
                    break
    if dim_no == 0 and res is not None:
        res = res[:-1]
    return res

def find_function_definitions_in_hunk(hunk_lines: list[str]) -> list[tuple[str, int, int]]:
    """
    Find new function definitions within a hunk.
    Returns list of (function_name, start_line_idx, end_line_idx).
    Only considers added lines (starting with +).
    """
    functions = []
    func_def_patterns = ['^\\+\\s*(?:static\\s+)?(?:inline\\s+)?(?:__always_inline\\s+)?(?:noinline\\s+)?(?:const\\s+)?(?:\\w+\\s+\\*?\\s*)+(\\w+)\\s*\\([^;]*$', '^\\+\\s*(?:static\\s+)?(?:\\w+\\s+\\*?\\s*)*(\\w+)\\s*\\(\\s*$']
    i = 0
    while i < len(hunk_lines):
        line = hunk_lines[i]
        if not line.startswith('+'):
            i += 1
            continue
        func_name = None
        for pattern in func_def_patterns:
            match = re.match(pattern, line)
            if match:
                func_name = match.group(1)
                break
        if not func_name:
            if i > 0 and re.match('^\\+\\s*(\\w+)\\s*\\(', line):
                prev = hunk_lines[i - 1] if i > 0 else ''
                if prev.startswith('+') and re.search('(?:static|int|void|bool|u\\d+|s\\d+|long|unsigned)\\s*$', prev):
                    match = re.match('^\\+\\s*(\\w+)\\s*\\(', line)
                    if match:
                        func_name = match.group(1)
        if func_name and func_name not in ('if', 'for', 'while', 'switch', 'return', 'sizeof', 'typeof'):
            start_idx = i
            brace_depth = 0
            found_opening_brace = False
            end_idx = i
            for j in range(i, len(hunk_lines)):
                check_line = hunk_lines[j]
                if check_line.startswith('+') or check_line.startswith(' '):
                    content = check_line[1:] if check_line else ''
                    for char in content:
                        if char == '{':
                            brace_depth += 1
                            found_opening_brace = True
                        elif char == '}':
                            brace_depth -= 1
                    if found_opening_brace and brace_depth == 0:
                        end_idx = j
                        break
            if found_opening_brace:
                functions.append((func_name, start_idx, end_idx))
                i = end_idx + 1
                continue
        i += 1
    return functions

@staticmethod
def _extract_content_text(output: object) -> tuple[str | None, str | None]:
    """Extract the primary text field from a dict-style tool output.

        Returns a ``(key, text)`` tuple.  If *output* is not a dict or does
        not contain a known text key (``content`` or ``result``), both values
        are ``None``.
        """
    if not isinstance(output, dict):
        return (None, None)
    output_dict = cast('dict[str, object]', output)
    for key in ('content', 'result'):
        val = output_dict.get(key)
        if val is not None and isinstance(val, str):
            return (key, val)
    return (None, None)

def is_float(s):
    """Returns True if the value in string s is a float"""
    if s is None:
        return False
    if '.' not in s:
        return False
    try:
        float(s)
        return True
    except ValueError:
        return False

