def _list_number_abstract_id(doc) -> str | None:
    """Return the abstractNumId that the built-in 'List Number' style binds to."""
    try:
        styles = doc.styles if hasattr(doc, 'styles') else doc.part.document.styles
        st = styles['List Number'].element
        nid = st.find(qn('w:pPr')).find(qn('w:numPr')).find(qn('w:numId')).get(qn('w:val'))
        for n in doc.part.numbering_part.element.findall(qn('w:num')):
            if n.get(qn('w:numId')) == nid:
                return n.find(qn('w:abstractNumId')).get(qn('w:val'))
    except (AttributeError, KeyError):
        pass
    return None

def _build_analysis_coverage(metadata: dict, disassemble: bool) -> dict:
    """Account for what was analyzed versus what was discovered.

    A run that disassembled 3 of 400 functions must never be
    indistinguishable from a clean run of 400: automated consumers need the
    blind spots, not just the findings.
    """
    functions = metadata.get('functions') or []
    discovered = metadata.get('discovered_functions') or []
    disassembled = metadata.get('disassembled_functions') or {}
    symbolic_count = 0
    discovered_merged = 0
    for func_entry in functions:
        if not isinstance(func_entry, dict):
            continue
        if func_entry.get('discovered'):
            discovered_merged += 1
        else:
            symbolic_count += 1
    degradations = []
    if metadata.get('disassembly_skipped'):
        degradations.append(metadata['disassembly_skipped'])
    if disassemble and (not disassembled) and (not metadata.get('disassembly_skipped')):
        degradations.append('disassembly_unavailable')
    if metadata.get('is_encrypted'):
        degradations.append('fairplay_encrypted')
    if (metadata.get('link_hygiene') or {}).get('attribution_status') == 'unresolved':
        degradations.append('dependency_attribution_unresolved')
    coverage = {'functions': {'symbolic': symbolic_count, 'discovered': len(discovered), 'discovered_merged_into_function_list': discovered_merged, 'disassembled': len(disassembled)}, 'degradations': sorted(degradations)}
    if (entropy := metadata.get('entropy')):
        sections_analyzed = len(entropy.get('sections') or [])
        coverage['sections_analyzed'] = sections_analyzed
    if (gaps := metadata.get('security_properties_gaps')):
        coverage['security_properties_gaps'] = list(gaps)
    if (variance := metadata.get('security_properties_slice_variance')):
        coverage['security_properties_slice_variance'] = list(variance)
    if (scope := metadata.get('code_signature_scope')):
        coverage['code_signature_scope'] = scope
    if (variance := metadata.get('code_signature_slice_variance')):
        coverage['code_signature_slice_variance'] = list(variance)
    if (metadata.get('code_signature') or {}).get('parse_status') == 'parse_failed':
        degradations.append('code_signature_parse_failed')
        coverage['degradations'] = sorted(degradations)
    slice_summaries = metadata.get('slices') or []
    slice_errors = metadata.pop('slice_errors', [])
    if metadata.get('is_universal'):
        coverage['slices'] = {'total': len(slice_summaries) + len(slice_errors), 'summarized': len(slice_summaries), 'failed': len(slice_errors)}
        if slice_errors:
            coverage['slices']['errors'] = slice_errors
            degradations.append('slice_summary_failed')
            coverage['degradations'] = sorted(degradations)
    return coverage

def validate_dataset_structure(item: dict):
    """
    expected format:

        prompt = {
            'system': f"{system_message}",
            'conversations': [
                {'from': 'User',
                 'value': f"{user_message}",
                 'label': default_label},

                {'from': 'Assistant',
                 'value': f"{assistant_message}",
                 'label': default_label}
            ],
            "mask": "User",
            "dataset": f"{dataset}",
        }
    """
    required_fields = ['system', 'conversations', 'mask', 'dataset']
    for field in required_fields:
        if field not in item:
            return False
    for message in item['conversations']:
        if 'from' not in message or 'value' not in message:
            return False
    return True

@staticmethod
def _is_gpt5_reasoning_model(model_name: str) -> bool:
    """Whether the model is a GPT-5.x / o-series reasoning model.

        Covers gpt-5, gpt-5.4/5.5/5.6 (including suffixed variants like
        gpt-5.6-sol / gpt-5.6-luna) and the o1/o3/o4 families. These models
        only accept default sampling params and, on /v1/chat/completions,
        reject reasoning_effort together with function tools.
        """
    if not model_name or not isinstance(model_name, str):
        return False
    name = model_name.lower()
    if name.startswith('gpt-5'):
        return True
    if name.startswith(('o1', 'o3', 'o4')):
        return True
    return False

@staticmethod
def _is_positional_cache(state_tuple, class_name: str='') -> bool:
    """
        Determine if a cache layer's state is position-indexed or cumulative.

        Positional (sliceable by token position):
            KVCache, RotatingKVCache, QuantizedKVCache
        Cumulative (represents all processed tokens):
            MambaCache, ArraysCache

        Args:
            state_tuple: Cache state (keys, values) or arrays list
            class_name: Cache class name for disambiguation
        """
    if not state_tuple:
        return False
    if class_name:
        positional = {'KVCache', 'BatchKVCache', 'RotatingKVCache', 'BatchRotatingKVCache', 'QuantizedKVCache', 'TurboQuantKVCache'}
        cumulative = {'MambaCache', 'BatchMambaCache', 'ArraysCache'}
        if any((cls in class_name for cls in positional)):
            return True
        if any((cls in class_name for cls in cumulative)):
            return False
    if isinstance(state_tuple, (tuple, list)) and len(state_tuple) == 2:
        first = state_tuple[0]
        if hasattr(first, 'shape') and len(first.shape) in (3, 4):
            return True
        if isinstance(first, tuple) and len(first) >= 2:
            if hasattr(first[0], 'shape') and len(first[0].shape) in (3, 4):
                return True
    return False

def fetch_colm_openreview(year, session=None):
    """Fetch accepted COLM papers from OpenReview and return BibTeX.

    Venue id: ``colmweb.org/COLM/{year}/Conference``. Tries ``content.venueid``
    then ``invitation``. On any API/parse error prints a warning and returns ''.
    """
    venueid = 'colmweb.org/COLM/{year}/Conference'.format(year=year)
    param_sets = [{'content.venueid': venueid}, {'invitation': venueid + '/-/Submission'}, {'invitations': venueid}]
    try:
        notes = []
        errors = []
        for params in param_sets:
            try:
                notes = _fetch_openreview_note_pages(session, params)
            except Exception as exc:
                errors.append(exc)
                notes = []
            if notes:
                break
        if not notes:
            extra = ''
            if errors:
                extra = ' ({exc})'.format(exc=errors[-1])
            print('Warning: COLM {year} OpenReview returned no notes for {vid}{extra}'.format(year=year, vid=venueid, extra=extra))
            return ''
        return colm_notes_to_bib(notes, year)
    except Exception as exc:
        print('Warning: COLM {year} OpenReview fetch failed ({exc}); skipping'.format(year=year, exc=exc))
        return ''

@staticmethod
def _truncate(value: str, limit: int) -> str:
    """Truncate a long string to ``limit`` chars with an ellipsis.

        ``longBusinessSummary`` (and any other free-text profile field) can run
        to thousands of characters; capping it keeps the agent context compact.
        """
    if limit <= 0 or len(value) <= limit:
        return value
    return value[:limit].rstrip() + '…'

def color_jitter(image, img_brightness=0, img_contrast=0, img_saturation=0):
    """
    Perform color jitter on the given image.
    Args:
        image (array): image to perform color jitter.
        img_brightness (float): jitter ratio for brightness.
        img_contrast (float): jitter ratio for contrast.
        img_saturation (float): jitter ratio for saturation.
    Returns:
        image (array): the jittered image.
    """
    jitter = []
    if img_brightness != 0:
        jitter.append('brightness')
    if img_contrast != 0:
        jitter.append('contrast')
    if img_saturation != 0:
        jitter.append('saturation')
    if len(jitter) > 0:
        order = np.random.permutation(np.arange(len(jitter)))
        for idx in range(0, len(jitter)):
            if jitter[order[idx]] == 'brightness':
                image = brightness(img_brightness, image)
            elif jitter[order[idx]] == 'contrast':
                image = contrast(img_contrast, image)
            elif jitter[order[idx]] == 'saturation':
                image = saturation(img_saturation, image)
    return image

