def _pct(data: list, p: float) -> float:
    """Return the p-th percentile of ``data`` (linear interpolation)."""
    if not data:
        return 0.0
    s = sorted(data)
    k = (len(s) - 1) * p / 100.0
    (lo, hi) = (int(k), min(int(k) + 1, len(s) - 1))
    return s[lo] + (s[hi] - s[lo]) * (k - lo)

def parse_entries(lines, a, b):
    """#### blocks in [a,b) -> list of dict(id, head_line, fields=[(label, content, line_no)])."""
    (entries, cur) = ([], None)
    for i in range(a, b):
        m = _HEAD_RE.match(lines[i])
        if m:
            cur = {'id': m.group(1), 'line': i + 1, 'fields': []}
            entries.append(cur)
            continue
        if cur is None:
            continue
        fm = _FIELD_RE.match(lines[i])
        if fm:
            cur['fields'].append((fm.group(1), fm.group(2), i + 1))
    return entries

def reformat_asterisks(text):
    """
    Fixes Pandas docstring warning about using * and ** without ending \\* and \\*\\*.

    The fix distinguishes single * and ** by adding \\ to them. No changes for *italic* and **bold** usages.

    :param text: Original text with warnings
    :return: Modified text that fixes warnings
    """
    lines = text.split('\n')
    new_text = ''
    for line in lines:
        idx = 0
        while idx < len(line):
            idx1 = line.find('*', idx)
            if idx1 >= idx:
                idx2 = line.find('*', idx1 + 1)
                if idx2 == -1:
                    line = line.replace('*', '\\*')
                    idx = len(line)
                elif idx2 == idx1 + 1:
                    idx2 = line.find('**', idx1 + 2)
                    if idx2 == -1:
                        line = line.replace('**', '\\*\\*')
                        idx = idx1 + 4
                    else:
                        idx = idx2 + 2
                elif idx2 + 1 < len(line):
                    if line[idx2 + 1] == '*':
                        line = line.replace('*', '\\*', 1)
                        idx = idx2
                    else:
                        idx = idx2 + 1
                else:
                    idx = len(line)
            else:
                idx = len(line)
        new_text += line + '\n'
    return new_text

