def parse_frontmatter(text: str) -> tuple[dict, str]:
    """Return (frontmatter, body). Frontmatter values are str or dict[str, str]."""
    lines = text.splitlines()
    if not lines or lines[0].strip() != '---':
        return ({}, text)
    end = None
    for i in range(1, len(lines)):
        if lines[i].strip() == '---':
            end = i
            break
    if end is None:
        return ({}, text)
    fm: dict = {}
    key_re = re.compile('^([A-Za-z0-9_-]+):\\s*(.*)$')
    i = 1
    while i < end:
        raw = lines[i]
        if not raw.strip() or raw.lstrip().startswith('#') or raw[:1] in (' ', '\t'):
            i += 1
            continue
        m = key_re.match(raw)
        if not m:
            i += 1
            continue
        (key, inline) = (m.group(1), m.group(2).strip())
        if inline in ('>', '|', '>-', '|-', '>+', '|+'):
            block: list[str] = []
            j = i + 1
            while j < end and (not lines[j].strip() or lines[j][:1] in (' ', '\t')):
                block.append(lines[j].strip())
                j += 1
            fm[key] = ' '.join((part for part in block if part))
            i = j
            continue
        if inline == '':
            nested: dict[str, str] = {}
            j = i + 1
            while j < end and lines[j][:1] in (' ', '\t') and lines[j].strip():
                sub = key_re.match(lines[j].strip())
                if sub:
                    nested[sub.group(1)] = sub.group(2).strip()
                j += 1
            fm[key] = nested if nested else ''
            i = j
            continue
        fm[key] = inline
        i += 1
    return (fm, '\n'.join(lines[end + 1:]))

def _version_parts(version):
    """A `(major, minor, ...)` int tuple, or None if it cannot be read.

    `is_abi_risk_python_version` unpacks `version[:2]`, so handing it the string
    "3.13.3" yields `("3", ".")` and a quiet False — the interpreter most likely
    to have caused the crash would be reported as not at risk. Normalizing here
    means a caller cannot make that mistake by passing the obvious thing.
    """
    if version is None:
        return None
    if isinstance(version, str):
        try:
            return tuple((int(part) for part in version.split('.')[:3]))
        except ValueError:
            return None
    try:
        return tuple((int(part) for part in tuple(version)[:3]))
    except (TypeError, ValueError):
        return None

def readable(fileobj):
    """Determines whether or not a file-like object is readable.

    :param fileobj: The file-like object to determine if readable

    :returns: True, if readable. False otherwise.
    """
    if hasattr(fileobj, 'readable'):
        return fileobj.readable()
    return hasattr(fileobj, 'read')

def send_napalm_commands(cmds, show_output=False, debug=False):
    """
    For a given list of commands, cmds, execute the napalm_cli method via Nornir Task
    and return a dictionary of dictionaries

    First key = device
    Secondary key(s) = show commands executed via cmds

    show_output is an optional argument which prints out the Ansible-like run output.
    debug is an optional argument which prints out values to assist in debugging.

    :param cmds: list of commands to execute on each device
    :param show_output: Boolean which defaults to False.
        When True values the Ansible-like run output will be printed to stdout
    :param debug: Boolean which defaults to False. When True values will be printed to stdout
    :return: output_dict
    """
    output_dict = {}
    if isinstance(cmds, list):
        nornir_instance = InitNornir(dry_run=True)
        cli_result = nornir_instance.run(napalm_cli, commands=cmds)
        if debug:
            print(cli_result.keys())
        for dev_key in cli_result.keys():
            if debug:
                print(dev_key)
                print(cli_result[dev_key][0].result.keys())
                print(cli_result[dev_key])
                print(dir(cli_result[dev_key]))
                print(cli_result[dev_key][0])
                print(cli_result[dev_key].failed)
                print_result(cli_result)
            if cli_result[dev_key].failed:
                print(cli_result[dev_key][0])
                output_dict.update({dev_key: []})
            else:
                for result_key in cli_result[dev_key][0].result.keys():
                    output_dict.update({dev_key: cli_result[dev_key][0].result[result_key]})
        if debug:
            for (k, v) in output_dict.items():
                print('device: {} \toutput: {}'.format(k, v))
    else:
        print('ERROR! argument passed to function must be a list!  Will return empty dictionary.')
    if show_output:
        print_result(cli_result, vars=['stdout'])
    return output_dict

def _make_dig_points(nasion=None, lpa=None, rpa=None, hpi=None, dig_points=None, dig_ch_pos=None):
    """Constructs digitizer info for the info.

    Parameters
    ----------
    nasion : array-like | numpy.ndarray, shape (3,) | None
        Point designated as the nasion point.
    lpa : array-like |  numpy.ndarray, shape (3,) | None
        Point designated as the left auricular point.
    rpa : array-like |  numpy.ndarray, shape (3,) | None
        Point designated as the right auricular point.
    hpi : array-like | numpy.ndarray, shape (n_points, 3) | None
        Points designated as head position indicator points.
    dig_points : array-like | numpy.ndarray, shape (n_points, 3)
        Points designed as the headshape points.
    dig_ch_pos : dict
        Dict of EEG channel positions.

    Returns
    -------
    dig : list
        List of digitizer points to be added to the info['dig'].
    """
    dig = []
    if lpa is not None:
        lpa = np.asarray(lpa)
        if lpa.shape == (3,):
            dig.append({'r': lpa, 'ident': FIFF.FIFFV_POINT_LPA, 'kind': FIFF.FIFFV_POINT_CARDINAL, 'coord_frame': FIFF.FIFFV_COORD_HEAD})
        else:
            msg = 'LPA should have the shape (3,) instead of %s' % (lpa.shape,)
            raise ValueError(msg)
    if nasion is not None:
        nasion = np.asarray(nasion)
        if nasion.shape == (3,):
            dig.append({'r': nasion, 'ident': FIFF.FIFFV_POINT_NASION, 'kind': FIFF.FIFFV_POINT_CARDINAL, 'coord_frame': FIFF.FIFFV_COORD_HEAD})
        else:
            msg = 'Nasion should have the shape (3,) instead of %s' % (nasion.shape,)
            raise ValueError(msg)
    if rpa is not None:
        rpa = np.asarray(rpa)
        if rpa.shape == (3,):
            dig.append({'r': rpa, 'ident': FIFF.FIFFV_POINT_RPA, 'kind': FIFF.FIFFV_POINT_CARDINAL, 'coord_frame': FIFF.FIFFV_COORD_HEAD})
        else:
            msg = 'RPA should have the shape (3,) instead of %s' % (rpa.shape,)
            raise ValueError(msg)
    if hpi is not None:
        hpi = np.asarray(hpi)
        if hpi.shape[1] == 3:
            for (idx, point) in enumerate(hpi):
                dig.append({'r': point, 'ident': idx + 1, 'kind': FIFF.FIFFV_POINT_HPI, 'coord_frame': FIFF.FIFFV_COORD_HEAD})
        else:
            msg = 'HPI should have the shape (n_points, 3) instead of %s' % (hpi.shape,)
            raise ValueError(msg)
    if dig_points is not None:
        dig_points = np.asarray(dig_points)
        if dig_points.shape[1] == 3:
            for (idx, point) in enumerate(dig_points):
                dig.append({'r': point, 'ident': idx + 1, 'kind': FIFF.FIFFV_POINT_EXTRA, 'coord_frame': FIFF.FIFFV_COORD_HEAD})
        else:
            msg = 'Points should have the shape (n_points, 3) instead of %s' % (dig_points.shape,)
            raise ValueError(msg)
    if dig_ch_pos is not None:
        keys = sorted(dig_ch_pos.keys())
        for key in keys:
            dig.append({'r': dig_ch_pos[key], 'ident': int(key[-3:]), 'kind': FIFF.FIFFV_POINT_EEG, 'coord_frame': FIFF.FIFFV_COORD_HEAD})
    return dig

def _wf_best_accepted_delta_pct(wf: dict) -> float:
    """Largest positive ``e2e_delta_pct`` claimed by an accepted head/kernel.

    The workflow return carries the heads/kernels it ACCEPTED (each with the
    measured same-session A/B ``e2e_delta_pct``). This is the ground-truth signal
    that a real, parity-checked win exists — independent of whatever final
    throughput/speedup the return also reports. Returns 0.0 when nothing claims a
    positive gain.
    """
    best = 0.0
    for item in (wf.get('accepted_heads') or []) + (wf.get('accepted_kernels') or []):
        if not isinstance(item, dict):
            continue
        try:
            d = float(item.get('e2e_delta_pct') or 0.0)
        except (TypeError, ValueError):
            d = 0.0
        if d > best:
            best = d
    return best

def _resolve_field(actual: object, field: str) -> tuple[object, bool]:
    """Return ``(value, present)`` for a dotted ``field`` path into ``actual``."""
    cur = actual
    for part in field.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return (None, False)
    return (cur, True)

def DecodeUTF8(data):
    """Decodes data as UTF-8, replacing any bad characters.

  If data is not bytes type, returns as-is.
  """
    if isinstance(data, bytes):
        return data.decode('utf-8', errors='replace')
    return data

def _default_cell(value):
    """Render a flag default as a code span. Lists become `["a", "b"]` rather
    than a bare `a, b`, which reads ambiguously in a table cell."""
    if value is None or value in ('', []):
        return ''
    if isinstance(value, list | tuple):
        items = ', '.join((f'"{v}"' if isinstance(v, str) else str(v) for v in value))
        text = f'[{items}]'
    else:
        text = str(value)
    safe = ' '.join(text.replace('|', '\\|').split())
    return f'`{safe}`'

def ftbtransforms(name, tree, sent):
    """Port of manual FTB enrichments specified in Stanford parser.

	cf. ``FrenchTreebankParserParams.java``"""
    if name == 'markinf':
        for t in tree.subtrees(lambda n: strip(n.label) == 'V' and isinstance(n.parent, Tree) and isinstance(n.parent.parent, Tree) and (strip(n.parent.label) == 'VN') and (strip(n.parent.parent.label) == 'VPinf')):
            t.label += STATESPLIT + 'infinitive'
    elif name == 'markpart':
        for t in tree.subtrees(lambda n: strip(n.label) == 'V' and isinstance(n.parent, Tree) and isinstance(n.parent.parent, Tree) and (strip(n.parent.label) == 'VN') and (strip(n.parent.parent.label) == 'VPpart')):
            t.label += STATESPLIT + 'participle'
    elif name == 'markvn':
        for t in tree.subtrees(lambda n: strip(n.label) == 'VN'):
            for sub in islice(t.subtrees(), 1, None):
                sub.label += STATESPLIT + 'withVN'
    elif name == 'coord1':
        for t in tree.subtrees(lambda n: strip(n.label) == 'COORD' and len(n) >= 2):
            t.label += STATESPLIT + strip(t[1].label)
    elif name == 'de2':
        for t in tree.subtrees(lambda n: strip(n.label) == 'P' and DERE.match(sent[n[0]])):
            t.label += STATESPLIT + 'de2'
    elif name == 'de3':
        for t in tree.subtrees(lambda n: strip(n.label) in ('PP', 'COORD')):
            a = list(ancestors(t))
            for n in range(2, len(a)):
                if PPORNP.match(''.join((strip(x.label) for x in a[:n]))):
                    if strip(a[n - 1][0].label) == 'P' and DERE.match(sent[a[n - 1][0][0]]):
                        t.label += STATESPLIT + 'de3'
                        break
    elif name == 'markp1':
        for t in tree.subtrees(lambda n: strip(n.label) == 'P' and strip(n.parent.label) == 'PP' and (strip(n.parent.parent.label) == 'NP')):
            t.label += STATESPLIT + 'n'
    elif name == 'mwadvs':
        for t in tree.subtrees(lambda n: strip(n.label) == 'MWADV' and 'S' in n.parent.label):
            t.label += STATESPLIT + 'mwadv-s'
    elif name == 'mwadvsel1':
        for t in tree.subtrees(lambda n: strip(n.label) == 'MWADV' and len(n) == 2 and (strip(n[0].label) == 'P') and (strip(n[1].label) == 'N')):
            t.label += STATESPLIT + 'mwadv1'
    elif name == 'mwadvsel2':
        for t in tree.subtrees(lambda n: strip(n.label) == 'MWADV' and len(n) == 3 and (strip(n[0].label) == 'P') and (strip(n[1].label) == 'D') and (strip(n[2].label) == 'N')):
            t.label += STATESPLIT + 'mwadv2'
    elif name == 'mwnsel1':
        for t in tree.subtrees(lambda n: strip(n.label) == 'MWN' and len(n) == 2 and (strip(n[0].label) == 'N') and (strip(n[1].label) == 'A')):
            t.label += STATESPLIT + 'mwn1'
    elif name == 'mwnsel2':
        for t in tree.subtrees(lambda n: strip(n.label) == 'MWN' and len(n) == 3 and (strip(n[0].label) == 'N') and (strip(n[1].label) == 'P') and (strip(n[2].label) == 'N')):
            t.label += STATESPLIT + 'mwn2'
    elif name == 'mwnsel3':
        for t in tree.subtrees(lambda n: strip(n.label) == 'MWN' and len(n) == 3 and (strip(n[0].label) == 'N') and (sent[n[1][0]] == '-') and (strip(n[2].label) == 'N')):
            t.label += STATESPLIT + 'mwn3'
    elif name == 'ftbmakegoldpos':
        for child in tree.subtrees():
            if child.source is not None and (not child.label.startswith('MW')):
                if child.source[MORPH].upper().split('-')[0] == 'A':
                    if child.source[MORPH].upper().split('-')[1] == 'INT':
                        child.label = 'ADJWH'
                    else:
                        child.label = 'ADJ'
                elif child.source[MORPH].upper().split('-')[0] == 'ADV':
                    if len(child.source[MORPH].split('-')) > 1 and child.source[MORPH].upper().split('-')[1] == 'INT':
                        child.label = 'ADVWH'
                    else:
                        child.label = 'ADV'
                elif child.source[MORPH].upper().split('-')[0] == 'C':
                    if child.source[MORPH].upper().split('-')[1] == 'S':
                        child.label = 'CS'
                    else:
                        child.label = 'CC'
                elif child.source[MORPH].upper().split('-')[0] == 'CL':
                    if child.source[MORPH].upper().split('-')[1] == 'OBJ':
                        child.label = 'CLO'
                    elif child.source[MORPH].upper().split('-')[1] == 'REFL':
                        child.label = 'CLR'
                    else:
                        child.label = 'CLS'
                elif child.source[MORPH].upper().split('-')[0] == 'D':
                    if child.source[MORPH].upper().split('-')[1] == 'IND':
                        child.label = 'DETWH'
                    else:
                        child.label = 'DET'
                elif child.source[MORPH].upper().split('-')[0] == 'ET':
                    child.label = 'ET'
                elif child.source[MORPH].upper().split('-')[0] == 'I':
                    child.label = 'I'
                elif child.source[MORPH].upper().split('-')[0] == 'N':
                    if child.source[MORPH].upper().split('-')[1] == 'P':
                        child.label = 'NPP'
                    else:
                        child.label = 'NC'
                elif child.source[MORPH].upper().split('-')[0] == 'P':
                    child.label = 'P'
                elif child.source[MORPH].upper().split('-')[0] == 'PONCT':
                    child.label = 'PONCT'
                elif child.source[MORPH].upper().split('-')[0] == 'PREF':
                    child.label = 'PREF'
                elif child.source[MORPH].upper().split('-')[0] == 'PRO':
                    if child.source[MORPH].upper().split('-')[1] == 'INT':
                        child.label = 'PROWH'
                    elif child.source[MORPH].upper().split('-')[1] == 'REL':
                        child.label = 'PROREL'
                    else:
                        child.label = 'PRO'
                elif child.source[MORPH].upper().split('-')[0] == 'V':
                    if child.source[MORPH].upper().split('-')[1] == 'G':
                        child.label = 'VPR'
                    elif child.source[MORPH].upper().split('-')[1] == 'K':
                        child.label = 'VPP'
                    elif child.source[MORPH].upper().split('-')[1] == 'S':
                        child.label = 'VS'
                    elif child.source[MORPH].upper().split('-')[1] == 'W':
                        child.label = 'VINF'
                    elif child.source[MORPH].upper().split('-')[1] == 'Y':
                        child.label = 'VIMP'
                    else:
                        child.label = 'V'
            elif child.source is not None and child.label.startswith('MW'):
                for t in child:
                    t.label = {'N': 'NC', 'D': 'DET', 'A': 'ADJ', 'C': 'CC', 'CL': 'CLS', 'PONCT': 'PONCT', 'P': 'P', 'ADV': 'ADV', 'PRO': 'PRO', 'V': 'V', 'ET': 'ET', 'I': 'I', 'PREF': 'PREF'}[t.label]
    elif name == 'ftbraisecompl':
        for sbtree in tree.subtrees():
            if strip(sbtree.label) in ('VPinf', 'VPpart') and strip(sbtree[0].label) in ('P', 'P+D', 'MWP'):
                sbtree_label_origin = sbtree.label
                sbtree.label = 'PP'
                children = sbtree[1:]
                sbtree[1:] = []
                new_tree = ParentedTree(sbtree_label_origin, [ch for ch in children])
                new_tree.type = COMPLEMENT
                sbtree[0].type = HEAD
                for ch in children:
                    if ch.label == 'VN':
                        ch.type = HEAD
                        break
                sbtree.append(new_tree)
            elif strip(sbtree.label) == 'Ssub':
                i = 2 if sbtree[0].label in PUNCTTAGS else 1
                if strip(sbtree[i - 1].label) in ('C', 'CC', 'CS', 'MWC') and len(sbtree) > i:
                    children = sbtree[i:]
                    sbtree[i:] = []
                    new_tree = ParentedTree('Sint', [ch for ch in children])
                    new_tree.type = COMPLEMENT
                    sbtree[i - 1].type = HEAD
                    sbtree.append(new_tree)
    elif name == 'ftbundocompounds':

        def make_VP(sbtrs):
            vp = ParentedTree('VP', [])
            vp_subtree = ParentedTree(sbtrs[0].label, sbtrs[0])
            vp_subtree.type = sbtrs[0].type
            vp_subtree.source = sbtrs[0].source
            vp.append(vp_subtree)
            if strip(sbtrs[1].label) in ('P', 'P+D'):
                pp = make_PP(sbtrs[1:])
                pp.type = COMPLEMENT
                vp.append(pp)
                return vp
            if sbtrs[1].label in ('D', 'A', 'N', 'ET'):
                np = make_NP(sbtrs[1:])
                np.type = COMPLEMENT
                vp.append(np)
                return vp
            else:
                x = list(sbtrs[1:])
                sbtrs[:] = []
                vp.extend(x)
            return vp

        def make_PP(sbtrs):
            pp = ParentedTree('PP', [])
            pp_subtree = ParentedTree(sbtrs[0].label, sbtrs[0])
            pp_subtree.type = sbtrs[0].type
            pp_subtree.source = sbtrs[0].source
            pp.append(pp_subtree)
            if len(sbtrs) > 1:
                sbtrs_children = sbtrs[1:]
                np_subtree = make_NP(sbtrs_children)
                np_subtree.type = COMPLEMENT
                pp.append(np_subtree)
            return pp

        def make_NP(sbtrs):
            np = ParentedTree('NP', [])
            while sbtrs != []:
                if sbtrs[0].label in ('D', 'ET'):
                    np_subtree = ParentedTree(sbtrs[0].label, sbtrs[0])
                    np_subtree.type = sbtrs[0].type
                    np_subtree.source = sbtrs[0].source
                    np.append(np_subtree)
                    sbtrs = sbtrs[1:]
                if sbtrs[0].label == 'N':
                    np_subtree = ParentedTree(sbtrs[0].label, sbtrs[0])
                    np_subtree.type = sbtrs[0].type
                    np_subtree.source = sbtrs[0].source
                    np.append(np_subtree)
                    sbtrs = sbtrs[1:]
                elif sbtrs[0].label == 'A':
                    if len(sbtrs) > 2 and sbtrs[1].label == 'C' and (sbtrs[2] == 'A'):
                        ap = make_AP(sbtrs[0:3], 'A C A')
                        np.append(ap)
                        sbtrs = sbtrs[3:]
                    else:
                        ap = ParentedTree('AP', [])
                        ap.type = MODIFIER
                        ap_subtree = ParentedTree('A', sbtrs[0])
                        ap_subtree.type = HEAD
                        ap_subtree.source = sbtrs[0].source
                        ap.append(ap_subtree)
                        np.append(ap)
                        sbtrs = sbtrs[1:]
                elif sbtrs[0].label in ('P', 'P+D'):
                    pp = make_PP(sbtrs)
                    pp.type = COMPLEMENT
                    np.append(pp)
                    sbtrs = []
                elif sbtrs[0].label == 'C':
                    coord = make_COORD(sbtrs)
                    coord.type = MODIFIER
                    np.append(coord)
                    sbtrs = []
            return np

        def make_COORD(sbtrs):
            coord = ParentedTree('COORD', [])
            coord_subtree = ParentedTree(sbtrs[0].label, sbtrs[0])
            coord_subtree.type = sbtrs[0].type
            coord_subtree.source = sbtrs[0].source
            coord_subtree.type = HEAD
            coord.append(coord_subtree)
            if strip(sbtrs[1].label) in ('P', 'P+D'):
                pp = make_PP(sbtrs[1:])
                pp.type = COMPLEMENT
                coord.append(pp)
            else:
                np = make_NP(sbtrs[1:])
                np.type = COMPLEMENT
                coord.append(np)
            return coord

        def make_AP(sbtrs, cmpd_str):
            if cmpd_str == 'A':
                ap = ParentedTree('AP', [])
                ap_subtree = ParentedTree('A', sbtrs[0])
                ap_subtree.type = HEAD
                ap_subtree.source = sbtrs[0].source
                ap.append(ap_subtree)
            elif cmpd_str == 'A C A':
                ap = ParentedTree('AP', [])
                ap.type = MODIFIER
                ap_subtree = ParentedTree(sbtrs[0].label, sbtrs[0])
                ap_subtree.type = HEAD
                ap_subtree.source = sbtrs[0].source
                ap.append(ap_subtree)
                coord = ParentedTree('COORD', [])
                coord.type = MODIFIER
                coord_subtree = ParentedTree(sbtrs[1].label, sbtrs[1])
                coord_subtree.type = sbtrs[1].type
                coord_subtree.source = sbtrs[1].source
                coord.append(coord_subtree)
                ap2 = ParentedTree('AP', [])
                ap2.type = COMPLEMENT
                ap2_subtree = ParentedTree(sbtrs[2].label, sbtrs[2])
                ap2_subtree.type = HEAD
                ap2_subtree.source = sbtrs[2].source
                ap2.append(ap2_subtree)
                coord.append(ap2)
                ap.append(coord)
            return ap
        for sbtree in tree.subtrees():
            if sbtree.label.startswith('MW') and writebrackettree(sbtree, sent).strip() not in FTBALLOWEDCOMPOUNDS:
                base_label = sbtree.label[2:]
                if base_label in FTBREGULARCOMPOUNDPATTERNS:
                    cmpd_str = '' if sbtree is None or len(sbtree) < 2 else ' '.join((x.label for x in sbtree))
                    if FTBREGULARCOMPOUNDPATTERNS[base_label].match(cmpd_str):
                        if base_label == 'V' and sbtree.type == HEAD:
                            parent = sbtree.parent
                            parent.remove(sbtree)
                            sbtree_to_append = make_VP(sbtree)
                            sbtree_to_append.type = HEAD
                            sbtree_to_append.source = sbtree.source
                            parent.append(sbtree_to_append)
                        elif base_label == 'N':
                            parent = sbtree.parent
                            parent.remove(sbtree)
                            sbtree_to_append = make_NP(sbtree)
                            sbtree_to_append.type = sbtree.type
                            sbtree_to_append.source = sbtree.source
                            parent.append(sbtree_to_append)
                        elif strip(sbtree.label) in ('P', 'P+D') and sbtree.parent.label != 'VPinf' or base_label == 'ADV':
                            parent = sbtree.parent
                            parent.remove(sbtree)
                            sbtree_to_append = make_PP(sbtree)
                            sbtree_to_append.type = COMPLEMENT
                            sbtree_to_append.type = sbtree.type
                            sbtree_to_append.source = sbtree.source
                            parent.append(sbtree_to_append)
    else:
        return False
    return True

def _resolve_max_prompt_tokens(auto_estimate: int, explicit_limit: int | None) -> int:
    """Resolve the prompt/context token cap enforced before prefill.

    ``--max-tokens`` controls generated output length. This resolver is for
    prompt/context length only: an explicit ``--max-prompt-tokens`` value wins;
    otherwise the engine uses the automatic memory-safe estimate.
    """
    if explicit_limit is not None and explicit_limit > 0:
        return int(explicit_limit)
    return int(auto_estimate or 0)

def _get_gce_image_price(image_name, size_name, cores=1):
    """
    Return price per hour for an gce image.
    Price depends on the size of the VM.

    :type image_name: ``str``
    :param image_name: GCE image full name.
                       Can be found from GCENodeImage.name

    :type size_name: ``str``
    :param size_name: Size name of the machine running the image.
                      Can be found from GCENodeSize.name

    :type cores: ``int``
    :param cores: The number of the CPUs the machine running the image has.
                  Can be found from GCENodeSize.extra['guestCpus']

    :rtype: ``float``
    :return: Image price
    """

    def _get_gce_image_family(image_name):
        image_family = None
        if 'sql' in image_name:
            image_family = 'SQL Server'
        elif 'windows' in image_name:
            image_family = 'Windows Server'
        elif 'rhel' in image_name and 'sap' in image_name:
            image_family = 'RHEL with Update Services'
        elif 'sles' in image_name and 'sap' in image_name:
            image_family = 'SLES for SAP'
        elif 'rhel' in image_name:
            image_family = 'RHEL'
        elif 'sles' in image_name:
            image_family = 'SLES'
        return image_family
    image_family = _get_gce_image_family(image_name)
    if not image_family:
        return 0
    pricing = get_pricing(driver_type='compute', driver_name='gce_images')
    try:
        price_dict = pricing[image_family]
    except KeyError:
        return 0
    size_type = 'any'
    if 'f1' in size_name:
        size_type = 'f1'
    elif 'g1' in size_name:
        size_type = 'g1'
    price_dict_keys = price_dict.keys()
    for key in price_dict_keys:
        if key == 'description':
            continue
        if re.search('.{1}vcpu or less', key) and cores <= int(key[0]):
            return float(price_dict[key]['price'])
        if re.search('.{1}-.{1}vcpu', key) and str(cores) in key:
            return float(price_dict[key]['price'])
        if re.search('.{1}vcpu or more', key) and cores >= int(key[0]):
            return float(price_dict[key]['price'])
        if key in {'standard', 'enterprise', 'web'} and key in image_name:
            return float(price_dict[key]['price'])
        if key in {'f1', 'g1'} and size_type == key:
            return float(price_dict[key]['price'])
        elif key == 'any':
            price = float(price_dict[key]['price'])
            return price * cores if 'sles' not in image_name else price
    return 0

def annotate_e2e(obj, num_tasks, is_aggregate):
    """Recursively add "unnormalized_e2e" and "request/s" beside every "e2e_s".

    Descends through dicts and lists. Whenever a dict contains an "e2e_s" key
    with a numeric value, that value is first normalized (divided by
    num_tasks) if `is_aggregate` says the raw figure is actually a whole-run
    total rather than a per-request mean -- then the two companion keys are
    inserted using the (now per-request) value. Returns True if any change was
    made anywhere in `obj`.
    """
    changed = False
    if isinstance(obj, dict):
        if 'e2e_s' in obj:
            value = obj['e2e_s']
            if isinstance(value, (int, float)) and (not isinstance(value, bool)):
                if is_aggregate and num_tasks:
                    value = value / num_tasks
                    obj['e2e_s'] = value
                obj['unnormalized_e2e'] = value * num_tasks
                obj['request/s'] = 1.0 / value if value != 0 else None
                changed = True
        for child in obj.values():
            changed |= annotate_e2e(child, num_tasks, is_aggregate)
    elif isinstance(obj, list):
        for item in obj:
            changed |= annotate_e2e(item, num_tasks, is_aggregate)
    return changed

def parse_aider(blob: dict | None) -> dict:
    """upstream_per_exercise can be either:
    - dict keyed by '<lang>/<exercise>' (current shape from aider's benchmark.py)
    - list of {language, passed} dicts (older or alt shape)
    Handle both.
    """
    if not blob:
        return {}
    for p in blob.get('packs', []):
        if p.get('pack_id') != 'aider-polyglot-30':
            continue
        s = (p.get('scenarios') or [{}])[0]
        latency_s = s.get('latency_seconds')
        trace = s.get('verifier_trace', {})
        inner = trace.get('trace', trace) or {}
        per_ex = inner.get('upstream_per_exercise') or inner.get('per_exercise') or {}
        per_lang: dict = defaultdict(lambda : [0, 0])
        passed_total = 0
        total = 0
        if isinstance(per_ex, dict):
            for (path, entry) in per_ex.items():
                lang = path.split('/', 1)[0].lower() if '/' in path else '?'
                per_lang[lang][1] += 1
                total += 1
                if entry.get('passed') is True or entry.get('tests_passed') is True or entry.get('status') == 'pass':
                    per_lang[lang][0] += 1
                    passed_total += 1
        elif isinstance(per_ex, list):
            for entry in per_ex:
                lang = (entry.get('language') or '?').lower()
                per_lang[lang][1] += 1
                total += 1
                if entry.get('passed') is True or entry.get('status') == 'pass':
                    per_lang[lang][0] += 1
                    passed_total += 1
        passed_count = s.get('passed_count') if s.get('passed_count') is not None else passed_total
        total_count = s.get('total_count') if s.get('total_count') is not None else total
        pass_rate = s.get('pass_rate')
        if pass_rate is None and total_count:
            pass_rate = passed_count / total_count
        return {'pass_rate': pass_rate, 'passed_count': passed_count, 'total_count': total_count, 'wall_seconds': latency_s, 'per_language': dict(per_lang), 'aider_commit': inner.get('aider_pinned_commit', ''), 'polyglot_commit': inner.get('polyglot_pinned_commit', ''), 'edit_format': inner.get('edit_format', '')}
    return {}

def GetHotkey(text):
    """Return the position and character of the hotkey"""
    curEnd = len(text) + 1
    text = text.replace('&&', '__')
    while True:
        pos = text.rfind('&', 0, curEnd)
        if pos in [-1, len(text)]:
            return (-1, '')
        if text[pos - 1] == '&':
            curEnd = pos - 2
            continue
        return (pos, text[pos + 1])

