def extract_gui_predictions(extracted_predictions):
    """
    Extract all point and box coordinates from the extracted_predictions dict (for GUI tasks)

    Args:
        extracted_predictions: e.g. {"street sign": [[209.45945945945945, 269.2692692692693]]} or
                              {"button": [[x1, y1, x2, y2]]}

    Returns:
        Tuple[List[List[float]], List[List[float]]]: (list of point coordinates, list of box coordinates)
    """
    points = []
    boxes = []
    if not isinstance(extracted_predictions, dict):
        return (points, boxes)
    for (key, value) in extracted_predictions.items():
        if isinstance(value, list):
            for coord in value:
                if isinstance(coord, list):
                    try:
                        if len(coord) == 2:
                            (x, y) = (float(coord[0]), float(coord[1]))
                            points.append([x, y])
                        elif len(coord) == 4:
                            (x1, y1, x2, y2) = (float(coord[0]), float(coord[1]), float(coord[2]), float(coord[3]))
                            boxes.append([x1, y1, x2, y2])
                    except (ValueError, TypeError):
                        continue
    return (points, boxes)

def _redact_request_line(value):
    """Drop the query string from a logged HTTP request line.

    The confirm-start URLs carry ``confirmation_token`` in their query string
    and BaseHTTPRequestHandler writes the whole request line to stderr, so the
    default log leaks a live confirmation token to anything that can read the
    server's output.  Only the path is worth logging.
    """
    if not isinstance(value, str):
        return value
    match = _REQUEST_LINE_RE.match(value)
    if match is None or match.group(3) is None:
        return value
    return match.group(1) + ' ' + match.group(2) + '?<redacted>' + (match.group(4) or '')

def _register_external_meta(meta_dict: dict, cmd_name: str, cmd_def: dict) -> None:
    """Populate _CMD_META for a modular/plugin command so it shows up in /help,
    tab-completion, and the system-prompt slash-command index. Without this the
    command is callable but invisible to those surfaces."""
    if cmd_name in meta_dict:
        return
    help_field = cmd_def.get('help')
    if isinstance(help_field, tuple) and len(help_field) >= 1:
        desc = help_field[0]
        subs = list(help_field[1]) if len(help_field) >= 2 and help_field[1] else []
    elif isinstance(help_field, str):
        (desc, subs) = (help_field, [])
    else:
        (desc, subs) = ('External command', [])
    meta_dict[cmd_name] = (desc, subs)

