@staticmethod
def format_size(size: int, suffix: str='B') -> str:
    """
        Formats an integer size value to make it human-readable.

        Parameters:
        size (int): The size value to format.
        suffix (str): The suffix denoting the base unit, default: 'B' for byte

        Returns:
        str: A human-readable representation of the size value.
        """
    for unit in ['', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi']:
        if abs(size) < 1024.0:
            return '{:.2f} {}{}'.format(size, unit, suffix)
        size /= 1024.0
    return '{:.2f} {}{}'.format(size, 'Yi', suffix)

def string_to_bytes(value):
    """Converts string value to array of bytes

    Arguments:
        value:
            string value to be converted to list of bytes
    """
    if isinstance(value, str):
        return list(bytearray(value, 'utf-8'))
    return list(bytearray(value))

def _cdl_node_preflight(item, node_index):
    """Verify the SetCDL target node exists (NodeIndex is 1-based per the
    scripting README) via the current Graph API — TimelineItem.GetNumNodes is
    deprecated; the node count lives on item.GetNodeGraph()."""
    info: Dict[str, Any] = {'node_index': node_index, 'num_nodes': None, 'graph_available': False}
    try:
        graph = item.GetNodeGraph()
    except Exception as exc:
        info['reason'] = f'GetNodeGraph failed: {exc}'
        return (False, info)
    if not graph:
        info['reason'] = 'item has no node graph'
        return (False, info)
    info['graph_available'] = True
    try:
        num_nodes = graph.GetNumNodes()
    except Exception as exc:
        info['reason'] = f'GetNumNodes failed: {exc}'
        return (False, info)
    info['num_nodes'] = num_nodes
    if not isinstance(num_nodes, int) or num_nodes < 1:
        info['reason'] = 'node graph reports no nodes'
        return (False, info)
    if int(node_index) > num_nodes:
        info['reason'] = f'NodeIndex {node_index} exceeds node count {num_nodes} (NodeIndex is 1-based)'
        return (False, info)
    return (True, info)

