def get_num_layer_for_convnext(var_name):
    """
    Divide [3, 3, 27, 3] layers into 12 groups; each group is three 
    consecutive blocks, including possible neighboring downsample layers;
    adapted from https://github.com/microsoft/unilm/blob/master/beit/optim_factory.py
    """
    num_max_layer = 12
    if var_name.startswith('downsample_layers'):
        stage_id = int(var_name.split('.')[1])
        if stage_id == 0:
            layer_id = 0
        elif stage_id == 1 or stage_id == 2:
            layer_id = stage_id + 1
        elif stage_id == 3:
            layer_id = 12
        return layer_id
    elif var_name.startswith('stages'):
        stage_id = int(var_name.split('.')[1])
        block_id = int(var_name.split('.')[2])
        if stage_id == 0 or stage_id == 1:
            layer_id = stage_id + 1
        elif stage_id == 2:
            layer_id = 3 + block_id // 3
        elif stage_id == 3:
            layer_id = 12
        return layer_id
    else:
        return num_max_layer + 1

def _named_valid_plugin_proposals(prompt: object, session_id: str) -> list[str]:
    """Return valid same-session proposals explicitly named in ``prompt``."""
    if not isinstance(prompt, str) or not session_id:
        return []
    proposals = _load_plugin_proposals(session_id)
    named = []
    for (name, proposal) in proposals.items():
        if not isinstance(name, str) or len(name) > 64 or (not _SKILL_NAME_PATTERN.fullmatch(name)) or (not isinstance(proposal, dict)) or (proposal.get('confidence') not in ('high', 'medium')) or (proposal.get('surface') not in _PLUGIN_PROPOSAL_SURFACES):
            continue
        boundary = f'(?<![a-z0-9-]){re.escape(name)}(?![a-z0-9-])'
        if re.search(boundary, prompt, re.IGNORECASE):
            named.append(name)
    return named

def score2stats(opus_or_score=None):
    """Returns a dict of some basic stats about the score, like
bank_select (list of tuples (msb,lsb)),
channels_by_track (list of lists), channels_total (set),
general_midi_mode (list),
ntracks, nticks, patch_changes_by_track (list of dicts),
num_notes_by_channel (list of numbers),
patch_changes_total (set),
percussion (dict histogram of channel 9 events),
pitches (dict histogram of pitches on channels other than 9),
pitch_range_by_track (list, by track, of two-member-tuples),
pitch_range_sum (sum over tracks of the pitch_ranges),
"""
    bank_select_msb = -1
    bank_select_lsb = -1
    bank_select = []
    channels_by_track = []
    channels_total = set([])
    general_midi_mode = []
    num_notes_by_channel = dict([])
    patches_used_by_track = []
    patches_used_total = set([])
    patch_changes_by_track = []
    patch_changes_total = set([])
    percussion = dict([])
    pitches = dict([])
    pitch_range_sum = 0
    pitch_range_by_track = []
    is_a_score = True
    if opus_or_score == None:
        return {'bank_select': [], 'channels_by_track': [], 'channels_total': [], 'general_midi_mode': [], 'ntracks': 0, 'nticks': 0, 'num_notes_by_channel': dict([]), 'patch_changes_by_track': [], 'patch_changes_total': [], 'percussion': {}, 'pitches': {}, 'pitch_range_by_track': [], 'ticks_per_quarter': 0, 'pitch_range_sum': 0}
    ticks_per_quarter = opus_or_score[0]
    i = 1
    nticks = 0
    while i < len(opus_or_score):
        highest_pitch = 0
        lowest_pitch = 128
        channels_this_track = set([])
        patch_changes_this_track = dict({})
        for event in opus_or_score[i]:
            if event[0] == 'note':
                num_notes_by_channel[event[3]] = num_notes_by_channel.get(event[3], 0) + 1
                if event[3] == 9:
                    percussion[event[4]] = percussion.get(event[4], 0) + 1
                else:
                    pitches[event[4]] = pitches.get(event[4], 0) + 1
                    if event[4] > highest_pitch:
                        highest_pitch = event[4]
                    if event[4] < lowest_pitch:
                        lowest_pitch = event[4]
                channels_this_track.add(event[3])
                channels_total.add(event[3])
                finish_time = event[1] + event[2]
                if finish_time > nticks:
                    nticks = finish_time
            elif event[0] == 'note_off' or (event[0] == 'note_on' and event[4] == 0):
                finish_time = event[1]
                if finish_time > nticks:
                    nticks = finish_time
            elif event[0] == 'note_on':
                is_a_score = False
                num_notes_by_channel[event[2]] = num_notes_by_channel.get(event[2], 0) + 1
                if event[2] == 9:
                    percussion[event[3]] = percussion.get(event[3], 0) + 1
                else:
                    pitches[event[3]] = pitches.get(event[3], 0) + 1
                    if event[3] > highest_pitch:
                        highest_pitch = event[3]
                    if event[3] < lowest_pitch:
                        lowest_pitch = event[3]
                channels_this_track.add(event[2])
                channels_total.add(event[2])
            elif event[0] == 'patch_change':
                patch_changes_this_track[event[2]] = event[3]
                patch_changes_total.add(event[3])
            elif event[0] == 'control_change':
                if event[3] == 0:
                    bank_select_msb = event[4]
                elif event[3] == 32:
                    bank_select_lsb = event[4]
                if bank_select_msb >= 0 and bank_select_lsb >= 0:
                    bank_select.append((bank_select_msb, bank_select_lsb))
                    bank_select_msb = -1
                    bank_select_lsb = -1
            elif event[0] == 'sysex_f0':
                if _sysex2midimode.get(event[2], -1) >= 0:
                    general_midi_mode.append(_sysex2midimode.get(event[2]))
            if is_a_score:
                if event[1] > nticks:
                    nticks = event[1]
            else:
                nticks += event[1]
        if lowest_pitch == 128:
            lowest_pitch = 0
        channels_by_track.append(channels_this_track)
        patch_changes_by_track.append(patch_changes_this_track)
        pitch_range_by_track.append((lowest_pitch, highest_pitch))
        pitch_range_sum += highest_pitch - lowest_pitch
        i += 1
    return {'bank_select': bank_select, 'channels_by_track': channels_by_track, 'channels_total': channels_total, 'general_midi_mode': general_midi_mode, 'ntracks': len(opus_or_score) - 1, 'nticks': nticks, 'num_notes_by_channel': num_notes_by_channel, 'patch_changes_by_track': patch_changes_by_track, 'patch_changes_total': patch_changes_total, 'percussion': percussion, 'pitches': pitches, 'pitch_range_by_track': pitch_range_by_track, 'pitch_range_sum': pitch_range_sum, 'ticks_per_quarter': ticks_per_quarter}

def ConvertVCMacrosToMSBuild(s):
