def pre_post_process_layer(prev_out, out, process_cmd, dropout_rate=0.0, epsilon=1e-12, name=''):
    """
    Add residual connection, layer normalization and droput to the out tensor
    optionally according to the value of process_cmd.
    This will be used before or after multi-head attention and position-wise
    feed-forward networks.
    """
    for cmd in process_cmd:
        if cmd == 'a':
            out = out + prev_out if prev_out else out
        elif cmd == 'n':
            out_dtype = out.dtype
            if out_dtype == fluid.core.VarDesc.VarType.FP16:
                out = layers.cast(x=out, dtype='float32')
            out = layers.layer_norm(out, begin_norm_axis=len(out.shape) - 1, param_attr=fluid.ParamAttr(name=name + '_layer_norm_scale', initializer=fluid.initializer.Constant(1.0)), bias_attr=fluid.ParamAttr(name=name + '_layer_norm_bias', initializer=fluid.initializer.Constant(0.0)), epsilon=epsilon)
            if out_dtype == fluid.core.VarDesc.VarType.FP16:
                out = layers.cast(x=out, dtype='float16')
        elif cmd == 'd':
            if dropout_rate:
                out = layers.dropout(out, dropout_prob=dropout_rate, dropout_implementation='upscale_in_train', is_test=False)
    return out

@staticmethod
def early_stopping(kind, metrics_list, patience):
    """
        If patience is set to None, only stop training
        once we have seen the maximum number of epochs
        """
    stop = False
    if patience == None:
        return stop
    else:
        if kind == 'r2':
            r2s = [d['r2'] for d in metrics_list]
            best_ix = np.argmax(r2s)
            if len(metrics_list) - best_ix > patience:
                stop = True
        elif kind == 'rmse':
            r2s = [d['rmse'] for d in metrics_list]
            best_ix = np.argmin(r2s)
            if len(metrics_list) - best_ix > patience:
                stop = True
        return stop

def _unique_strings(values) -> list[str]:
    """Return non-empty strings once, preserving their first-seen order."""
    unique: list[str] = []
    seen: set[str] = set()
    for value in values:
        if not isinstance(value, str):
            continue
        value = value.strip()
        if not value or value in seen:
            continue
        unique.append(value)
        seen.add(value)
    return unique

def _record_ground_truth(rec: dict) -> str:
    """Ground truth may live under several keys (commonly `label`) and may be a
    falsy-but-valid value (e.g. label 0 / False), so test presence explicitly
    rather than truthiness — an `or` chain would silently drop those."""
    for key in ('ground_truth', 'label', 'answer', 'target', 'gold', 'gt'):
        if key in rec and rec[key] is not None:
            return _stringify_field(rec[key])
    return ''

def _check_backward_loss_type(args: tuple, kwargs: dict) -> None:
    """Validate that a loss tensor has a valid SPMD type for backward().

    Called when torch.Tensor.backward is intercepted by __torch_function__.
    Only checks when no explicit gradient is provided (the implicit grad_output
    is a 1.0 scalar on each rank, which has Invariant semantics).

    Raises:
        SpmdTypeError: If the loss type is not Invariant or Partial on any axis,
            or if the loss is untyped in strict mode.
    """
    loss = args[0]
    gradient = kwargs.get('gradient', args[1] if len(args) > 1 else None)
    if gradient is not None:
        return
    if not has_local_type(loss):
        if _state.is_strict():
            raise SpmdTypeError('backward() called on a loss tensor with no SPMD type annotation. In strict mode, annotate the loss with assert_type() before calling backward().')
        return
    for (axis, typ) in get_local_type(loss).items():
        if typ is I or typ is P:
            continue
        axis_arg = format_axis(axis)
        if typ is R:
            fix = f'The loss is Replicate on axis {axis_arg} -- this usually means an upstream all_reduce reduced to R instead of I. Consider:\n  - Changing the upstream reduction to all_reduce(..., dst=I) so the loss is Invariant, or\n  - Removing the all_reduce entirely and calling backward() on the local (Partial) loss, which is also more efficient'
        else:
            fix = f'The loss is Varying -- each rank holds a different local loss. Use reinterpret(loss, {axis_arg}, src=V, dst=P) to declare that the semantics is that you want to differentiate with regards to the (pending) reduction of the loss on all ranks'
        raise SpmdTypeError(f'backward() on a {_TYPE_FULL_NAMES[typ]} loss on axis {axis_arg} would produce incorrect gradients. The implicit grad_output is a 1.0 scalar on each rank (Invariant), but only Invariant or Partial losses are valid for backward() without an explicit gradient.\n{fix}')

def _causal_topk_pairs(seq_len: int, topk: int) -> float:
    """Approximate causal sparse-attention query/key pairs with dense formula conventions."""
    effective_topk = min(topk, seq_len)
    if effective_topk == seq_len:
        return 0.5 * seq_len * seq_len
    return effective_topk * seq_len - 0.5 * effective_topk ** 2

