def row_haystack(row: dict) -> list[str]:
    """Return the lower-cased strings the lookup query matches against."""
    parts: list[str] = []
    for key in ('pin', 'ball', 'bga_ball', 'package_ball', 'connector_pin', 'verilog_name', 'signal_name', 'customer_usage', 'devkit_usage'):
        v = row.get(key)
        if isinstance(v, str) and v:
