def validate_fields(fields):
    """Validate the field specification format. Returns list of issues."""
    issues = []
    if not isinstance(fields, list):
        issues.append('Top-level structure must be a JSON array of field objects.')
        return issues
    for (i, field) in enumerate(fields):
        if not isinstance(field, dict):
            issues.append(f'Field {i}: must be a JSON object.')
            continue
        if 'selector' not in field:
            issues.append(f"Field {i}: missing required 'selector' key.")
        if 'type' not in field:
            issues.append(f"Field {i}: missing required 'type' key.")
        elif field['type'] not in SUPPORTED_FIELD_TYPES:
            issues.append(f"Field {i}: unsupported type '{field['type']}'. Supported: {', '.join(sorted(SUPPORTED_FIELD_TYPES.keys()))}")
        if field.get('type') not in ('checkbox', 'radio', 'click') and 'value' not in field:
            issues.append(f"Field {i}: missing 'value' for type '{field.get('type', '?')}'.")
    return issues

def _eval_simpleqa(response_text: str, gold_target: str) -> bool:
    """Fallback local evaluation if GEMINI_API_KEY is not available (unit tests/offline)."""
    if not response_text:
        return False
    resp = response_text.strip()
    gold = str(gold_target).strip()
    if not gold:
        return False
    if gold.lower() in resp.lower():
        return True
    return False

def is_monotonic(values):
    """Check if a sequence is monotonically increasing or decreasing.
    Returns +1 for increasing, -1 for decreasing, 0 for neither.
    Requires at least 3 values.
    """
    if len(values) < 3:
        return 0
    diffs = [values[i + 1] - values[i] for i in range(len(values) - 1)]
    if all((d > 0 for d in diffs)):
        return 1
    if all((d < 0 for d in diffs)):
        return -1
    return 0

def _setting(field, default):
    """One numeric Training Settings value, or ``default`` if it cannot be read.

	Never throws. A heartbeat arriving while the Single is missing (fresh site,
	mid-migrate) must degrade to the shipped defaults, not 500 at a learner.
	"""
    try:
        value = cint(frappe.get_cached_doc('Training Settings').get(field))
    except Exception:
        return default
    return value or default

def humanbytes(B):
    """Return the given bytes as a human friendly string."""
    B = float(B)
    KB = float(1024)
    MB = float(KB ** 2)
    GB = float(KB ** 3)
    TB = float(KB ** 4)
    PB = float(KB ** 5)
    if B < KB:
        return '{0:.2f}'.format(B, 'Bytes' if 0 == B > 1 else 'Byte')
    elif KB <= B < MB:
        return '{0:.2f} KB'.format(B / KB)
    elif MB <= B < GB:
        return '{0:.2f} MB'.format(B / MB)
    elif GB <= B < TB:
        return '{0:.2f} GB'.format(B / GB)
    elif TB <= B < PB:
        return '{0:.2f} TB'.format(B / TB)
    elif PB <= B:
        return '{0:.2f} PB'.format(B / PB)

def schedule_n_to_change_fixed(max_n_to_change, it):
    """
    Scheduler for deciding num. of chars which need to be changed.

    :param: max_n_to_change: max number of tokens to change. 
    :param: it: index of iteration. 

    """
    if 0 < it <= 10:
        n_to_change = max_n_to_change
    elif 10 < it <= 25:
        n_to_change = max_n_to_change // 2
    elif 25 < it <= 50:
        n_to_change = max_n_to_change // 4
    elif 50 < it <= 100:
        n_to_change = max_n_to_change // 8
    elif 100 < it <= 500:
        n_to_change = max_n_to_change // 16
    else:
        n_to_change = max_n_to_change // 32
    n_to_change = max(n_to_change, 1)
    return n_to_change

@staticmethod
def _rewrite_frame_config(text: str, region_cut: str, skip_merge_stages: bool=True) -> str:
    """Rewrite a rendered config.py for one subswath: a per-subswath
        region_cut. When skip_merge_stages (the 2-3 subswath case) also set
        threshold_geocode/snaphu=0 so the merge stage handles snaphu+geocode
        across subswaths (mirrors p2p_S1_TOPS_Frame._override_thresholds). For
        a single overlapping subswath they are left at the parent values so
        snaphu+geocode run in-place."""
    overrides = {'region_cut': f'"{region_cut}"', 'iono_skip_est': '1'}
    if skip_merge_stages:
        overrides['threshold_geocode'] = '0'
        overrides['threshold_snaphu'] = '0'
    (out, seen) = ([], set())
    for line in text.splitlines():
        s = line.lstrip()
        replaced = False
        for (k, v) in overrides.items():
            if s.startswith(k + '=') or s.startswith(k + ' ') or s.startswith(k + '\t'):
                out.append(f'{k} = {v}')
                seen.add(k)
                replaced = True
                break
        if not replaced:
            out.append(line)
    for (k, v) in overrides.items():
        if k not in seen:
            out.append(f'{k} = {v}')
    return '\n'.join(out) + '\n'

def _notebook_request(connection, header_dict, payload=b''):
    """Run one notebook request/response exchange over a solver channel.

    Opens a channel, sends HEADER_JSON_DATA, the JSON header line, and the
    optional payload, then reads until newline and parses the OK/error
    response. Returns (ok, rejected, err): on a server rejection `rejected`
    is True and `err` is the parsed error string; on a transport failure
    `rejected` is False and `err` is str(e). All side-effects (state writes,
    INFO reports, the error verb) stay at the call site.
    """
    channel = None
    try:
        channel = connection.instance.open_channel()
        channel.sendall(HEADER_JSON_DATA)
        header = json.dumps(header_dict).encode() + b'\n'
        channel.sendall(header)
        if payload:
            channel.sendall(payload)
        response = b''
        while b'\n' not in response:
            chunk = channel.recv(1024)
            if not chunk:
                break
            response += chunk
        if b'OK' not in response:
            try:
                err = json.loads(response.decode().strip()).get('error', response.decode().strip())
            except Exception:
                err = response.decode(errors='replace').strip() or 'no response'
            return (False, True, err)
        return (True, False, '')
    except Exception as e:
        return (False, False, str(e))
    finally:
        if channel is not None:
            try:
                channel.close()
            except Exception:
                pass

def _normalize_hyperedge_members(he: object) -> None:
    """Canonicalize a hyperedge's member list onto the `nodes` key, in place.

    If `nodes` is already a list it wins (canonical), and only stray alias keys
    are dropped. Otherwise the first alias (`members`, then `node_ids`) that is a
    list is moved to `nodes`, with a single stderr WARNING naming the hyperedge
    id and alias used. Leftover alias keys are always removed so downstream code
    never re-reads them. Whichever branch supplied the list, member VALUES are
    coerced to hashable scalar ids and deduped preserving order (#2486) — see
    ``_coerce_hyperedge_member_refs``.
    """
    if not isinstance(he, dict):
        return
    if isinstance(he.get('nodes'), list):
        he['nodes'] = _coerce_hyperedge_member_refs(he, he['nodes'])
    else:
        for alias in _HE_MEMBER_ALIASES:
            val = he.get(alias)
            if isinstance(val, list):
                he['nodes'] = _coerce_hyperedge_member_refs(he, val)
                print(f"[graphify] WARNING: hyperedge '{he.get('id', '?')}' uses field '{alias}' instead of 'nodes'; normalizing.", file=sys.stderr)
                break
    for alias in _HE_MEMBER_ALIASES:
        he.pop(alias, None)

def pass_at_k_est(n: int, c: int, k: int) -> float:
    """Chen et al. unbiased estimator for single-task pass@k.
    n = total samples, c = number of correct samples."""
    if k > n or k < 0 or n == 0:
        return float('nan')
    num_wrong = n - c
    if num_wrong >= k:
        return 1.0 - math.comb(num_wrong, k) / math.comb(n, k)
    return 1.0 if c > 0 else 0.0

def ar5iv_main_figures(aid, max_figs=2):
    """Return [(img_url, caption)] for up to `max_figs` MAIN figures on the ar5iv page."""
    try:
        html = _get(ar5iv_url(aid)).decode('utf-8', 'ignore')
    except Exception:
        return []
    out = []
    for m in re.finditer('<figure[^>]*>(.*?)</figure>', html, re.S | re.I):
        block = m.group(1)
        img = re.search('<img[^>]+src="([^"]+\\.(?:png|jpg|jpeg|svg))"', block, re.I)
        cap = re.search('<figcaption[^>]*>(.*?)</figcaption>', block, re.S | re.I)
        if not img:
            continue
        caption = re.sub('\\s+', ' ', re.sub('<[^>]+>', ' ', cap.group(1))).strip() if cap else ''
        if not is_main_figure(caption):
            continue
        src = img.group(1)
        if src.startswith('//'):
            src = 'https:' + src
        elif src.startswith('/'):
            src = 'https://ar5iv.labs.arxiv.org' + src
        elif not src.startswith('http'):
            src = ar5iv_url(aid).rsplit('/', 1)[0] + '/' + src
        out.append((src, caption))
        if len(out) >= max_figs:
            break
    return out

def subject_of(message: str) -> str:
    """Return the first non-empty, non-comment line of a commit message."""
    for line in message.splitlines():
        stripped = line.strip()
        if stripped and (not stripped.startswith('#')):
            return stripped
    return ''

def p_parse_cli_value(s: str):
    """
    Parse a value/dependency passed to CLI
    CLI values are generated by the following non-contextual grammar:

        S -> :str: (string/number value)
        S -> [I]
        S -> {D}
        I -> I,I
        I -> S
        D -> D,D
        D -> K:S
        K -> :str:

        Starting symbol = S
        Terminal symbols: '[', ']', '{', '}', ':', ,',', :str:
            (:str: represents any string where terminals are escaped)

    TODO: The current implementation of my parser is crippled and is
          not able to parse nested structures. Currently there is no real use
          case for having nested structures as values, so it's kinda fine atm.
    """
    if len(s) == 0:
        return None
    if s[0] == '[':
        if len(s) < 2 or s[len(s) - 1] != ']':
            raise Exception("Missing ']' delimiter")
        inner = s[1:len(s) - 1]
        if inner == '':
            return []
        return [p_parse_cli_value(v) for v in p_unescaped_separated(',', inner)]
    if s[0] == '{':
        if len(s) < 2 or s[len(s) - 1] != '}':
            raise Exception("Missing '}' delimiter")
        d = {}
        inner = s[1:len(s) - 1]
        if inner == '':
            return {}
        for kv in p_unescaped_separated(',', inner):
            k_v = list(p_unescaped_separated(':', kv))
            if len(k_v) < 2:
                raise Exception('Missing value in dictionary entry')
            if len(k_v) > 2:
                raise Exception("Unexpected ':' token")
            key = k_v[0]
            value = p_parse_cli_value(k_v[1])
            d[key] = value
        return d
    if s == '\\True':
        return True
    if s == '\\False':
        return False
    if len(s) >= 3 and s[0:1] == '\\N':
        return int(s[2:])
    return s.replace('\\', '')

def _resolve_config(cfg: dict) -> dict:
    """Return cfg with the mode preset filled in (explicit values always win).

    This MUST match benchmark_model.py's _apply_mode_preset so the config this
    script writes to its overlay — and records in loop_state — is byte-identical
    to what the benchmark would resolve. The subprocesses re-read a file from
    disk, so resolving the preset only in memory here (as a bare
    cfg["mode"]=... ) would be silently dropped: the whole point of the loop's
    --mode flag (zipf, representative scale, items_per_partition) would never
    reach the actual run. We write the resolved config to an overlay and pass
    THAT to deploy + benchmark.
    """
    mode = cfg.get('mode')
    if mode is None or mode == 'standard':
        return dict(cfg)
    presets = getattr(bm, '_PRESETS', {}) if bm else {}
    merged = dict(cfg)
    for (k, v) in presets.get(mode, {}).items():
        if k not in cfg:
            merged[k] = v
    return merged

def _island_size_map(graph: dict) -> dict[int, int]:
