def split_suffix_symbol(stock_code: str) -> tuple[str, str] | None:
    """Return ``(base, suffix)`` for dotted symbols, upper-cased and stripped."""
    code = (stock_code or '').strip().upper()
    if '.' not in code:
        return None
    (base, suffix) = code.rsplit('.', 1)
    if not base or not suffix:
        return None
    return (base, suffix)

def create_label_mapping(label_names: list[str]) -> dict[int, str]:
    """Create mapping from PONER labels to standard BIO labels.

    Args:
        label_names: The list of label names.

    Returns:
        The mapping from PONER labels to standard BIO labels.
    """
    base_mapping = {'B-p': 'B-PER', 'I-p': 'I-PER', 'B-i': 'B-ORG', 'I-i': 'I-ORG', 'B-g': 'B-LOC', 'I-g': 'I-LOC', 'B-t': 'B-MISC', 'I-t': 'I-MISC', 'B-o': 'B-MISC', 'I-o': 'I-MISC'}
    mapping = {i: base_mapping.get(label_name, 'O') for (i, label_name) in enumerate(label_names)}
    return mapping

def _validate_brief_settings(updates):
    """Reject malformed daily-brief fields. Enum-validating brief_channel/theme here
    means an arbitrary value can never reach the settings store (or the dashboard
    that renders it into an <option>), closing the stored-XSS surface at the source."""
    if 'brief_channel' in updates:
        v = (updates['brief_channel'] or '').strip()
        if v and v not in _BRIEF_CHANNELS:
            return 'Unknown daily-brief channel.'
    if 'brief_theme' in updates and (updates['brief_theme'] or '').strip() not in ('dark', 'light'):
        return "Daily-brief theme must be 'dark' or 'light'."
    if 'brief_time' in updates and (not _BRIEF_TIME_RE.match((updates['brief_time'] or '').strip())):
        return 'Daily-brief time must be HH:MM (24-hour).'
    return None

def extract_api_key_from_headers(headers, request_type):
    """
    Extract API key from HTTP headers based on request type.
    Gemini: x-goog-api-key header
    FLUX: Authorization header (Bearer token)
    """
    if request_type == 'gemini':
        api_key = headers.get('x-goog-api-key', '')
        if api_key:
            return api_key
    elif request_type == 'flux':
        auth_header = headers.get('authorization', '')
        if auth_header.startswith('Bearer '):
            return auth_header[7:]
    return None

def _find_section(lines: list[str], heading: str, start: int=0) -> tuple[int, int] | None:
    """Locate ``heading`` and return ``(start_idx, end_idx)`` (exclusive).

    A section ends at the next top-level ``## `` heading or end-of-file.
    Returns ``None`` when the heading is absent.
    """
    section_start: int | None = None
    for idx in range(start, len(lines)):
        line = lines[idx]
        if section_start is None:
            if line.strip() == heading:
                section_start = idx
            continue
        if line.startswith('## ') and line.strip() != heading:
            return (section_start, idx)
    if section_start is None:
        return None
    return (section_start, len(lines))

def _cpe_product_key(cpe: str) -> str:
    """Return the ``part:vendor:product`` portion of a cpe:2.3 URI (e.g. ``a:apache:http_server``)."""
    parts = cpe.split(':')
    if len(parts) < 5:
        return ''
    return ':'.join(parts[2:5])

def parse_mem_mb(mem_str):
    """Parse a memory string (e.g., '16G', '4096M', '16') into megabytes.

    Bare numbers are treated as gigabytes (consistent with normalize_size).
    Returns integer MB value, or None if unparseable.
    """
    mem_str = str(mem_str).strip()
    if not mem_str:
        return None
    suffix = mem_str[-1].upper()
    if suffix in ('K', 'M', 'G', 'T'):
        try:
            num = float(mem_str[:-1])
        except ValueError:
            return None
        multipliers = {'K': 1 / 1024, 'M': 1, 'G': 1024, 'T': 1024 * 1024}
        return int(num * multipliers[suffix])
    try:
        return int(float(mem_str) * 1024)
    except ValueError:
        return None

def display_covered(pc: float, precision: int) -> str:
    """Return a displayable total percentage, as a string.

    Note that "0" is only returned when the value is truly zero, and "100"
    is only returned when the value is truly 100.  Rounding can never
    result in either "0" or "100".

    """
    if precision < 0:
        raise ConfigError(f'precision={precision} is invalid. Must not be negative.')
    near0 = 1.0 / 10 ** precision
    if 0 < pc < near0:
        pc = near0
    elif 100.0 - near0 < pc < 100:
        pc = 100.0 - near0
    else:
        pc = round(pc, precision)
    return f'{pc:.{precision}f}'

@staticmethod
def __ipv4Canonicalize(addr):
    """This function attempts to canonicalize an IPv4 address (four completely-specified octets) or prefix (less than four octets) into a four octet, dotted decimal string representation by appending the appropriate number of zeroes (.0) to the address. Note, an empty string is canonicalized into the any address (0.0.0.0).

        Args:
           addr (str): A string containing the IPv4 address or prefix to canonicalize

        Returns:
           str. The canonicalized IPv4 address or prefix.
        """
    if len(addr) > 0:
        octets = addr.count('.') + 1
    else:
        octets = 0
    missing = 4 - octets
    if missing > 0:
        padding = '.'.join(['0'] * missing)
        if octets > 0:
            addr += '.' + padding
        else:
            addr += padding
    return addr

def extract_boxed_content(text: str, last=False) -> str:
    """
    Extracts answers in \\boxed{}. 
    :param text: The input string containing the LaTeX content.
    :param last: If True, it extracts the last boxed content, otherwise the first one.
    :return: The extracted content in the first or last \x08oxed{}.
    """
    depth = 0
    start_pos = text.rfind('\\boxed{') if last else text.find('\\boxed{')
    end_pos = -1
    if start_pos != -1:
        content = text[start_pos + len('\\boxed{'):]
        for (i, char) in enumerate(content):
            if char == '{':
                depth += 1
            elif char == '}':
                depth -= 1
            if depth == -1:
                end_pos = i
                break
    if end_pos != -1:
        return content[:end_pos].strip()
    return 'None'

def _oidc_read_session(jar, cookie_name):
    """Reassemble a session from its cookie shards, or return None.

    Shards must be contiguous from -0. A gap means the client dropped part of
    the session, which is indistinguishable from having no session at all.
    """
    (shards, index) = ([], 0)
    while f'{cookie_name}-{index}' in jar:
        shards.append(jar[f'{cookie_name}-{index}'])
        index += 1
    if not shards:
        return None
    try:
        blob = ''.join(shards)
        blob += '=' * (-len(blob) % 4)
        return json.loads(base64.urlsafe_b64decode(blob.encode()))
    except Exception:
        return None

def get_json_path(path_list):
    """
    Convert a JSON element path or JSON schema path provided in the exception
    data of a jsonschema validation error into a human readable path string
    that can be used in messages.
    """
    path_str = ''
    for item in path_list:
        if isinstance(item, int):
            path_str += f'[{item}]'
        elif isinstance(item, str):
            path_str += f'.{item}'
    return path_str.lstrip('.')

def inverse_data_size(value, include_space=True):
    """
    Invert the data_size() function to convert a size in bytes into a
    data size string.
    """
    if value >= 1024 ** 4:
        string = f'{value / 1024 ** 4:.1f} TiB'
    elif value >= 1024 ** 3:
        string = f'{value / 1024 ** 3:.1f} GiB'
    elif value >= 1024 ** 2:
        string = f'{value / 1024 ** 2:.1f} MiB'
    elif value >= 1024:
        string = f'{value / 1024:.1f} kiB'
    else:
        string = f'{value:.1f} B'
    if not include_space:
        string = string.replace(' ', '')
    return string

def poly_mult_2(a: int, b: int):
    """
    Return binary multplication in Z2
    """

    def multbiggest(a, b):
        r = 0
        for i in range(a.bit_length()):
            if a >> i & 1:
                r ^= b << i
        return r
    if a.bit_length() >= b.bit_length():
        return multbiggest(a, b)
    return multbiggest(b, a)

def classify_mechanism(col: str, mask: list[bool], all_masks: dict[str, list[bool]]) -> str:
    """
    Heuristic classification of missingness mechanism:
    - MCAR: nulls appear randomly, no correlation with other columns
    - MAR:  nulls correlate with values in other observed columns
    - MNAR: nulls correlate with the missing column's own unobserved value (can't fully detect)

    Returns one of: "MCAR (likely)", "MAR (likely)", "MNAR (possible)", "Insufficient data"
    """
    null_indices = {i for (i, v) in enumerate(mask) if v}
    if not null_indices:
        return 'None'
    n = len(mask)
    if n < 10:
        return 'Insufficient data'
    correlated_cols = []
    for (other_col, other_mask) in all_masks.items():
        if other_col == col:
            continue
        other_null_indices = {i for (i, v) in enumerate(other_mask) if v}
        if not other_null_indices:
            continue
        overlap = len(null_indices & other_null_indices)
        union = len(null_indices | other_null_indices)
        jaccard = overlap / union if union else 0
        if jaccard > 0.5:
            correlated_cols.append(other_col)
    sorted_indices = sorted(null_indices)
    if len(sorted_indices) > 2:
        gaps = [sorted_indices[i + 1] - sorted_indices[i] for i in range(len(sorted_indices) - 1)]
        avg_gap = sum(gaps) / len(gaps)
        clustered = avg_gap < n / len(null_indices) * 0.5
    else:
        clustered = False
    if correlated_cols:
        return f"MAR (likely) — co-occurs with nulls in: {', '.join(correlated_cols[:3])}"
    elif clustered:
        return 'MNAR (possible) — nulls are spatially clustered, may reflect a systematic gap'
    else:
        return 'MCAR (likely) — nulls appear random, no strong correlation detected'

def construct_llvm_target_tuple(metadata: dict) -> str:
    """
    Constructs an LLVM target tuple string from binary metadata.
    Format: arch-vendor-os-environment

    Args:
        metadata (dict): The dictionary of parsed binary metadata.

    Returns:
        str: A string representing the LLVM target tuple.
    """
    if metadata.get('is_dotnet'):
        if metadata.get('exe_type') == 'PE32':
            arch = 'i686'
        else:
            arch = 'x86_64'
        return f'{arch}-pc-windows-msvc'
    vendor = 'unknown'
    os_str = 'unknown'
    env = ''
    machine_type = (metadata.get('machine_type') or metadata.get('cpu_type') or '').upper()
    endianness = metadata.get('endianness', 'LSB').upper()
    arch_map = {'I386': 'i686', 'X86_64': 'x86_64', 'AMD64': 'x86_64', 'ARM': 'arm', 'AARCH64': 'aarch64', 'ARM64': 'aarch64', 'ARM64EC': 'aarch64', 'ARM64X': 'aarch64', 'MIPS': 'mips', 'MIPS_RS3_LE': 'mipsel', 'PPC': 'ppc', 'POWERPC': 'ppc', 'PPC64': 'ppc64', 'POWERPC64': 'ppc64', 'RISCV': 'riscv64', 'SYSTEMZ': 'systemz', 'S390': 'systemz', 'SPARCV9': 'sparcv9', 'HEXAGON': 'hexagon', 'WASM32': 'wasm32', 'WASM64': 'wasm64'}
    arch = arch_map.get(machine_type, 'unknown')
    if 'mips' in arch and endianness == 'LSB':
        arch = arch.replace('mips', 'mipsel')
    elif 'ppc' in arch and endianness == 'LSB':
        arch += 'le'
    elif 'aarch64' in arch and endianness == 'MSB':
        arch = 'aarch64_be'
    elif 'arm' in arch and endianness == 'MSB':
        arch = 'armeb'
    binary_type = metadata.get('binary_type')
    if binary_type == 'PE':
        os_str = 'windows'
        vendor = 'pc'
    elif binary_type == 'MachO':
        vendor = 'apple'
        platform = metadata.get('platform', 'MACOS').upper()
        os_map = {'MACOS': 'macosx', 'IOS': 'ios', 'TVOS': 'tvos', 'WATCHOS': 'watchos', 'BRIDGEOS': 'bridgeos', 'DRIVERKIT': 'driverkit'}
        os_str = os_map.get(platform, 'darwin')
    elif binary_type == 'ELF':
        vendor = 'unknown'
        os_abi = metadata.get('identity_os_abi', 'LINUX').upper()
        os_map = {'LINUX': 'linux', 'SYSTEMV': 'linux', 'FREEBSD': 'freebsd', 'NETBSD': 'netbsd', 'OPENBSD': 'openbsd', 'SOLARIS': 'solaris'}
        os_str = os_map.get(os_abi, 'linux')
    if metadata.get('is_targeting_android'):
        os_str = 'linux'
        env = 'android'
    elif os_str == 'windows':
        env = 'msvc'
    elif os_str == 'linux':
        if metadata.get('is_musl'):
            env = 'musl'
            interpreter = metadata.get('interpreter', '')
            if '-sf.so' in interpreter:
                env = 'muslsf'
            elif arch == 'arm':
                if 'hard' in metadata.get('processor_flag', '').lower() or '-hf.so' in interpreter:
                    env = 'musleabihf'
                else:
                    env = 'musleabi'
            elif arch == 'mips64' or arch == 'mips64el':
                env = 'muslabi64'
        else:
            env = 'gnu'
            if arch.startswith('arm') and 'hard' in metadata.get('processor_flag', '').lower():
                env = 'gnueabihf'
    components = [arch, vendor, os_str]
    if env:
        components.append(env)
    return '-'.join(components)

def _is_single_value(value):
    """
    Check if a value is a single numeric value or a single character.

    Parameters:
    -----------
        value (int, float, str): The value to be checked.

    Returns:
    --------
        bool: True if the value is a single numeric value or a single character, False otherwise.
    """
    if isinstance(value, (int, float, str)):
        if isinstance(value, (int, float)):
            return True
        elif isinstance(value, str):
            if len(value) == 1 and value.isdigit():
                return True
            else:
                return False
    return False

def _import_optional(name):
    """Import a module, or None if it is absent.

    Not a bare `try: import cuda`. The cuda-python distribution installs `cuda`
    as an implicit namespace package, so that import succeeds even when nothing
    is installed under it, leaving an empty module whose __file__ is None. The
    caller would then fail later with AttributeError instead of a clean skip.
    """
    import importlib
    import importlib.util
    try:
        spec = importlib.util.find_spec(name)
    except (ImportError, ValueError):
        return None
    if spec is None or spec.origin is None:
        return None
    try:
        return importlib.import_module(name)
    except ImportError:
        return None

def nexussearch(find, tree, name=[], Whole=False, Case=False):
    """
    Search nexus tree for named value
        addresses, values = nexussearch('Energy', Whole=False, Case=False)

    Returns list of nexus addresses and the associated value
    """
    outnames = []
    outvals = []
    try:
        for branch in tree.keys():
            branchname = name + [branch]
            if find == '*' or (Whole and Case and (find == branch)) or (Whole and (not Case) and (find.lower() == branch.lower())) or (not Whole and Case and (find in branch)) or (not Whole and (not Case) and (find.lower() in branch.lower())):
                try:
                    val = tree[branch][()]
                    if np.prod(val.shape) > 1:
                        pval = val.shape
                    else:
                        pval = val.reshape(-1)[0]
                    pname = '/'.join(branchname)
                    outnames += [pname]
                    outvals += [pval]
                    continue
                except AttributeError:
                    pass
            (pname, pval) = nexussearch(find, tree[branch], branchname)
            outnames += pname
            outvals += pval
    except AttributeError:
        return (outnames, outvals)
    return (outnames, outvals)

def transfer_data_to_cpu(data_map: dict) -> dict:
    """ Transfer tensors in data_map to cpu device.
    Will recursively walk through inner list, tuple and dict values.

    Args:
        data_map (dict): a dictionary which contains tensors to be transferred

    Returns:
        A dict which has same structure with input `data_map`.
    """
    if not isinstance(data_map, dict):
        return data_map
    ret = OrderedDict()
    for (key, value) in data_map.items():
        if isinstance(value, torch.Tensor):
            ret[key] = value.detach().cpu()
        elif isinstance(value, dict):
            ret[key] = transfer_data_to_cpu(value)
        elif isinstance(value, (list, tuple)):
            ret[key] = type(value)([transfer_data_to_cpu(t) for t in value])
        else:
            ret[key] = value
    torch.cuda.empty_cache()
    return ret

def newshape(s, lowdim=0):
    """
    Given a shape s, calculate the shape of a new array with the
    lowest dimension replaced.  If lowdim is zero the lowest dimension
    is removed, otherwise it is replaced.
    """
    sl = list(s)
    if lowdim == 0:
        sl.pop()
    else:
        sl[-1] = lowdim
    return tuple(sl)

def _extract_preferred_field(data, id_or_value):
    """In case the preferred representation of data when the latter has multiple representations"""
    if not id_or_value:
        return data
    if not data:
        return ''
    if isinstance(data, dict):
        if id_or_value in data:
            return data[id_or_value]
    if isinstance(data, list):
        return ','.join([_extract_preferred_field(i, id_or_value) for i in data])
    return data

def _parse_pos(raw):
    """Normalize a FlowView position return into (x, y) floats, or None.

    Depending on the bridge, position reads come back as a 1-indexed Lua table,
    a dict ({1: x, 2: y} / {"x": .., "y": ..}), or an (x, y) tuple/list. Be
    liberal in what we accept.
    """
    if raw is None:
        return None
    if isinstance(raw, dict):
        for (ka, kb) in ((1, 2), ('1', '2'), ('x', 'y'), ('X', 'Y')):
            if ka in raw and kb in raw:
                try:
                    return (float(raw[ka]), float(raw[kb]))
                except (TypeError, ValueError):
                    return None
        vals = list(raw.values())
        if len(vals) >= 2:
            try:
                return (float(vals[0]), float(vals[1]))
            except (TypeError, ValueError):
                return None
        return None
    if isinstance(raw, (list, tuple)):
        if len(raw) >= 2:
            try:
                return (float(raw[0]), float(raw[1]))
            except (TypeError, ValueError):
                return None
        return None
    try:
        return (float(raw[1]), float(raw[2]))
    except Exception:
        return None

def _matches_detail(detail, pattern):
    """Match one ``$or``-free alternative against an object. Every ``$or`` is
    gone by the time this runs — ``_compile_pattern`` expanded it — so this is a
    plain AND over the pattern's keys."""
    if isinstance(pattern, dict) and _UNSATISFIABLE in pattern:
        return False
    if not isinstance(pattern, dict) or not pattern:
        return False
    for (key, expected) in pattern.items():
        present = isinstance(detail, dict) and key in detail
        actual = detail.get(key) if isinstance(detail, dict) else None
        if isinstance(expected, list):
            scalars = _flatten(actual, False) if present else []
            has_leaf = bool(scalars)
            exists_filters = [item for item in expected if isinstance(item, dict) and 'exists' in item]
            if exists_filters:
                if any((item['exists'] is has_leaf for item in exists_filters)):
                    continue
                if len(exists_filters) == len(expected):
                    return False
            if not present:
                return False
            if not any((_matches_alternatives(scalar, expected) for scalar in scalars)):
                return False
        elif isinstance(expected, dict):
            candidates = _flatten(actual, True) or [{}]
            if not any((_matches_detail(candidate, expected) for candidate in candidates)):
                return False
        else:
            return False
    return True

def _extract_c_block(text: str, opening_brace: int) -> str | None:
    """Return a balanced C block, including its braces."""
    if opening_brace >= len(text) or text[opening_brace] != '{':
        return None
    depth = 0
    for index in range(opening_brace, len(text)):
        char = text[index]
        if char == '{':
            depth += 1
        elif char == '}':
            depth -= 1
            if depth == 0:
                return text[opening_brace:index + 1]
    return None

def resolve(d):
    """Collapse a dimensionWithTolerance to a scalar: nominal -> mid -> max -> min.

    Mirrors MKF's resolve_dimensional_values. Returns None when the value carries no
    bound at all; callers treat that as 'not specified', never as zero.
    """
    if isinstance(d, bool):
        return None
    if isinstance(d, (int, float)):
        return float(d)
    if not isinstance(d, dict):
        return None
    if d.get('nominal') is not None:
        return float(d['nominal'])
    (mn, mx) = (d.get('minimum'), d.get('maximum'))
    if mn is not None and mx is not None:
        return (float(mn) + float(mx)) / 2.0
    if mx is not None:
        return float(mx)
    if mn is not None:
        return float(mn)
    return None

def _regipy_value_to_bytes(value: object) -> bytes | None:
    """Convert a regipy registry value to raw bytes.

    regipy returns REG_BINARY values as hex strings rather than raw bytes.
    This helper normalizes the value to bytes for struct parsing.
    """
    if isinstance(value, bytes):
        return value
    if isinstance(value, str):
        try:
            return bytes.fromhex(value)
        except ValueError:
            return None
    return None

def _compute_dfd_type_layers(scope_data):
    """Fallback layer derivation: group Section 1 components by DFD type when no trust zones exist."""
    components = scope_data.get('components', [])
    if not components:
        return None
    by_type = {}
    for comp in components:
        ctype = (comp.get('type') or '').strip()
        cname = (comp.get('name') or '').strip()
        if not ctype or not cname:
            continue
        by_type.setdefault(ctype, []).append(cname)
    if not by_type:
        return None
    layers = []
    for (position, ctype) in enumerate(sorted(by_type.keys())):
        comp_names = sorted(by_type[ctype])
        if not comp_names:
            continue
        layers.append({'name': ctype, 'position': position, 'components': comp_names, 'component_count': len(comp_names), 'source_kind': 'dfd_type'})
    return layers if layers else None

@staticmethod
def _ramp(val: float, pos_key: bool, neg_key: bool, inc: float, upper: float, lower: float=None) -> float:
    """Bidirectional ramp with upper/lower bounds. Holds current value when keys released."""
    if lower is None:
        lower = -upper
    if pos_key and (not neg_key):
        return min(upper, val + inc)
    if neg_key and (not pos_key):
        return max(lower, val - inc)
    return val

def remove_empty_track(midi_file):
    """
    1. read pretty midi data
    2. remove emtpy track,
    also remove track with fewer than 10% notes of the track
    with most notes

    ********
    Return: pretty_midi object, pypianoroll object
    """
    try:
        pretty_midi_data = pretty_midi.PrettyMIDI(midi_file)
    except Exception as e:
        print(f'exceptions in read the file {midi_file}')
        return (None, None)
    pypiano_data = pypianoroll.Multitrack()
    try:
        pypiano_data.parse_pretty_midi(pretty_midi_data, skip_empty_tracks=False)
    except Exception as e:
        print(f'exceptions for pypianoroll in read the file {midi_file}')
        return (None, None)
    drum_idx = []
    for (i, instrument) in enumerate(pretty_midi_data.instruments):
        if instrument.is_drum:
            drum_idx.append(i)
    note_count = [np.count_nonzero(np.any(track.pianoroll, axis=1)) for track in pypiano_data.tracks]
    empty_indices = np.array(note_count) < 10
    remove_indices = np.arange(len(pypiano_data.tracks))[empty_indices]
    for index in sorted(remove_indices, reverse=True):
        del pypiano_data.tracks[index]
        del pretty_midi_data.instruments[index]
    return (pretty_midi_data, pypiano_data)

def _selector_selected(comp):
    """The live variant of a Selector (Avid enabled/disabled layer variants).

    This is the AAF `Selected` PROPERTY — pyaaf2 does not expose it as a `.selected`
    python attribute, so read it via getvalue()/[] first and only then fall back.
    """
    for getter in (lambda c: c.getvalue('Selected'), lambda c: c['Selected'].value, lambda c: getattr(c, 'selected', None)):
        try:
            v = getter(comp)
            if v is not None:
                return v
        except Exception:
            pass
    return None

def _platform_supported(mod) -> bool:
    """True if *mod* declares no PLATFORMS attribute, or the current
    ``sys.platform`` matches one of its declared prefixes. Lets a
    scenario opt out of OSes where its connect path doesn't apply
    (e.g. bl_connect_local on macOS/Windows, bl_connect_win_native on
    Linux/macOS)."""
    plats = getattr(mod, 'PLATFORMS', None)
    if plats is None:
        return True
    return any((sys.platform.startswith(p) for p in plats))

def _find_integration(skill: dict, integration_id: str) -> dict | None:
    """Return the integrations[] entry with id == integration_id, or None."""
    for i in skill.get('integrations') or []:
        if i.get('id') == integration_id:
            return i
    return None

def str2size(s, scale=1024):
    """Convert size-string.

    String format: <value>[:space:]<B | K | M | ...> to bytes.

    :param s: size-string
    :param scale: base size
    """
    if not s:
        return 0
    if isinstance(s, int):
        return s
    match = re.match('^([\\.\\d]+)\\s*([BbKkMmGgTtPpEeZzYy]?)', s)
    if match is None:
        raise ValueError(_('Invalid value: %(value)s') % {'value': s})
    groups = match.groups()
    value = float(groups[0])
    suffix = groups[1].upper() if groups[1] else 'B'
    types = ('B', 'K', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y')
    for (i, t) in enumerate(types):
        if suffix == t:
            return int(value * pow(scale, i))

def extract_vulns_for_file(results, target_file):
    """Extract list of (cvi_id, lineno, is_inconclusive) from scan results for a specific file."""
    if not results:
        return []
    vulns = []
    items = []
    if isinstance(results, list):
        items = results
    elif isinstance(results, dict):
        for key in ('results', 'vulnerabilities', 'data'):
            if key in results and isinstance(results[key], list):
                items = results[key]
                break
    for item in items:
        if not isinstance(item, dict):
            continue
        file_val = item.get('file') or item.get('file_path') or item.get('file_name') or ''
        if target_file in file_val:
            cvi = item.get('cvi_id') or item.get('cvi') or item.get('vuln_class') or ''
            cvi_str = str(cvi)
            if cvi_str.isdigit():
                cvi_str = 'CVI-' + cvi_str
            lineno = None
            if ':' in str(file_val):
                parts = str(file_val).rsplit(':', 1)
                if parts[-1].isdigit():
                    lineno = int(parts[-1])
            result_type = item.get('result_type') or item.get('type') or ''
            is_inconclusive = 'Inconclusive' in str(result_type)
            if 'CVI' in cvi_str:
                vulns.append((cvi_str, lineno, is_inconclusive))
    return vulns

def _is_base64_blob(s: str) -> bool:
    """True if s looks like an embedded base64 blob rather than a path/URL.
    A filesystem path contains '.' (e.g. extensions) which is not a base64 char,
    so this also distinguishes base64 JPEG (starts with '/9j/') from real paths."""
    if len(s) < 64:
        return False
    return all((c in _B64_CHARS for c in s[:256]))

@staticmethod
def strip_textpad(text):
    """
        Attempt to intelligently strip excess whitespace from the output of a
        curses textpad.
        """
    if text is None:
        return text
    if '\n' not in text:
        return text.rstrip()
    (stack, current_line) = ([], '')
    for line in text.split('\n'):
        if line.endswith('  ') or not line:
            stack.append(current_line + line.rstrip())
            current_line = ''
        else:
            current_line += line
    stack.append(current_line)
    for item in stack[::-1]:
        if not item:
            stack.pop()
        else:
            break
    out = '\n'.join(stack)
    return out

def powmod(a, b, c):
    """
    Uses GMP, if available, to do a^b mod c where a, b, c
    are integers.

    :return int: (a ** b) % c
    """
    if a == 1:
        return 1
    if not HAVE_GMP or max(a, b, c) < _USE_MOD_FROM_GMP_SIZE:
        return pow(a, b, c)
    else:
        return int(gmpy2.powmod(a, b, c))

def get_test_id(data):
    """
    Method to retrieve test_id
    :param data:
    :return:
    """
    test_id = ''
    if 'rule_set' in data:
        test_id = data['rule_set']
    if 'test_id' in data:
        test_id = data['test_id']
    if 'rule_id' in data:
        test_id = data['rule_id']
    if 'check_name' in data:
        test_id = data['check_name']
    if 'check_id' in data:
        test_id = data['check_id']
    if 'tag' in data:
        test_id = data['tag']
    if 'commitMessage' in data and 'commit' in data:
        test_id = 'CWE-312'
    if 'type' in data:
        test_id = data['type']
    if 'cwe' in data:
        cwe_obj = data['cwe']
        if isinstance(cwe_obj, str):
            test_id = cwe_obj
        if isinstance(cwe_obj, dict):
            tmp_id = cwe_obj.get('ID')
            if not tmp_id:
                tmp_id = cwe_obj.get('id')
            if tmp_id:
                test_id = tmp_id
        if not test_id.startswith('CWE') and test_id.isdigit():
            test_id = 'CWE-' + test_id
    if not test_id and 'code' in data and data.get('code'):
        if str(data.get('code')).isdigit():
            test_id = str(data['code'])
        elif len(data.get('code').split()) == 1:
            test_id = data.get('code')
    return test_id

def is_true(value=None):
    """
    Returns a boolean value representing the "truth" of the value passed. The
    rules for what is a "True" value are:

        1. Integer/float values greater than 0
        2. The string values "True" and "true"
        3. Any object for which bool(obj) returns True
    """
    try:
        value = int(value)
    except (ValueError, TypeError):
        pass
    try:
        value = float(value)
    except (ValueError, TypeError):
        pass
    if isinstance(value, (int, float)):
        return value > 0
    elif isinstance(value, str):
        return str(value).lower() == 'true'
    else:
        return bool(value)

def config_positive_float_value(value):
    """
    Returns positive float value if it can be cast by float() and it's a
    float > 0. (not including zero) Raises ValueError otherwise.
    """
    try:
        result = float(value)
        if result <= 0:
            raise ValueError()
    except (TypeError, ValueError):
        raise ValueError('Config option must be a positive float number, not "%s".' % value)
    return result

def _format_tokens(input_tokens: int, output_tokens: int) -> str:
    """Humanise token counts as '1.2M tokens (↑890K / ↓355K)'. Returns '' when both are zero."""
    total = input_tokens + output_tokens
    if total == 0:
        return ''

    def _fmt(n: int) -> str:
        if n >= 1000000:
            return f'{n / 1000000:.1f}M'
        if n >= 1000:
            return f'{n / 1000:.0f}K'
        return str(n)
    return f'{_fmt(total)} tokens (↑{_fmt(input_tokens)} / ↓{_fmt(output_tokens)})'

def _diagnostic_preview(message: str, limit: int=240) -> str:
    """Return one compact CLI preview while the report retains full detail."""
    compact = ' '.join(message.split())
    if len(compact) <= limit:
        return compact
    return compact[:limit - 3].rstrip() + '...'

def count_ast(ast):
    """Walk the pandoc AST. Return (real_cite_groups, images, tables, math).
    real_cite_groups = number of Cite nodes containing >=1 real citekey (each becomes ONE Zotero
    field downstream, mirroring zotero_offline.lua's one-field-per-Cite behaviour)."""
    cnt = {'cite': 0, 'image': 0, 'table': 0, 'math': 0}

    def walk(x):
        if isinstance(x, dict):
            t = x.get('t')
            if t == 'Cite':
                ids = [c.get('citationId') for c in x['c'][0]]
                if any((_is_real_key(i) for i in ids)):
                    cnt['cite'] += 1
            elif t == 'Image':
                cnt['image'] += 1
            elif t == 'Table':
                cnt['table'] += 1
            elif t == 'Math':
                cnt['math'] += 1
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)
    walk(ast)
    return (cnt['cite'], cnt['image'], cnt['table'], cnt['math'])

def _matches(url: str, filters: list[str]) -> bool:
    """Return True if url contains at least one of the filter substrings (or no filters set)."""
    if not filters:
        return True
    return any((f in url for f in filters))

@staticmethod
def _get_mode_parameters(mode):
    """ Return the correst TraCI parameters for the requested mode.
            Parameters: _mode, _ptype, _vtype
        """
    if mode == 'public':
        return ('public', '', '')
    if mode == 'bicycle':
        return ('bicycle', '', 'bicycle')
    if mode == 'walk':
