def _attr_candidate_values(attr: dict) -> list:
    """Values to match a message attribute against a filter policy. A scalar
    attribute yields its single StringValue; a String.Array yields each element
    (AWS matches an array attribute when any element matches)."""
    raw = attr.get('StringValue', '')
    if (attr.get('DataType') or '').strip() != 'String.Array':
        return [raw]
    try:
        parsed = json.loads(raw)
    except (json.JSONDecodeError, TypeError):
        return [raw]
    if not isinstance(parsed, list):
        return [raw]
    values = []
    for element in parsed:
        if isinstance(element, bool):
            values.append('true' if element else 'false')
        elif isinstance(element, str):
            values.append(element)
        elif isinstance(element, (int, float)):
            values.append(str(element))
    return values or [raw]

def index_dispatch_edges(path):
    """Return host-op -> dispatched GPU kernels using profiler External ids.

    TraceLens may report one aggregate host/custom-op row whose percentage is the sum of several
    kernels.  Such a row is useful context but it is not a kernel-selection candidate.  This index
    provides the machine-observed children needed to split it before strategizing.
    """
    try:
        with _open(path) as fh:
            data = json.load(fh)
    except Exception:
        return {}
    events = data.get('traceEvents', data if isinstance(data, list) else [])
    host_by_ext = {}
    spans_by_thread = {}
    for event in events:
        if not isinstance(event, dict) or event.get('cat') not in ('cpu_op', 'user_annotation'):
            continue
        ext = (event.get('args') or {}).get('External id')
        if ext is not None:
            host_by_ext.setdefault(ext, set()).add(event.get('name', '?'))
        if ext is not None and event.get('ts') is not None:
            start = float(event['ts'])
            end = start + float(event.get('dur') or 0.0)
            spans_by_thread.setdefault((event.get('pid'), event.get('tid')), []).append((start, end, event.get('name', '?'), ext))
    for spans in spans_by_thread.values():
        stack = []
        for (start, end, name, ext) in sorted(spans, key=lambda item: (item[0], -item[1])):
            while stack and stack[-1][0] <= start:
                stack.pop()
            names = host_by_ext.setdefault(ext, set())
            names.add(name)
            names.update((parent_name for (_, parent_name) in stack))
            stack.append((end, name))
    edges = {}
    for event in events:
        if not isinstance(event, dict) or event.get('cat') != 'kernel':
            continue
        ext = (event.get('args') or {}).get('External id')
        hosts = host_by_ext.get(ext) or ()
        for host in hosts:
            child = edges.setdefault(host, {}).setdefault(event.get('name', '?'), {'calls': 0, 'total_us': 0.0})
            child['calls'] += 1
            child['total_us'] += float(event.get('dur') or 0.0)
    return edges

def process_record(record: dict) -> tuple[dict, bool, str | None]:
    """
    Process a single training record, canonicalizing the CXSMILES if present.

    Args:
        record: Training record dict with 'messages' list

    Returns:
        Tuple of (processed_record, was_changed, error_message)
    """
    for msg in record.get('messages', []):
        if msg.get('role') == 'assistant':
            content = msg.get('content', '')
            cxsmiles = extract_cxsmiles_from_content(content)
            if cxsmiles is None:
                return (record, False, 'no_cxsmiles')
            result = canonicalize_cxsmiles_checked(cxsmiles)
            if result.value is None:
                return (record, False, result.error or f'parse_failed: {cxsmiles[:100]}')
            if result.fallback:
                return (record, False, f'verify_failed: {result.error}')
            canonical = result.value
            if cxsmiles == canonical:
                return (record, False, None)
            new_content = replace_cxsmiles_in_content(content, canonical)
            msg['content'] = new_content
            return (record, True, None)
    return (record, False, 'no_assistant_message')

def execute(work_order: dict) -> dict:
    """执行层主入口——接收工单 → 检索 → 推理 → 返回结果

    Args:
        work_order: 来自助理层的已审查工单

    Returns:
        {"status": "ok|error", "response": "...", "retrieved": [...], "level": int}
    """
    clean_query = work_order.get('order', {}).get('clean', '')
    intent = work_order.get('order', {}).get('intent', 'chat')
    task_type = work_order.get('order', {}).get('task_type', 'chat')
    if not clean_query:
        return {'status': 'error', 'response': '工单内容为空'}
    retrieved = []
    response = ''
    used_level = 0
    cached = level0_hot(clean_query)
    if cached:
        return {'status': 'ok', 'response': cached, 'retrieved': [], 'level': 0, 'source': 'hot_cache'}
    if task_type in ('info_search', 'analysis', 'code'):
        retrieved = level2_pgvector(clean_query)
        if retrieved:
            used_level = 2
    work_order['retrieved'] = retrieved
    response = level3_factory(clean_query, work_order)
    used_level = 3 if not retrieved else 2
    return {'status': 'ok', 'response': response, 'retrieved': retrieved, 'level': used_level, 'source': 'factory_api'}

def _get_dimension_criteria(dimension: str) -> list[str]:
