    """
    criteria_map = {'completeness': ['has_all_required_steps', 'addresses_all_query_aspects', 'handles_edge_cases', 'includes_fallback_path'], 'efficiency': ['minimizes_redundant_calls', 'uses_appropriate_agents', 'optimizes_cost', 'optimizes_latency'], 'safety': ['validates_inputs', 'handles_errors_gracefully', 'has_timeout_protection', 'avoids_risky_combinations'], 'coherence': ['logical_agent_sequence', 'proper_data_flow', 'no_conflicting_actions']}
    return criteria_map.get(dimension, [])

def normalize_arxiv_id(value: str) -> str:
    """
    统一将可能携带 URL 的 arXiv 输入转换为 id。
    兼容：
    - 1706.03762
    - 1706.03762v1
    - https://arxiv.org/abs/1706.03762v1
    """
    raw = (value or '').strip()
    if not raw:
        return ''
    if raw.startswith('http://') or raw.startswith('https://'):
        raw = raw.rsplit('/', 1)[-1]
    raw = raw.split('?')[0]
    if raw.startswith('abs/'):
        raw = raw[len('abs/'):]
    if raw.startswith('pdf/'):
        raw = raw[len('pdf/'):].replace('.pdf', '')
    return raw.strip().lower()

def lprmap(data, key, value, valtype=None):
    """
    Return mapped Line Protocol formatted key/value pair string, if value found in data
    """
    if value in data:
        if valtype == 'float':
            v = float(data[value])
        elif valtype == 'int':
            v = int(data[value])
        elif valtype == 'str':
            v = str(data[value])
        else:
            v = data[value]
        return f',{key}={lpr(v)}'
    return ''

def inspect_jwt_bfs(token: str) -> dict:
    """Detect xAI JWT risk claim ``bfs`` by key presence (not truthiness).

    Clean tokens simply omit the claim. Flagged tokens typically carry
    ``bfs: 2`` (value may vary; presence alone is the signal).
    Distinct from grok.com ``botFlagSource`` / registration policy deny.
    """
    raw = str(token or '').strip()
    if raw.startswith('sso='):
        raw = raw[4:].strip()
    if raw.startswith('{'):
        try:
            obj = json.loads(raw)
        except Exception:
            obj = None
        if isinstance(obj, dict):
            for key in ('access_token', 'token', 'sso', 'id_token', 'key'):
                nested = str(obj.get(key) or '').strip()
                if nested.count('.') >= 2:
                    raw = nested
                    break
    (ok, claims) = _decode_jwt_payload_with_status(raw) if raw.count('.') >= 2 else (False, {})
    has = ok and 'bfs' in claims
    return {'ok': ok, 'has_bfs': has, 'bfs': claims.get('bfs') if has else None, 'tier': claims.get('tier'), 'sub': str(claims.get('sub') or claims.get('principal_id') or '')[:48], 'exp': claims.get('exp'), 'referrer': claims.get('referrer'), 'claim_keys': sorted((str(k) for k in claims.keys())) if claims else []}

def safeRenderTemplate(error, *args, **kwargs):
    """If error is empty, return rendered template from *args and **kwargs.
    Otherwise return empty string, if exception appear return empty string."""
    if error != {}:
        return ''
    try:
        return render_template(*args, **kwargs)
    except jinja2.exceptions.TemplateNotFound as e:
        error.setdefault('Template Error', []).append('Request template: "{0}", but it was not found!'.format(e.name))
        return ''

def get_async_or_sync_fn(fn):
    """Returns an async function for the specified fn, if it exists; otherwise returns source."""
    if hasattr(fn, 'asynq'):
        return fn.asynq
    if hasattr(fn, 'async'):
        return getattr(fn, 'async')
    return fn

def analyze_layer_transitions(tracks: dict, vias: dict, net_names: dict[int, str], power_rails: set[str] | None=None) -> list[dict]:
    """Identify signal net layer transitions (via usage patterns).

    For ground return path analysis, higher-level logic needs to know which
    signal nets change layers and where. A via forces the return current to
    find a path between layers — if there's no nearby stitching via on the
    reference plane, the return current loop area increases, raising EMI.

    Reports per-net: which layers are used, how many vias, and whether the
    net uses more than one copper layer (indicating layer transitions).
    """
    net_layers: dict[int, dict] = {}
    for seg in tracks.get('segments', []):
        net = seg['net']
        if net <= 0:
            continue
        d = net_layers.setdefault(net, {'layers': set(), 'vias': []})
        d['layers'].add(seg['layer'])
    for arc in tracks.get('arcs', []):
        net = arc['net']
        if net <= 0:
            continue
        d = net_layers.setdefault(net, {'layers': set(), 'vias': []})
        d['layers'].add(arc['layer'])
    for via in vias.get('vias', []):
        net = via['net']
        if net <= 0 or net not in net_layers:
            continue
        net_layers[net]['vias'].append({'x': via['x'], 'y': via['y'], 'layers': via.get('layers', ['F.Cu', 'B.Cu']), 'drill': via.get('drill', 0)})
    result = []
    for (net_num, data) in sorted(net_layers.items()):
        if len(data['layers']) < 2:
            continue
        name = net_names.get(net_num, f'net_{net_num}')
        if is_power_net_name(name, power_rails) or is_ground_name(name):
            continue
        entry = {'net': name, 'net_number': net_num, 'copper_layers': sorted(data['layers']), 'layer_count': len(data['layers']), 'via_count': len(data['vias'])}
        if data['vias']:
            entry['via_positions'] = [{'x': round(v['x'], 2), 'y': round(v['y'], 2), 'layers': v['layers']} for v in data['vias']]
        result.append(entry)
    result.sort(key=lambda e: e['via_count'], reverse=True)
    return result

def bytes_to_str(value):
    """Covert an integer (in bytes) into it's string representation with
    acompanied unit value (such as B, KB, MB, GB, TB, etc)"""
    unit = 'B'
    try:
        value = float(value)
    except (ValueError, TypeError):
        return None
    if value >= 1024.0:
        value = value / 1024.0
        unit = 'KB'
        if value >= 1024.0:
            value = value / 1024.0
            unit = 'MB'
            if value >= 1024.0:
                value = value / 1024.0
                unit = 'GB'
                if value >= 1024.0:
                    value = value / 1024.0
                    unit = 'TB'
    return f'{round(value, 2):.2f}{unit}'

def validate_ms(value: int | str) -> str:
    """
    Normalize milliseconds value for config storage.
    Always stored as '<int>ms', non-negative.
    """
    if isinstance(value, int):
        if value < 0:
            raise ValueError('Milliseconds must be non-negative.')
        return f'{value}ms'
    if isinstance(value, str):
        v = value.strip().lower().replace(' ', '')
        if v.endswith('ms'):
            v = v[:-2]
        try:
            n = int(v)
        except ValueError as e:
            raise ValueError(f'Invalid millisecond value: {value!r}') from e
        if n < 0:
            raise ValueError('Milliseconds value must be non-negative.')
        return f'{n}ms'
    raise ValueError(f"Invalid millisecond value: '{value}'")

def get_lr_trapezoidal(step, num_step, warmup_iters=256, cooldown_frac=0.4):
    """Trapezoidal schedule from modded-nanogpt 844e5fd.

    Linear warmup, constant plateau, then linear warmdown to zero.
    Returns a multiplier in [0, 1] applied to the base learning rate.
    """
    if step < warmup_iters:
        return (step + 1) / warmup_iters
    return get_lr(step, num_step, cooldown_frac)

def locate_xy(xy0, xy1, location):
    """
    Find a corresponding xy coordinate from location parameters 

    Parameters
    ----------
    xy0 : np.array([float, float])
        first coordinate
    xy1 : np.array([float, float])
        second coordinate
    location : str
        direction/projection parameter. Possible values are 'lowerLeft', 'upperRight', 'centerCenter', ...

    Returns
    -------
    np.array([float, float])
        resulting coordinate
    """
    if location == 'lowerLeft':
        return np.array(xy0)
    if location == 'lowerRight':
        return np.array([xy1[0], xy0[1]])
    if location == 'upperLeft':
        return np.array([xy0[0], xy1[1]])
    if location == 'upperRight':
        return np.array(xy1)
    if location == 'centerCenter':
        return np.array(0.5 * xy0 + 0.5 * xy1)

def merge_categories(cat_sets: set, fallback: str) -> str:
    """Collapse a set of "a,b" category strings into one sorted, de-duped
    comma list. Falls back to `fallback` when nothing was mapped."""
    ids = set()
    for c in cat_sets:
        for part in c.split(','):
            part = part.strip()
            if part.isdigit():
                ids.add(int(part))
    if not ids:
        for part in fallback.split(','):
            part = part.strip()
            if part.isdigit():
                ids.add(int(part))
    return ','.join((str(i) for i in sorted(ids))) or '15'

def _convert_weight_key(key: str, model: 'PreTrainedModel') -> str:
    """
    Convert a single state dict key using the model's checkpoint conversion mapping.

    For example, in the InternVL, we have _checkpoint_conversion_mapping = {"^model": "language_model"}

    This is to adapt to the big breaking change introduced in HF transformers 4.52:
    https://github.com/huggingface/transformers/pull/38385
    """
    if not hasattr(model, '_checkpoint_conversion_mapping'):
        return key
    for (pattern, replacement) in model._checkpoint_conversion_mapping.items():
        replacement = replacement.lstrip('^')
        replacement = re.sub('\\(.*\\)', '', replacement)
        (converted_key, n_replace) = re.subn(pattern, replacement, key)
        if n_replace > 0:
            return converted_key
    return key

def _product_byte_size(props: dict) -> int | None:
    """Byte size of the main product file (the one ``download()`` fetches).

    S1/ALOS expose ``bytes`` as an int. NISAR exposes a dict mapping every file
    in the granule to ``{'bytes': N, 'format': ...}``; return the entry for the
    file we actually download (``fileName`` == the ``url`` basename), falling
    back to the sum of all entries.
    """
    raw = props.get('bytes')
    if isinstance(raw, bool):
        return None
    if isinstance(raw, (int, float)):
        return int(raw)
    if isinstance(raw, dict):
        filename = props.get('fileName')
        if filename:
            entry = raw.get(filename)
            if isinstance(entry, dict) and isinstance(entry.get('bytes'), (int, float)):
                return int(entry['bytes'])
        total = 0
        for v in raw.values():
            if isinstance(v, dict) and isinstance(v.get('bytes'), (int, float)):
                total += int(v['bytes'])
        return total or None
    return None

def _prune_none_for_apigw_json(obj):
    """Drop None members so the wire never emits JSON `null` (real AWS typically omits optional nulls;
    boto3 then maps the same shape for clients as AWS). Recurses into dict values."""
    if isinstance(obj, dict):
        return {k: _prune_none_for_apigw_json(v) for (k, v) in obj.items() if v is not None}
    if isinstance(obj, list):
        return [_prune_none_for_apigw_json(x) for x in obj]
    return obj

@staticmethod
def _bisect_left(a, x, lo=0, key=None):
    """Polyfill for bisect.bisect_left with key argument
    TODO: replace with standard library version when Python 3.10+ is minimum requirement
    """
    if lo < 0:
        raise ValueError('lo must be non-negative')
    hi = len(a)
    if key is None:
        key = lambda v: v
    while lo < hi:
        mid = (lo + hi) // 2
        v = key(a[mid])
        if v is not None and v < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def parse_hhr_hits(hhr_text: str, max_hits: int | None=None) -> list[tuple[str, float, str]]:
    """Parse the hit table of an HHsearch ``.hhr`` report.

    Returns ``(template_id, probability, evalue)`` tuples for each row of the
    ``No Hit ...`` table, with the template id normalized (extension stripped)
    and truncated to ``max_hits`` when given.
    """
    hits: list[tuple[str, float, str]] = []
    in_table = False
    for line in hhr_text.splitlines():
        if line.startswith(' No Hit'):
            in_table = True
            continue
        if in_table:
            if not line.strip():
                break
            m = _HHR_HIT_RE.match(line)
            if m:
                hits.append((normalize_tid(m.group(1)), float(m.group(2)), m.group(3)))
                if max_hits is not None and len(hits) >= max_hits:
                    break
    return hits

def formatValue(value, forceInt=False):
    """Return a clean string for a number: integer if whole (or forced), otherwise trimmed decimal."""
    rounded = round(value, 4)
    if forceInt or abs(rounded - round(rounded)) < 1e-09:
        return '%i' % round(rounded)
    return ('%f' % rounded).rstrip('0').rstrip('.')

def is_jid(jid):
