@staticmethod
def _merge_a_into_b(a, b):
    """merge dict `a` into dict `b` (non-inplace).
            values in `a` will overwrite `b`.
            copy first to avoid inplace modification

        Args:
            a ([type]): [description]
            b ([type]): [description]

        Returns:
            [dict]: [description]
        """
    if not isinstance(a, dict):
        return a
    b = b.copy()
    for (k, v) in a.items():
        if isinstance(v, dict) and k in b and (not v.pop(DELETE_KEY, False)):
            if not isinstance(b[k], dict) and (not isinstance(b[k], list)):
                raise TypeError(f'{k}={v} in child config cannot inherit from base because {k} is a dict in the child config but is of type {type(b[k])} in base config. You may set `{DELETE_KEY}=True` to ignore the base config')
            b[k] = Config._merge_a_into_b(v, b[k])
        elif isinstance(b, list):
            try:
                _ = int(k)
            except:
                raise TypeError(f'b is a list, index {k} should be an int when input but {type(k)}')
            b[int(k)] = Config._merge_a_into_b(v, b[int(k)])
        else:
            b[k] = v
    return b

def compare_dicts(old=None, new=None):
    """
    Compare before and after results from various salt functions, returning a
    dict describing the changes that were made.
    """
    ret = {}
    for key in set(new or {}).union(old or {}):
        if key not in old:
            ret[key] = {'old': '', 'new': new[key]}
        elif key not in new:
            ret[key] = {'new': '', 'old': old[key]}
        elif new[key] != old[key]:
            ret[key] = {'old': old[key], 'new': new[key]}
    return ret

def get_weight(stats):
    """
    Return a data point weight for the result.
    """
    if stats is None or 'ci_99_a' not in stats or 'ci_99_b' not in stats:
        return None
    try:
        a = stats['ci_99_a']
        b = stats['ci_99_b']
        if math.isinf(a) or math.isinf(b):
            return None
        return 2 / abs(b - a)
    except ZeroDivisionError:
        return None

def is_prime(number: int) -> bool:
    """
    Check if a number is prime.

    :param number: The number to check.
    :return: True if the number is prime, False otherwise.
    """
    if number <= 1:
        return False
    for i in range(2, int(number ** 0.5) + 1):
        if number % i == 0:
            return False
    return True

@staticmethod
def _remove_bdb_context(evalue):
    """Remove exception context from Pdb from the exception.

        E.g. "AttributeError: 'Pdb' object has no attribute 'do_foo'",
        when trying to look up commands (bpo-36494).
        Only done for Python 3+.
        """
    if not hasattr(evalue, '__context__'):
        return
    removed_bdb_context = evalue
    while removed_bdb_context.__context__:
        ctx = removed_bdb_context.__context__
        if isinstance(ctx, AttributeError) and ctx.__traceback__.tb_frame.f_code.co_name == 'onecmd':
            removed_bdb_context.__context__ = None
            break
        removed_bdb_context = removed_bdb_context.__context__

def naive_collate(batch):
    """Only collate dict value in to a list. E.g. meta data dict and img_info
    dict will be collated."""
    elem = batch[0]
    if isinstance(elem, dict):
        return {key: naive_collate([d[key] for d in batch]) for key in elem}
    else:
        return batch

