def _nth_str(n):
    """Return posessive form of numeral `n`: 1st, 2nd, 3rd, etc."""
    if n % 10 == 1 and n % 100 != 11:
        return '%dst' % n
    if n % 10 == 2 and n % 100 != 12:
        return '%dnd' % n
    if n % 10 == 3 and n % 100 != 13:
        return '%drd' % n
    return '%dth' % n

def filesize_display(num_bytes):
    """
    Return a human-readable filesize string in B, KB, MB, or GB.

    TODO: We may want an option here for number of decimal places or
    sig figs, since it's used for filesize limit displays. As a limit
    description, '30 MB' makes more sense than '30.00 MB'.
    """
    KILO = 1024
    MEGA = 1024 * 1024
    GIGA = 1024 * 1024 * 1024
    if num_bytes < KILO:
        return '{n} B'.format(n=num_bytes)
    if num_bytes < MEGA:
        return '{n:.2f} KB'.format(n=num_bytes / KILO)
    if num_bytes < GIGA:
        return '{n:.2f} MB'.format(n=num_bytes / MEGA)
    return '{n:.2f} GB'.format(n=num_bytes / GIGA)

def get_stream_range(num_streams, first_or_second):
    """get the range of stream numbers for the given number of total streams and the index of throughput test
    e.g. num_streams = 9, first_or_second = 1 => return [1,2,3,4]
    e.g. num_streams = 9, first_or_second = 2 => return [5,6,7,8]
    """
    if first_or_second == 1:
        stream_range = [x for x in range(1, num_streams // 2 + 1)]
    else:
        stream_range = [x for x in range(num_streams // 2 + 1, num_streams)]
    return stream_range

@staticmethod
def _previous_whitespace_token(text: str, end_index: int) -> str:
    """Return the whitespace-delimited token before *end_index*."""
    word_end = end_index
    while word_end > 0 and text[word_end - 1].isspace():
        word_end -= 1
    word_start = word_end
    while word_start > 0 and (not text[word_start - 1].isspace()):
        word_start -= 1
    return text[word_start:word_end]

def lint(source: str, strict: bool=False) -> list[str]:
    """Return a list of error strings (empty = pass)."""
    try:
        doc = load_doc(source)
    except Exception as e:
        return [f'[LOAD ERROR] {e}']
    errors = []
    collection_id = doc.get('id', source)
    for (asset_key, asset) in doc.get('assets', {}).items():
        mime = asset.get('type', '')
        if 'pmtiles' not in mime:
            continue
        vlayers = asset.get('vector:layers')
        if not vlayers:
            errors.append(f"[{collection_id}] asset '{asset_key}': PMTiles asset missing 'vector:layers' (the MapLibre source-layer id(s)).")
        columns = asset.get('table:columns')
        if not columns:
            errors.append(f"[{collection_id}] asset '{asset_key}': PMTiles asset has empty 'table:columns' — populate the tile-accurate fields from the .pmtiles footer (vector_layers[].fields). See data-workflows #283.")
            continue
        for col in columns:
            name = col.get('name', '')
            if not name:
                errors.append(f"[{collection_id}] asset '{asset_key}': a table:columns entry is missing 'name'.")
                continue
            if not col.get('type'):
                errors.append(f"[{collection_id}] asset '{asset_key}', column '{name}': missing 'type'.")
    return errors

def _message(error) -> str:
    """The sentence out of a JSON-RPC error object, wherever it was nested.

    flask_jsonrpc wraps an exception the view raised: the useful sentence is
    under 'data', and 'message' at the top is "Server error".
    """
    if isinstance(error, dict):
        data = error.get('data')
        if isinstance(data, dict) and data.get('message'):
            return str(data['message'])
        if error.get('message'):
            return str(error['message'])
    return str(error)

def generate_typescript_interface(name: str='TestInterface', properties: dict[str, str] | None=None, methods: dict[str, str] | None=None) -> str:
    """
    Generate TypeScript interface code.

    Args:
        name: Interface name
        properties: Dictionary of property name to type
        methods: Dictionary of method name to signature

    Returns:
        TypeScript interface code as string
    """
    if properties is None:
        properties = {}
    if methods is None:
        methods = {}
    lines = [f'interface {name} {{']
    for (prop, type_str) in properties.items():
        lines.append(f'  {prop}: {type_str};')
    for (method, signature) in methods.items():
        lines.append(f'  {method}{signature};')
    lines.append('}')
    return '\n'.join(lines)

def _redirect_target(fullname: str) -> str | None:
    """Return the target module path for a redirected ``tvm.script[...]`` name.

    Returns ``None`` if ``fullname`` is not a redirected name.
    """
    if fullname.startswith('tvm.script.'):
        rest = fullname[len('tvm.script.'):]
        (head, _, tail) = rest.partition('.')
        if head in _DIALECT_REGISTRY and '.' not in head:
            target = _DIALECT_REGISTRY[head]
            return f'{target}.{tail}' if tail else target
        for (prefix, sub) in _REDIRECTED_SUBPACKAGES.items():
            if fullname == prefix or not fullname.startswith(prefix + '.'):
                continue
            rest = fullname[len(prefix) + 1:]
            (head, _, tail) = rest.partition('.')
            if head in _DIALECT_REGISTRY:
                target = f'{_DIALECT_REGISTRY[head]}.{sub}'
                return f'{target}.{tail}' if tail else target
    return None

