  Args:
    left: Eqn for left tensor of eisnum eqn.
    right: Eqn for left tensor of eisnum eqn.

  Returns:
    Scale eqn.
  """
    eqn = []
    for ch in right:
        if ch in left:
            eqn.append(ch)
    return ''.join(eqn)

