def _manifest_display_size(meta: dict, ratio: float) -> tuple[int, int]:
    """Return a display-sized stand-in for vector media dimensions."""
    width_in = meta.get('display_width_in')
    height_in = meta.get('display_height_in')
    if isinstance(width_in, (int, float)) and isinstance(height_in, (int, float)):
        width = max(1, int(round(float(width_in) * 96)))
        height = max(1, int(round(float(height_in) * 96)))
        return (width, height)
    width_emu = meta.get('display_width_emu')
    height_emu = meta.get('display_height_emu')
    if isinstance(width_emu, int) and isinstance(height_emu, int):
        width = max(1, int(round(width_emu / 914400 * 96)))
        height = max(1, int(round(height_emu / 914400 * 96)))
        return (width, height)
    width = 960
    height = max(1, int(round(width / ratio)))
    return (width, height)

def convert_legacy_dyn_params(scene) -> str:
    """Convert every legacy entry to F-curves and clear the list.

    Returns a human-readable summary, empty when there was nothing to do.
    """
    root = getattr(scene, 'zozo_contact_solver', None)
    state = getattr(root, 'state', None)
    items = getattr(state, 'dyn_params', None)
    if not items:
        return ''
    converted = []
    for item in items:
        spec = _LEGACY.get(item.param_type)
        if spec is None or len(item.keyframes) < 2:
            continue
        (prop, value_field, length) = spec
        for (index, kf) in enumerate(item.keyframes):
            frame = int(kf.frame)
            if index == 0:
                pass
            elif kf.use_hold:
                pass
            elif length:
                setattr(state, prop, tuple(getattr(kf, value_field)))
            else:
                setattr(state, prop, float(kf.scalar_value))
            state.keyframe_insert(data_path=prop, frame=frame)
        if item.param_type == 'WIND':
            for (index, kf) in enumerate(item.keyframes):
                if index and (not kf.use_hold):
                    state.wind_strength = float(kf.wind_strength_value)
                state.keyframe_insert(data_path='wind_strength', frame=int(kf.frame))
        _apply_hold_interpolation(scene, state, item, prop)
        converted.append(item.param_type)
    if converted:
        items.clear()
        state.dyn_params_index = -1
    return 'converted %d scene keyframe list(s) to F-curves: %s' % (len(converted), ', '.join(converted)) if converted else ''

