def extract_coord(var_name: str) -> None | tuple[str, int, int]:
    """Assuming prefix_R_C format, return `(prefix, row, column)`.

    The "nowhere" coordinate has form prefix_n_n. To indicate this,
    (-1, -1) is returned as the row, column position.

    If error, return None or throw exception.
    """
    if not isinstance(var_name, str):
        raise TypeError('extract_coord: invalid argument type; must be string.')
    name_frags = var_name.split('_')
    if len(name_frags) < 3:
        return None
    try:
        if name_frags[-1] == 'n' and name_frags[-2] == 'n':
            prefix = '_'.join(name_frags[:-2])
            return (prefix, -1, -1)
        col = int(name_frags[-1])
        row = int(name_frags[-2])
    except ValueError:
        return None
    prefix = '_'.join(name_frags[:-2])
    return (prefix, row, col)

def _is_str_or_tuple_of_strs(obj):
    """Check that obj is a str or list/tuple nesting up to 1st level of str.

        Valid examples:

        * "pandas"
        * ("pandas", "scikit-learn")
        * ["pandas", "scikit-learn"]
        """
    if isinstance(obj, (tuple, list)):
        return all((isinstance(x, str) for x in obj))
    return isinstance(obj, str)

def _detect_adapter(data: dict, framework: str) -> str:
    """Derive adapter type (LoRA/FFT) from YAML peft configuration fields.

    - LLMFT: training_config.model_config.peft_config.peft_type
    - VERL: training_config.actor_rollout_ref.model.lora_rank (0=FFT, >0=LoRA)
    - Nova: training_config.model.peft.peft_scheme
    - Checkpointless: model.peft.peft_type
    """
    if framework == 'llmft':
        peft = _get(data, 'training_config', 'model_config', 'peft_config')
        if isinstance(peft, dict):
            pt = peft.get('peft_type')
            if pt and str(pt).lower() == 'lora':
                return 'LoRA'
            return 'FFT'
        return 'FFT'
    if framework == 'verl':
        rank = _get(data, 'training_config', 'actor_rollout_ref', 'model', 'lora_rank')
        if rank is not None and int(rank) > 0:
            return 'LoRA'
        nested_rank = _get(data, 'training_config', 'actor_rollout_ref', 'model', 'lora', 'rank')
        if nested_rank is not None and int(nested_rank) > 0:
            return 'LoRA'
        sft_rank = _get(data, 'training_config', 'model', 'lora', 'rank')
        if sft_rank is not None and int(sft_rank) > 0:
            return 'LoRA'
        sft_lora_rank = _get(data, 'training_config', 'model', 'lora_rank')
        if sft_lora_rank is not None and int(sft_lora_rank) > 0:
            return 'LoRA'
        return 'FFT'
    if framework == 'nova':
        scheme = _get(data, 'training_config', 'model', 'peft', 'peft_scheme')
        if scheme and str(scheme).lower() == 'lora':
            return 'LoRA'
        peft = _get(data, 'training_config', 'model', 'peft')
        if isinstance(peft, dict) and (not scheme):
            return ''
        return 'FFT' if peft is None else ''
    if framework == 'checkpointless':
        pt = _get(data, 'model', 'peft', 'peft_type')
        if pt and str(pt).lower() != 'none':
            return str(pt).upper()
        return ''
    return ''

