def derive_tiered_kv_cache(spec: dict) -> dict:
    """Return tiered KV cache settings from the variant spec."""
    raw = spec.get('tiered_kv_cache', False)
    if isinstance(raw, dict):
        enabled = bool(raw.get('enabled', True))
        cache_sizes = raw.get('cache_sizes', spec.get('cache_sizes', []))
    else:
        enabled = bool(raw)
        cache_sizes = spec.get('cache_sizes', [])
    if not enabled:
        return {'enabled': False, 'cache_sizes': []}
    if isinstance(cache_sizes, str):
        cache_sizes = [int(x.strip()) for x in cache_sizes.split(',') if x.strip()]
    else:
        cache_sizes = [int(x) for x in cache_sizes]
    if not cache_sizes:
        cache_sizes = [32, 64, 128, 256, 512, 1024]
    cache_sizes = sorted(dict.fromkeys(cache_sizes))
    return {'enabled': True, 'cache_sizes': cache_sizes}

@staticmethod
def max_undef(*args):
    """
        Custom maximum function return None if one of its arguments
        is None and max(*args) otherwise.
        """
    if len([x for x in args if x == 1]) > 0:
        return 1
    return reduce(lambda x, y: None if x is None or y is None else max(x, y), args)

def validate_persona_name(name: str) -> tuple[bool, str]:
    """
    Validate persona name to prevent path traversal attacks.

    Returns:
        (is_valid, error_message): tuple indicating if name is valid
    """
    if not name or not name.strip():
        return (False, 'Persona name cannot be empty')
    if '/' in name or '\\' in name:
        return (False, 'Persona name cannot contain path separators (/ or \\)')
    if '..' in name:
        return (False, 'Persona name cannot contain parent directory references (..)')
    if name.startswith('.'):
        return (False, 'Persona name cannot start with a dot (.)')
    if '\x00' in name or '\n' in name or '\r' in name:
        return (False, 'Persona name contains invalid characters')
    return (True, '')

