def enable_deterministic_mode_fixed(model):
    """
    Fixed traversal that properly replaces all RMSNorm modules.

    Note: The library's enable_deterministic_mode() uses dir() which
    fails to traverse into list attributes like model.layers.
    This version uses children() and handles lists correctly.
    """
    replaced = 0
    visited = set()
    actual_model = model.model if hasattr(model, 'model') else model

    def replace_in_module(module):
        nonlocal replaced
        if id(module) in visited:
            return
        visited.add(id(module))
        if not hasattr(module, 'children'):
            return
        for name in module.children():
            try:
                child = getattr(module, name)
            except:
                continue
            if isinstance(child, list):
                for item in child:
                    if isinstance(item, nn.Module):
                        replace_in_module(item)
                continue
            if not isinstance(child, nn.Module):
                continue
            if isinstance(child, nn.RMSNorm) and (not isinstance(child, BatchInvariantRMSNorm)):
                new_norm = BatchInvariantRMSNorm(dims=child.weight.shape[0], eps=child.eps, chunk_size=64)
                new_norm.weight = child.weight
                setattr(module, name, new_norm)
                replaced += 1
            else:
                replace_in_module(child)
    replace_in_module(actual_model)
    return replaced

def flatten(obj, prefix=''):
    """Flatten nested dict/list into dotted keys.

    Lists use [i] positional indices — so inserting/removing a list element
    shifts every following index and cmd_diff reports it as a cascade of
    per-index 'changes' rather than one add/remove. Ordered-list deltas are
    positional and should be read as such.

    Empty dicts/lists emit a sentinel key ("<prefix>{}" / "<prefix>[]" with an
    empty-container value) so a field that is present-but-empty is representable
    in the flattened form — otherwise a field going to/from {} or [] would
    vanish and be invisible to the diff.
    """
    out = {}
    if isinstance(obj, dict):
        if not obj:
            out['%s{}' % prefix] = {}
        for (k, v) in obj.items():
            out.update(flatten(v, '%s.%s' % (prefix, k) if prefix else str(k)))
    elif isinstance(obj, list):
        if not obj:
            out['%s[]' % prefix] = []
        for (i, v) in enumerate(obj):
            out.update(flatten(v, '%s[%d]' % (prefix, i)))
    else:
        out[prefix] = obj
    return out

def get_link_color(link_loss: int) -> str:
    """
    This function returns the failure color code based on the percentage of the lost packets
    """
    result = ''
    failure_colors = ['#ffffff', '#ffeeee', '#ffdddd', '#ffcccc', '#ffbbbb', '#ffaaaa', '#ff8888', '#ff6666', '#ff4444', '#ff2222', '#ff0000']
    for (i, fc) in enumerate(failure_colors):
        if link_loss == float(i * 10):
            result = fc
        elif link_loss > float(i * 10) and link_loss < float((i + 1) * 10):
            result = failure_colors[i + 1]
    return result

def retrieve_financial_details(data):
    """
    retrieve_financial_details returns all of the available financial details under the
    "QuoteTimeSeriesStore" for any of the following three yahoo finance webpages:
    "/financials", "/cash-flow" and "/balance-sheet".

    Returns:
        - TTM_dicts: A dictionary full of all of the available Trailing Twelve Month figures, this can easily be converted to a pandas dataframe.
        - Annual_dicts: A dictionary full of all of the available Annual figures, this can easily be converted to a pandas dataframe.
    """
    TTM_dicts = []
    Annual_dicts = []
    for (key, timeseries) in data.get('timeSeries', {}).items():
        try:
            if timeseries:
                time_series_dict = {'index': key}
                for each in timeseries:
                    if not each:
                        continue
                    time_series_dict[each.get('asOfDate')] = each.get('reportedValue')
                if 'trailing' in key:
                    TTM_dicts.append(time_series_dict)
                elif 'annual' in key:
                    Annual_dicts.append(time_series_dict)
        except KeyError as e:
            print(f'An error occurred while processing the key: {e}')
    return (TTM_dicts, Annual_dicts)

def extract(obj, arr, key):
    """Return all matching values in an object."""
    if isinstance(obj, dict):
        for (k, v) in obj.items():
            if isinstance(v, dict) or (isinstance(v, list) and v and isinstance(v[0], (list, dict))):
                extract(v, arr, key)
            elif k == key:
                arr.append(v)
    elif isinstance(obj, list):
        for item in obj:
            extract(item, arr, key)
    return arr

def validate_outbound(text):
    """Basic validation for outbound content. Returns (ok, text)."""
    if not text or not isinstance(text, str):
        return (False, text)
    suspicious_patterns = ['sk-[a-zA-Z0-9]{20,}', 'Bearer [a-zA-Z0-9\\-_.]+', '/Users/[a-zA-Z]+/', 'password\\s*[:=]\\s*\\S+']
    import re
    for pattern in suspicious_patterns:
        if re.search(pattern, text, re.IGNORECASE):
            return (False, text)
    return (True, text)

