@staticmethod
def _build_scale_urls(image_url: str, logical_w: float, logical_h: float, slice_scale: int) -> dict:
    """
        生成多倍图下载 URL（OSS image/resize 参数）。

        蓝湖切图只存一张图（stored = logical × sliceScale，通常 2x）。
        不同倍率通过 OSS x-oss-process=image/resize 实现在线裁剪。

        Args:
            image_url:   OSS 原图 URL（stored = logical × sliceScale）
            logical_w/h: 逻辑 1x 尺寸（来自 image.size.width/height 或 ddsImage.size）
            slice_scale: 切图导出倍率（sketch JSON 根节点 sliceScale，通常为 2）

        Returns:
            dict: 包含 1x/2x/3x 及各平台常用倍率的 URL
        """
    if not image_url or not logical_w or (not logical_h):
        return {}
    lw = max(1, int(round(logical_w)))
    lh = max(1, int(round(logical_h)))
    stored_w = lw * slice_scale
    stored_h = lh * slice_scale

    def make_url(w: int, h: int) -> str:
        (w, h) = (max(1, w), max(1, h))
        if w == stored_w and h == stored_h:
            return image_url
        return f'{image_url}?x-oss-process=image/resize,w_{w},h_{h}/format,png'

    def js_round(v: float) -> int:
        """模拟 JavaScript Math.round（.5 向上取整）"""
        import math
        return math.floor(v + 0.5)
    ios_base = stored_w / 4
    return {'1x': make_url(lw * 1, lh * 1), '2x': make_url(lw * 2, lh * 2), '3x': make_url(lw * 3, lh * 3), 'ios_1x': make_url(max(1, js_round(ios_base * 1)), max(1, js_round(stored_h / 4 * 1))), 'ios_2x': make_url(max(1, js_round(ios_base * 2)), max(1, js_round(stored_h / 4 * 2))), 'ios_3x': make_url(max(1, js_round(ios_base * 3)), max(1, js_round(stored_h / 4 * 3))), 'android_mdpi': make_url(max(1, js_round(stored_w / 4 * 1)), max(1, js_round(stored_h / 4 * 1))), 'android_hdpi': make_url(max(1, js_round(stored_w / 4 * 1.5)), max(1, js_round(stored_h / 4 * 1.5))), 'android_xhdpi': make_url(max(1, js_round(stored_w / 4 * 2)), max(1, js_round(stored_h / 4 * 2))), 'android_xxhdpi': make_url(max(1, js_round(stored_w / 4 * 3)), max(1, js_round(stored_h / 4 * 3))), 'android_xxxhdpi': make_url(stored_w, stored_h)}

def _reduce_hidden_layers(model_config: 'PretrainedConfig', hidden_layers: int) -> bool:
    """Reduce the hidden-layer count on a single (possibly nested) config object.

    Returns True if any recognized layer-count attribute was found and updated.
    """
    updated = False
    for attr_name in ('num_hidden_layers', 'num_layers', 'depth', 'n_layer', 'n_layers', 'encoder_layers', 'decoder_layers', 'num_decoder_layers'):
        if getattr(model_config, attr_name, None) is not None:
            setattr(model_config, attr_name, hidden_layers)
            updated = True
    layer_types = getattr(model_config, 'layer_types', None)
    if isinstance(layer_types, (list, tuple)):
        model_config.layer_types = layer_types[:hidden_layers]
    return updated

def serialize_value(value):
    """将 Python 对象转换为 BiDi LocalValue

    Args:
        value: Python 原生对象

    Returns:
        BiDi 协议格式的字典
    """
    if value is None:
        return {'type': 'null'}
    if isinstance(value, bool):
        return {'type': 'boolean', 'value': value}
    if isinstance(value, int):
        if abs(value) > 9007199254740991:
            return {'type': 'bigint', 'value': str(value)}
        return {'type': 'number', 'value': value}
    if isinstance(value, float):
        import math
        if math.isnan(value):
            return {'type': 'number', 'value': 'NaN'}
        if math.isinf(value):
            return {'type': 'number', 'value': 'Infinity' if value > 0 else '-Infinity'}
        if value == 0.0 and math.copysign(1.0, value) < 0:
            return {'type': 'number', 'value': '-0'}
        return {'type': 'number', 'value': value}
    if isinstance(value, str):
        return {'type': 'string', 'value': value}
    if isinstance(value, (list, tuple)):
        return {'type': 'array', 'value': [serialize_value(v) for v in value]}
    if isinstance(value, dict):
        if 'sharedId' in value:
            return {'type': 'sharedReference', 'sharedId': value['sharedId']}
        pairs = []
        for (k, v) in value.items():
            pairs.append([serialize_value(k) if not isinstance(k, str) else k, serialize_value(v)])
        return {'type': 'object', 'value': pairs}
    if isinstance(value, set):
        return {'type': 'set', 'value': [serialize_value(v) for v in value]}
    shared_id = getattr(value, '_shared_id', None)
    if shared_id:
        return {'type': 'sharedReference', 'sharedId': shared_id}
    return {'type': 'string', 'value': str(value)}

def isctime(sys=None, dt=None, strict=False):
    """
    Check to see if a system is a continuous-time system.

    Parameters
    ----------
    sys : I/O system, optional
        System to be checked.
    dt : None or number, optional
        Timebase to be checked.
    strict : bool (default = False)
        If strict is True, make sure that timebase is not None.
    """
    if sys is None:
        if dt is None:
            return True if not strict else False
        else:
            return dt == 0
    elif dt is not None:
        raise TypeError('passing both system and timebase not allowed')
    if isinstance(sys, (int, float, complex, np.number)):
        return True if not strict else False
    else:
        return sys.isctime(strict)

