def calculate_video_frame_range(ele: dict, total_frames: int, video_fps: float) -> tuple[int, int, int]:
    """
    Calculate the start and end frame indices based on the given time range.

    Args:
        ele (dict): A dictionary containing optional 'video_start' and 'video_end' keys (in seconds).
        total_frames (int): Total number of frames in the video.
        video_fps (float): Frames per second of the video.

    Returns:
        tuple: A tuple containing (start_frame, end_frame, frame_count).

    Raises:
        ValueError: If input parameters are invalid or the time range is inconsistent.
    """
    if video_fps <= 0:
        raise ValueError('video_fps must be a positive number')
    if total_frames <= 0:
        raise ValueError('total_frames must be a positive integer')
    video_start = ele.get('video_start', None)
    video_end = ele.get('video_end', None)
    if video_start is None and video_end is None:
        return (0, total_frames - 1, total_frames)
    max_duration = total_frames / video_fps
    if video_start is not None:
        video_start_clamped = max(0.0, min(video_start, max_duration))
        start_frame = math.ceil(video_start_clamped * video_fps)
    else:
        start_frame = 0
    if video_end is not None:
        video_end_clamped = max(0.0, min(video_end, max_duration))
        end_frame = math.floor(video_end_clamped * video_fps)
        end_frame = min(end_frame, total_frames - 1)
    else:
        end_frame = total_frames - 1
    if start_frame >= end_frame:
        raise ValueError(f'Invalid time range: Start frame {start_frame} (at {(video_start_clamped if video_start is not None else 0)}s) exceeds end frame {end_frame} (at {(video_end_clamped if video_end is not None else max_duration)}s). Video duration: {max_duration:.2f}s ({total_frames} frames @ {video_fps}fps)')
    logger.info(f'calculate video frame range: start_frame={start_frame!r}, end_frame={end_frame!r}, total_frames={total_frames!r} from video_start={video_start!r}, video_end={video_end!r}, video_fps={video_fps:.3f}')
    return (start_frame, end_frame, end_frame - start_frame + 1)

def _wrap_js_for_evaluate(script: str, n_args: int) -> tuple[str, list]:
    """把 DrissionPage 的 run_js(script, *args) 包装成 Playwright evaluate 格式。

    DrissionPage: page.run_js("return arguments[0] + 1", 5)
    Playwright:   page.evaluate("(a) => { return a + 1; }", 5)

    策略：
    1. 把 arguments[0], arguments[1]... 替换为参数名 __cf_a0, __cf_a1...
    2. 用箭头函数包装，无参数时用 IIFE
    """
    script = script.strip()
    if n_args == 0:
        wrapped = f'(() => {{ {script} }})()'
        return (wrapped, [])
    param_names = []
    modified = script
    for i in range(n_args):
        pname = f'__cf_a{i}'
        modified = modified.replace(f'arguments[{i}]', pname)
        param_names.append(pname)
    if n_args == 1:
        wrapped = f'({param_names[0]}) => {{ {modified} }}'
        return (wrapped, [])
    else:
        params = ', '.join(param_names)
        wrapped = f'([{params}]) => {{ {modified} }}'
        return (wrapped, list(range(n_args)))

def _is_freq_func(x):
    """Whether a frequency specification (Omega or Omegadot) is given as
    function(s) of time rather than constant(s): a callable, or a sequence whose
    first element is callable."""
    if callable(x):
        return True
    try:
        return callable(x[0])
    except (TypeError, IndexError, KeyError):
        return False

def modules_to_component_filter(modules: list[str]) -> str:
    """Convert module names to a comma-separated component filter string.

    Maps module names back to the component names used by the existing
    ``--only`` system (e.g. "agents", "skills", "hooks", "rules").
    This bridges the new module system with the old component system.
    """
    components: set[str] = set()
    for module in modules:
        if module == 'core':
            components.update(['hooks', 'constitution', 'architecture', 'rules'])
        elif module == 'agents':
            components.add('agents')
        elif module == 'skills':
            components.add('skills')
        elif module.startswith('rules-'):
            components.add('rules')
        elif module == 'mcp-templates':
            pass
    return ','.join(sorted(components))

def _normalize_response(obj):
    """Convert an ollama response object to a dict for backwards compatibility.
    If already a dict, return as-is. Handles nested response objects recursively."""
    if obj is None:
        return {}
    if isinstance(obj, dict):
        return obj
    result = {}
    if hasattr(obj, '__dict__'):
        for (key, val) in obj.__dict__.items():
            if not key.startswith('_'):
                if hasattr(val, '__dict__') and (not isinstance(val, (str, int, float, bool, list, dict, type(None)))):
                    result[key] = _normalize_response(val)
                elif isinstance(val, list):
                    result[key] = [_normalize_response(item) if hasattr(item, '__dict__') and (not isinstance(item, (str, int, float, bool, dict, type(None)))) else item for item in val]
                else:
                    result[key] = val
    if not result:
        for attr in ('models', 'model', 'name', 'modified_at', 'digest', 'size', 'details', 'modelfile', 'template', 'license', 'modelinfo', 'parameters', 'message', 'response', 'context', 'embedding', 'embeddings', 'eval_count', 'eval_duration', 'total_duration', 'load_duration', 'prompt_eval_count', 'prompt_eval_duration', 'done'):
            val = getattr(obj, attr, None)
            if val is not None:
                if hasattr(val, '__dict__') and (not isinstance(val, (str, int, float, bool, list, dict, type(None)))):
                    result[attr] = _normalize_response(val)
                elif isinstance(val, list):
                    result[attr] = [_normalize_response(item) if hasattr(item, '__dict__') and (not isinstance(item, (str, int, float, bool, dict, type(None)))) else item for item in val]
                else:
                    result[attr] = val
    return result

def normalize_span(span: object) -> dict | None:
    """Return the canonical evidence span, or None when there is no usable one."""
    if not isinstance(span, dict):
        return None
    text = span.get('text')
    if not isinstance(text, str) or not text.strip():
        return None
    path = span.get('path')
    start_line = span.get('start_line')
    if not isinstance(path, str) or not path.strip():
        return None
    if not isinstance(start_line, int) or isinstance(start_line, bool) or start_line < 1:
        return None
    start_column = span.get('start_column')
    start_column = start_column if isinstance(start_column, int) and start_column >= 1 else 1
    end_line = span.get('end_line')
    end_line = end_line if isinstance(end_line, int) and end_line >= start_line else start_line
    end_column = span.get('end_column')
    end_column = end_column if isinstance(end_column, int) and end_column >= 1 else start_column
    return {'end_column': end_column, 'end_line': end_line, 'path': path.strip(), 'start_column': start_column, 'start_line': start_line, 'text': collapse(text)}

def parse_size(s: str | int) -> int:
    """Parse a size string with optional unit (B, KB, MB, GB) into bytes.

    Examples: "1024", "1KB", "64KB", "1MB", "1GB"
    """
    if isinstance(s, int):
        return s
    s = str(s).strip().upper()
    if not s:
        raise ValueError('Empty size string')
    m = re.match('^(\\d+(?:\\.\\d+)?)\\s*([KMG]?B?)$', s)
    if not m:
        raise ValueError(f'Invalid size format: {s!r}. Use e.g. 1024, 1KB, 1MB, 1GB')
    (num_str, unit) = m.groups()
    num = float(num_str)
    unit = unit or 'B'
    if unit == 'K':
        unit = 'KB'
    elif unit == 'M':
        unit = 'MB'
    elif unit == 'G':
        unit = 'GB'
    if unit not in _SIZE_UNITS:
        raise ValueError(f'Unknown unit: {unit}. Use B, KB, MB, GB')
    return int(num * _SIZE_UNITS[unit])

