@staticmethod
def _response_to_dict(response) -> dict:
    """
        Convert DashScope response object to a plain dict.

        DashScope SDK wraps responses in proxy objects whose __getattr__
        delegates to __getitem__, raising KeyError (not AttributeError)
        when an attribute is missing.  Standard hasattr / getattr only
        catch AttributeError, so we must use try-except everywhere.
        """
    _SENTINEL = object()

    def _safe_getattr(obj, name, default=_SENTINEL):
        """getattr that also catches KeyError from DashScope proxy objects."""
        try:
            return getattr(obj, name)
        except (AttributeError, KeyError, TypeError):
            return default

    def _has_attr(obj, name):
        return _safe_getattr(obj, name) is not _SENTINEL

    def _to_dict(obj):
        if isinstance(obj, (str, int, float, bool, type(None))):
            return obj
        if isinstance(obj, dict):
            return {k: _to_dict(v) for (k, v) in obj.items()}
        if isinstance(obj, (list, tuple)):
            return [_to_dict(i) for i in obj]
        if _has_attr(obj, 'keys'):
            try:
                return {k: _to_dict(obj[k]) for k in obj.keys()}
            except Exception:
                pass
        return obj
    result = {}
    for attr in ('request_id', 'status_code', 'code', 'message', 'output', 'usage'):
        val = _safe_getattr(response, attr)
        if val is _SENTINEL:
            try:
                val = response[attr]
            except (KeyError, TypeError, IndexError):
                continue
        result[attr] = _to_dict(val)
    return result

def parse_frontmatter(lines: list[str]) -> tuple[dict, int]:
    """Return (frontmatter dict-ish, index of first body line)."""
    if not lines or lines[0].strip() != '---':
        return ({}, 0)
    fm = {}
    for (i, line) in enumerate(lines[1:], start=1):
        if line.strip() == '---':
            return (fm, i + 1)
        m = re.match('^([A-Za-z][A-Za-z0-9_-]*):\\s*(.*)$', line)
        if m:
            fm[m.group(1).strip().lower()] = m.group(2).strip().strip('"')
    return ({}, 0)

def normalize_padding_value(padding: str | int | tuple[int, int] | tuple[int, int, int, int]) -> tuple[int, int, int, int]:
    """
    Normalize a padding value.

    This value can be a string, e.g. ``"10"``, or ``"10x10"``, or ``"10x10x10x10"``

    It can also be specified as a python ``int`` or ``tuple``

    Multidimensional padding values are laid out as: ``LEFTxTOPxRIGHTxBOTTOM``, or ``WIDTHxHEIGHT``

    This is the same all across dgenerate.

    :raise ValueError: If the padding value is specified incorrectly.

    :param padding: Padding value
    :return: Normalized padding (4 tuple of int)
    """
    if isinstance(padding, int):
        padding = (padding, padding, padding, padding)
    else:
        if isinstance(padding, str):
            try:
                padding_dims = _textprocessing.parse_dimensions(str(padding))
            except ValueError as e:
                raise ValueError(f'Could not parse the padding value: {padding}') from e
        else:
            padding_dims = padding
        if len(padding_dims) == 1:
            p = padding_dims[0]
            padding = (p, p, p, p)
        elif len(padding_dims) == 2:
            (width_pad, height_pad) = padding_dims
            padding = (width_pad, height_pad, width_pad, height_pad)
        elif len(padding_dims) == 4:
            padding = tuple(padding_dims)
        else:
            raise ValueError('Padding value must be 1, 2, or 4 dimensional. Use format: "10" (uniform), "10x20" (width x height), or "5x10x5x15" (left x top x right x bottom)')
    return padding

def _ldap_parse_value(text, start):
    """Parse an assertion value from filter text at position `start`, handling escape sequences.
    Returns (value, end_pos)."""
    retVal = []
    i = start
    while i < len(text) and text[i] not in (')',):
        if text[i] == '\\' and i + 2 < len(text):
            retVal.append(chr(int(text[i + 1:i + 3], 16)))
            i += 3
        else:
            retVal.append(text[i])
            i += 1
    return (''.join(retVal), i)

def _addressed_to_mentor(text: str) -> bool:
    """In the trio, a message aimed at the builder (Клод/Ментор) must NOT be hijacked by Nagual.
    @-mentions win (owner convention): @<nagual_bot> = Nagual, @<claude_bot> = Claude."""
    t = (text or '').lower()
    if '@dazaebalo_bot' in t:
        return False
    if '@claude_nagual_bot' in t:
        return True
    return ('клод' in t or 'ментор' in t) and 'нагвал' not in t

def pretty(data, indent=''):
    """Format nested dict/list/tuple structures into a more human-readable string
    This function is a bit better than pprint for displaying OrderedDicts.
    """
    ret = ''
    ind2 = indent + '    '
    if isinstance(data, dict):
        ret = indent + '{\n'
        for (k, v) in data.items():
            ret += ind2 + repr(k) + ':  ' + pretty(v, ind2).strip() + '\n'
        ret += indent + '}\n'
    elif isinstance(data, list) or isinstance(data, tuple):
        s = repr(data)
        if len(s) < 40:
            ret += indent + s
        else:
            if isinstance(data, list):
                d = '[]'
            else:
                d = '()'
            ret = indent + d[0] + '\n'
            for (i, v) in enumerate(data):
                ret += ind2 + str(i) + ':  ' + pretty(v, ind2).strip() + '\n'
            ret += indent + d[1] + '\n'
    else:
        ret += indent + repr(data)
    return ret

def _trainable_token_spans(mask: list[bool]) -> list[tuple[int, int]]:
    """Return half-open token spans marked trainable by a Verifiers node mask."""
    spans: list[tuple[int, int]] = []
    start: int | None = None
    for (index, sampled) in enumerate([*mask, False]):
        if sampled and start is None:
            start = index
        elif not sampled and start is not None:
            spans.append((start, index))
            start = None
    return spans

def make_geo_data(lat, lng):
    """    Creates a geo location URI.

    :param float lat: Latitude
    :param float lng: Longitude
    :rtype: str
    """

    def float_to_str(f):
        return f'{f:.8f}'.rstrip('0').rstrip('.')
    return f'geo:{float_to_str(lat)},{float_to_str(lng)}'

def _section_span(lines, header, start=0):
    """Return [i, j) covering a Google `header` line and its more-indented
    body (blank lines included), or None if not found."""
    for i in range(start, len(lines)):
        if lines[i].strip() == header:
            base = len(lines[i]) - len(lines[i].lstrip())
            j = i + 1
            while j < len(lines):
                s = lines[j]
                if s.strip() and len(s) - len(s.lstrip()) <= base:
                    break
                j += 1
            return (i, j)
    return None

def is_gdn_layer(layer) -> bool:
    """Return True if the module is a GDN (linear attention) layer or a DecoderLayer containing one."""
    if hasattr(layer, 'layer_type') and layer.layer_type == 'linear_attention':
        return True
    if hasattr(layer, 'block_type') and layer.block_type == 'linear_attention':
        return True
    return False

def listify(x):
    """Convenience function to allow strings or lists to be used as arguments.

    If a string is given, it will be tokenized into a list using whitespace as
    separator.  If a list or tuple is given, its elements will be processed.
    If anything else is given, convert it to a string, and then try to make
    the result into a list.
    """
    if not x:
        return []
    if isinstance(x, str):
        xlist = x.split()
    elif isinstance(x, (list, tuple)):
        xlist = []
        for l in x:
            xlist += listify(l)
    else:
        xlist = listify(str(x))
    return xlist

def _render_table_from_schema(schema_data, spec_file_name, need_header=True, parent_required_list=None, context=None):
    """Render a Markdown table from a schema dictionary.

    Schema dictionary must contain 'properties'. 'required' list is optional.

    Args:
    ----
      schema_data: A dictionary representing the JSON schema.
      spec_file_name: The name of the spec file indicating where the dictionary
        should be rendered.
      need_header: Optional. Whether to render the header row.
      parent_required_list: Optional. The list of required properties from the
        parent schema.
      context: Optional. A dictionary providing context for loading schema
        variants (e.g., {'io_type': 'request', 'operation_id':
        'createCheckout'}).

    Returns:
    -------
      A string containing a Markdown table representing the schema properties,
      or a message indicating why a table could not be rendered.

    """
    if not schema_data:
        return '_No content fields defined._'
    self_id = schema_data.get('$id')
    self_ref_name = self_id.rsplit('/', 1)[-1] if self_id else None

    def _deref_self(ref_value):
        if ref_value == '#' and self_ref_name:
            return self_ref_name
        return ref_value
    if 'oneOf' in schema_data and (not schema_data.get('properties')) and (not schema_data.get('allOf')) and (not schema_data.get('$ref')):
        links = []
        for item in schema_data['oneOf']:
            if '$ref' in item:
                links.append(create_link(_deref_self(item['$ref']), spec_file_name, context))
            elif item.get('type'):
                links.append(f"`{item.get('type')}`")
        if links:
            return '\nThis object MUST be one of the following types: ' + ', '.join(links) + '.\n'
    properties = schema_data.get('properties', {})
    required_list = schema_data.get('required', [])
    if parent_required_list:
        required_list = list(required_list)
        for req in parent_required_list:
            if req not in required_list:
                required_list.append(req)
    if not properties and 'oneOf' not in schema_data and ('$ref' not in schema_data) and ('allOf' not in schema_data or schema_data.get('type') == 'array'):
        s_type = schema_data.get('type')
        enum_val = schema_data.get('enum')
        pattern_val = schema_data.get('pattern')
        if s_type or enum_val:
            desc = schema_data.get('description', '')
            if pattern_val:
                desc += f'\n\n**Pattern:** `{pattern_val}`'
            if enum_val:
                formatted = ', '.join([f'`{v}`' for v in enum_val])
                desc += f'\n\n**Enum:** {formatted}'
            return desc
        return '_No properties defined._'
    md = []
    if need_header:
        md = ['| Name | Type | Requirement | Description |']
        md.append('| :--- | :--- | :--- | :--- |')
    if 'allOf' in properties:
        md.append(_render_embedded_table(properties.get('allOf', []), required_list, spec_file_name, context))
    elif 'allOf' in schema_data and (not properties):
        md.append(_render_embedded_table(schema_data.get('allOf', []), required_list, spec_file_name, context))
    elif '$ref' in schema_data:
        md.append(_render_table_from_ref(schema_data.get('$ref'), required_list, spec_file_name, context))
    else:
        for (field_name, details) in properties.items():
            if field_name == '$ref':
                md.append(_render_table_from_ref(details, required_list, spec_file_name, context))
                continue
            ucp_annotation = details.get('ucp_request') if isinstance(details, dict) else None
            f_type = details.get('type', 'any')
            ref = _deref_self(details.get('$ref'))
            if ref and 'ucp.json#/$defs/' in ref and ('$defs' in ref):
                def_name = ref.split('/')[-1]
                try:
                    with UCP_SCHEMA_PATH.open(encoding='utf-8') as f:
                        ucp_data = json.load(f)
                        resolved_def = ucp_data.get('$defs', {}).get(def_name)
                        if resolved_def:
                            embedder_desc = details.get('description')
                            details = dict(resolved_def)
                            if embedder_desc:
                                details['description'] = embedder_desc
                            ref = None
                            f_type = details.get('type', 'any')
                except (json.JSONDecodeError, OSError):
                    pass
            items = details.get('items', {})
            items_ref = _deref_self(items.get('$ref'))
            version_data = None
            if ref and ref.endswith('#/$defs/version'):
                try:
                    with UCP_SCHEMA_PATH.open(encoding='utf-8') as f:
                        data = json.load(f)
                        version_data = data.get('$defs', {}).get('version', {})
                except json.JSONDecodeError as e:
                    print(f"**Error loading schema {'ucp.json' + ref}':** {e}")
            if 'oneOf' in details:
                parts = []
                for one_of_type in details.get('oneOf', []):
                    if '$ref' in one_of_type:
                        parts.append(create_link(_deref_self(one_of_type['$ref']), spec_file_name, context))
                    elif one_of_type.get('type'):
                        parts.append(f"`{one_of_type['type']}`")
                f_type = f"OneOf[{', '.join(parts)}]"
            elif ref:
                if version_data:
                    f_type = version_data.get('type', 'any')
                else:
                    f_type = create_link(ref, spec_file_name, context)
            elif f_type == 'array' and items_ref:
                link = create_link(items_ref, spec_file_name, context)
                f_type = f'Array[{link}]'
            elif f_type == 'array':
                inner_type = items.get('type')
                if not inner_type:
                    branches = items['allOf'] if isinstance(items.get('allOf'), list) else [items]
                    for branch in branches:
                        if not isinstance(branch, dict):
                            continue
                        if branch.get('$ref'):
                            inner_type = create_link(_deref_self(branch['$ref']), spec_file_name, context)
                            break
                        if branch.get('title'):
                            inner_type = branch['title']
                            break
                    inner_type = inner_type or 'object'
                f_type = f'Array[{inner_type}]'
            desc = ''
            if 'const' in details:
                desc += f"**Constant = {details.get('const')}**. "
            elif version_data and ref == '#/$defs/version':
                desc += version_data.get('description', '')
            embedder_desc = details.get('description')
            if embedder_desc is not None:
                desc += embedder_desc
            elif ref and (not ref.startswith('#')):
                ref_clean = ref.split('#')[0]
                ref_entity = ref_clean.replace('.json', '')
                ref_schema = _load_json_file(ref_entity)
                if ref_schema:
                    desc += ref_schema.get('description', '')
            enum_values = details.get('enum')
            if enum_values and isinstance(enum_values, list):
                formatted_enums = ', '.join([f'`{str(v)}`' for v in enum_values])
                if desc:
                    desc += '<br>'
                desc += f'**Enum:** {formatted_enums}'
            requirement = _field_requirement(field_name, ucp_annotation, required_list)
            md.append(f'| {field_name} | {f_type} | {requirement} | {desc} |')
    return '\n'.join(md)

def recursive_copy(x, clone=None, detach=None, retain_grad=None):
    """
    Copies a reference to a tensor, or an object that contains tensors,
    optionally detaching and cloning the tensor(s).  If retain_grad is
    true, the original tensors are marked to have grads retained.
    """
    if not clone and (not detach) and (not retain_grad):
        return x
    if isinstance(x, torch.Tensor):
        if retain_grad:
            if not x.requires_grad:
                x.requires_grad = True
            x.retain_grad()
        elif detach:
            x = x.detach()
        if clone:
            x = x.clone()
        return x
    if isinstance(x, dict):
        return type(x)({k: recursive_copy(v) for (k, v) in x.items()})
    elif isinstance(x, (list, tuple)):
        return type(x)([recursive_copy(v) for v in x])
    else:
        assert False, f'Unknown type {type(x)} cannot be broken into tensors.'

