def collect_new_values(form=None, formsets=None, as_json_string=False):
    """
    Collect the "post save" data into a JSON-compatible structure.
    returns something like this:
    {
        'form_data': {
            '<field name 1>': <new field 1 value>,
            '<field name 2>': <new field 2 value>,
            ...
        },
        formsets_data: [
            # for each formset:
            {
                'added':[
                    {
                        'object_verbose_name': '<object verbose name>',
                        'object_unicode': '<object unicode>',
                        '<field name 1>': <new field 1 value>,
                        '<field name 2>': <new field 2 value>,
                    },
                    ...
                ],
                'changed': [
                    {
                        'object_verbose_name': '<object verbose name>',
                        'object_unicode': '<object unicode>',
                        '<field name X>': <new field X value>,
                        '<field name Y>': <new field Y value>,
                        '<field name Z>': <new field Z value>,
                    },
                    ...
                ],
                'deleted': [
                    {
                        'object_verbose_name': '<object verbose name>',
                        'object_unicode': '<object unicode>',
                    },
                    ...
                ]
            },
            ...
        ]
    }
    """
    result = {'form_data': {}, 'formsets_data': []}
    if form:
        for field_name in get_auditable_fields(form):
            field_value = form.cleaned_data[field_name]
            result['form_data'][field_name] = field_serializer(field_serializer(field_value))
    if formsets:
        for formset in formsets:
            formset_data = {'added': [], 'changed': [], 'deleted': []}
            added_data = []
            for added_object in formset.new_objects:
                object_values = {'object_verbose_name': force_unicode(added_object._meta.verbose_name), 'object_unicode': force_unicode(added_object), 'fields': {}}
                for field in added_object._meta.local_fields:
                    field_name = field.get_attname()
                    field_value = getattr(added_object, field_name)
                    object_values['fields'][field_name] = field_serializer(field_value)
                added_data.append(object_values)
            formset_data['added'] = added_data
            changed_data = []
            for (changed_object, changed_fields) in formset.changed_objects:
                object_values = {'object_verbose_name': force_unicode(changed_object._meta.verbose_name), 'object_unicode': force_unicode(changed_object), 'fields': {}}
                for field_name in changed_fields:
                    field_value = getattr(changed_object, field_name)
                    object_values['fields'][field_name] = field_serializer(field_value)
                changed_data.append(object_values)
            formset_data['changed'] = changed_data
            deleted_data = []
            for deleted_object in formset.deleted_objects:
                object_values = {'object_verbose_name': force_unicode(deleted_object._meta.verbose_name), 'object_unicode': force_unicode(deleted_object)}
                deleted_data.append(object_values)
            formset_data['deleted'] = deleted_data
            if any([added_data, changed_data, deleted_data]):
                result['formsets_data'].append(formset_data)
    if as_json_string:
        return json.dumps(result)
    else:
        return result

def _read_hook_payload() -> dict:
    """Read and parse the hook's JSON stdin payload once, TTY/empty-guarded.

    Claude Code passes e.g. `{"source": "startup", "session_id": "…"}`. Returns
    `{}` when stdin is a TTY (a manual `sf-context detect` run) or empty/unparseable
    (the `--plugin-dir` test harness), so callers default to the full startup path.
    Stdin reads once, so callers that need both `source` and `session_id` go through
    this rather than re-reading. Side effect: stashes the payload's `session_id` in
    `_CURRENT_SESSION_ID` so the session-scoped readiness gate can read it without
    every intermediate caller having to thread it through.
    """
    try:
        if sys.stdin.isatty():
            return {}
        data = sys.stdin.read()
    except Exception:
        return {}
    if not data.strip():
        return {}
    payload = parse_json(data)
    payload = payload if isinstance(payload, dict) else {}
    sid = payload.get('session_id') or payload.get('sessionId')
    if isinstance(sid, str) and sid:
        global _CURRENT_SESSION_ID
        _CURRENT_SESSION_ID = sid
    return payload

def _embed_logo(logo_url: str) -> str:
    """Return a usable src attribute for the logo. Base64-embed local paths;
    leave URLs as-is (recipient's browser will fetch them)."""
    if not logo_url:
        return ''
    if logo_url.startswith(('data:', 'http://', 'https://')):
        return logo_url
    p = Path(logo_url).expanduser()
    if p.exists() and p.is_file():
        ext = p.suffix.lstrip('.').lower() or 'png'
        data = base64.b64encode(p.read_bytes()).decode('ascii')
        mime = {'png': 'image/png', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'svg': 'image/svg+xml', 'gif': 'image/gif', 'webp': 'image/webp'}.get(ext, f'image/{ext}')
        return f'data:{mime};base64,{data}'
    return logo_url

def _extract_page_range_text(reader, start: int, end: int) -> str:
    """Return concatenated text from pages ``[start, end)``."""
    parts: list[str] = []
    for i in range(start, end):
        try:
            text = reader.pages[i].extract_text() or ''
        except Exception:
            text = ''
        if text:
            parts.append(text)
    return '\n'.join(parts)

def _chart_custom_labels(ch):
    """Custom data-label text (present only when it overrides the number shown on the
    chart; an automatic label = the series value, already in the data table).
    Scans every plot (a combo chart has several)."""
    found = {}
    try:
        for plot in ch.plots:
            for s in plot.series:
                for (idx, pt) in enumerate(s.points):
                    try:
                        dl = pt.data_label
                        if dl.has_text_frame and dl.text_frame.text.strip():
                            found.setdefault(str(s.name), {})[idx] = dl.text_frame.text.strip()
                    except Exception:
                        pass
    except Exception:
        pass
    return found or None

def parse_sstat_nodes(output: str, job_id: str) -> list[str]:
    """Parse and return the sstat command

    This function parses and returns the nodes of
    a job in a list with the duplicates removed.

    :param output: output of the sstat command
    :return: compute nodes of the allocation or job
    """
    nodes = []
    for line in output.split('\n'):
        sstat_string = line.split('|')
        if len(sstat_string) >= 2:
            if jobid_exact_match(sstat_string[0], job_id):
                node = sstat_string[1]
                nodes.append(node)
    return list(set(nodes))

