def flatten_outputs(out):
    """Deterministic tensor list from an op's return value: tensor, tuple/list, dict, or nesting.

    Attention entries return `(out, lse)`; a bare-tensor assumption does not merely raise here, it
    makes `correct()` fall into its except and report the candidate INCORRECT — a correct kernel
    rejected for the shape of its return value. Dict order is by sorted key so the two legs pair up."""
    if isinstance(out, dict):
        return [t for k in sorted(out) for t in flatten_outputs(out[k])]
    if isinstance(out, (tuple, list)):
        return [t for o in out for t in flatten_outputs(o)]
    if hasattr(out, 'shape'):
        return [out]
    return []

def _clean_cell(cell: dict) -> dict:
    """Drop run-specific metadata, stderr noise, and text/plain fallbacks that shadow a rich output."""
    cell['metadata'] = {k: v for (k, v) in cell.get('metadata', {}).items() if k != 'execution'}
    outputs = []
    for out in cell.get('outputs', []):
        if out.get('output_type') == 'stream' and out.get('name') == 'stderr':
            text = _TQDM_NOISE.sub('', ''.join(out.get('text', [])))
            if not text:
                continue
            out['text'] = text
        data = out.get('data')
        if data and ('text/html' in data or any((k.startswith('image/') for k in data))):
            data.pop('text/plain', None)
        outputs.append(out)
    cell['outputs'] = outputs
    return cell

def _clean_dict(d):
    """
        Recursively clean a dictionary by removing all None values, empty strings, empty lists,
        and nested dictionaries that become empty after cleaning.

        Args:
            d (dict): The dictionary to clean.

        Returns:
            dict: The cleaned dictionary.
        """
    if not isinstance(d, dict):
        return d
    cleaned_dict = {}
    for (key, value) in d.items():
        if isinstance(value, dict):
            nested_cleaned = _clean_dict(value)
            if nested_cleaned:
                cleaned_dict[key] = nested_cleaned
        elif isinstance(value, bool) or value:
            cleaned_dict[key] = value
    return cleaned_dict

@staticmethod
def _is_placeholder_stock_name(name: str, code: str) -> bool:
    """Return True when the stock name is missing or placeholder-like."""
    if not name:
        return True
    normalized = str(name).strip()
    if not normalized:
        return True
    if normalized == code:
        return True
    if normalized.startswith('股票'):
        return True
    if 'Unknown' in normalized:
        return True
    return False

@staticmethod
def match(o1, o2):
    """
        Compare two ModelDescription object instances

        Arguments:
            o1 (ModelDescription, dict): object to compare
            o2 (ModelDescription, dict): object to compare

        Returns:
            bool: true if objects match
        """
    type_o1 = type(o1)
    if type_o1 is not type(o2):
        return False
    if type_o1 is dict:
        if set(o1.keys()) != set(o2.keys()):
            neon_logger.display('Missing keys')
            return False
        for key in o1:
            if key == 'name':
                return True
            if not ModelDescription.match(o1[key], o2[key]):
                return False
    elif any([type_o1 is x for x in [list, tuple]]):
        if len(o1) != len(o2):
            return False
        for (val1, val2) in zip(o1, o2):
            if not ModelDescription.match(val1, val2):
                return False
    elif type_o1 is np.ndarray:
        match = np.array_equal(o1, o2)
        return match
    else:
        return o1 == o2
    return True

def _powershell_elevator_script(hidden: bool=False, elevate_message: str=None, clear_screen: bool=False, bg_color: str=None) -> str:
    """
    Returns a wrapper script for powershell commands / scripts
    that will try elevation and get stdout/stderr and exit code (0 or 1) of the elevated process
    """
    script = '
# Run elevated commands and get stdout/stderr and (partial) exitcode

try {
    # Function blatantly stolen from https://stackoverflow.com/a/15669365/2635443
    function Write-StdErr {
        param ([PSObject] $InputObject)
        $outFunc = if ($Host.Name -eq 'ConsoleHost') {
            [Console]::Error.WriteLine
        } else {
        $host.ui.WriteErrorLine
        }
        if ($InputObject) {
            [void] $outFunc.Invoke($InputObject.ToString())
        } else {
            [string[]] $lines = @()
            $Input | % { $lines += $_.ToString() }
            [void] $outFunc.Invoke($lines -join "`r`n")
        }
    }

    # Parts blatanly stolen from https://stackoverflow.com/a/60216595/2635443

    # Get the ID and security principal of the current user account
    $myWindowsID=[System.Security.Principal.WindowsIdentity]::GetCurrent()
    $myWindowsPrincipal=new-object System.Security.Principal.WindowsPrincipal($myWindowsID)

    # Get the security principal for the Administrator role
    $adminRole=[System.Security.Principal.WindowsBuiltInRole]::Administrator

    # Check to see if we are currently running "as Administrator"
    if ($myWindowsPrincipal.IsInRole($adminRole))
        {
            # Update window to show we're running as administrator
            try {
                $Host.UI.RawUI.WindowTitle = $myInvocation.MyCommand.Definition + "(Elevated)"
            } catch {
                # WindoTitle can't be more than 1023 characters, so let's just ignore this if it fails
                $Host.UI.RawUI.WindowTitle = "Elevated PowerShell"
            }
            ___BACKGROUND_COLOR_PLACEHOLDER___
            ___CLEAR_SCREEN_PLACEHOLDER___
            ___ELEVATE_MESSAGE_PLACEHOLDER___
        } else {
            $capture_stdout = New-TemporaryFile
            $capture_stderr = New-TemporaryFile
            # Relaunch our processs as admin
            # This will disconnect fds, so we need to redirect stdout and stderr in order to catch them
            $processParams = new-object System.Diagnostics.ProcessStartInfo "PowerShell";

            # Specify the current script path and name as a parameter
            $processParams.Arguments = $myInvocation.MyCommand.Definition;
            $processParams.Arguments += " > $capture_stdout 2> $capture_stderr"

            # Indicate that the process should be elevated
            $processParams.Verb = "RunAs"
            # We might hide our window, or leave this commented out so options above apply
            ___HIDDEN_PLACEHOLDER___

            # Start the new process
            try {
                $process = [System.Diagnostics.Process]::Start($processParams)
                While (-not $process.HasExited) {
                    Start-Sleep -Milliseconds 100
                }
                # Arbitrary wait time for fds to close
                Start-Sleep -Milliseconds 500
                Write-Host (Get-Content -Path $capture_stdout)
                Write-StdErr (Get-Content -Path $capture_stderr)
                # This will only return 0 or 1, other integers are transformed into 1
                exit($process.ExitCode)
            } catch {
                Write-output "Process cannot be launched as admin. Trying as standard user"
            }

        }

    # The following code will run elevated
    ___CODE_PLACEHOLDER___
} catch {
    Write-Host "PS Error: $($_.Exception.Message)"
    Start-Sleep -Seconds 3
    exit(1)
}
    '
    if hidden:
        script = script.replace('___HIDDEN_PLACEHOLDER___', '$processParams.WindowStyle = "Hidden"')
    else:
        script = script.replace('___HIDDEN_PLACEHOLDER___', '')
    if elevate_message:
        script = script.replace('___ELEVATE_MESSAGE_PLACEHOLDER___', '$Host.UI.Write("{}")'.format(elevate_message))
    else:
        script = script.replace('___ELEVATE_MESSAGE_PLACEHOLDER___', '')
    if bg_color:
        script = script.replace('___BACKGROUND_COLOR_PLACEHOLDER___', '$Host.UI.RawUI.BackgroundColor = "{}"'.format(bg_color))
    else:
        script = script.replace('___BACKGROUND_COLOR_PLACEHOLDER___', '')
    if clear_screen:
        script = script.replace('___CLEAR_SCREEN_PLACEHOLDER___', 'Clear-Host')
    else:
        script = script.replace('___CLEAR_SCREEN_PLACEHOLDER___', '')
    return script

def clean_code_main_block(code: str) -> str:
    """
    Removes `if __name__ == "__main__"` blocks from Python code.

    Args:
        code (str): The input Python code.

    Returns:
        str: Cleaned code without the main execution block.
    """
    code_lines = code.split('\n')
    filtered_lines = []
    skip_block = False
    for line in code_lines:
        if line.strip().startswith('if __name__ == "__main__"') or line.strip().startswith("if __name__ == '__main__'"):
            skip_block = True
            continue
        if skip_block:
            if line.strip() and (not line.startswith(' ')) and (not line.startswith('\t')):
                skip_block = False
            else:
                continue
        filtered_lines.append(line)
    return '\n'.join(filtered_lines)

def extract_final_answer(text: str, mode: bool='boxed', strict=True):
    """Extract final answer from generated text using a specific parsing mode.

    Args:
        text: Raw generated text that may include reasoning/tool wrappers.
        mode: Parsing mode (`tag`, `boxed`, or `markdown`).
        strict: For markdown mode, require fenced markdown blocks when True.

    Returns:
        For `tag`/`boxed`: extracted string or None.
        For `markdown`: parsed `pd.DataFrame` or None.
    """
    text = text.split('</think>')[-1].strip()
    if mode == 'tag':
        answer_pattern = '<answer>(.*?)</answer>'
        match = re.finditer(answer_pattern, text, re.DOTALL)
        matches = list(match)
        if len(matches) < 1:
            return None
        return matches[-1].group(1).strip()
    elif mode == 'boxed':
        if not text:
            return None
        matches = []
        i = 0
        while i < len(text):
            boxed_start = text.find('\\boxed{', i)
            if boxed_start == -1:
                break
            content_start = boxed_start + 7
            if content_start >= len(text):
                break
            brace_count = 1
            content_end = content_start
            while content_end < len(text) and brace_count > 0:
                char = text[content_end]
                if char == '{':
                    brace_count += 1
                elif char == '}':
                    brace_count -= 1
                content_end += 1
            if brace_count == 0:
                content = text[content_start:content_end - 1]
                matches.append(content)
                i = content_end
            else:
                i = content_start
        return matches[-1] if matches else None
    elif mode == 'markdown':
        if not text or not isinstance(text, str):
            return None
        response_df = None
        markdown_str = re.findall('```markdown(.*?)```', text, re.DOTALL)
        if not markdown_str:
            if strict:
                return None
            pipe_positions = [m.start() for m in re.finditer('\\|', text)]
            if len(pipe_positions) >= 4:
                first_pipe = pipe_positions[0]
                last_pipe = pipe_positions[-1]
                start = text.rfind('\n', 0, first_pipe)
                start = 0 if start == -1 else start
                end = text.find('\n', last_pipe)
                end = len(text) if end == -1 else end
                table_candidate = text[start:end]
                markdown_str = re.findall('((?:\\|.*\\n?)+)', table_candidate)
        if markdown_str:
            markdown_str = markdown_str[-1].strip()
            lines = markdown_str.split('\n')
            lines = [line.strip() for line in lines]
            new_lines = []
            for line in lines:
                if set(line.strip()).issubset(set('|- :')) or '|' not in line:
                    continue
                new_lines.append('|'.join([_line.strip() for _line in line.split('|')]))
            if not new_lines:
                return None
            markdown_str = '\n'.join(new_lines)
            try:
                response_df = pd.read_csv(StringIO(markdown_str), sep='|', keep_default_na=False)
                response_df = response_df.loc[:, ~response_df.columns.str.startswith('Unnamed')]
                for col in response_df.columns:
                    if response_df[col].dtype == 'object':
                        response_df[col] = response_df[col].apply(lambda x: x.replace('<br>', '\n') if isinstance(x, str) and x else x)
                    response_df[col] = response_df[col].replace('', 'nan')
                return response_df
            except Exception:
                return None
        return response_df
    else:
        raise ValueError(f"Unknown mode: {mode}. Must be 'tag', 'boxed', or 'markdown'")

def _convert_range_like_params(params: dict) -> dict:
    """Convert list values for common range/size keys to tuples.

    This helps map Hydra YAML list values into IsaacLab config classes that
    expect tuples (e.g. ``*_range``).
    """
    converted = {}
    for (key, value) in params.items():
        if isinstance(value, list) and (key.endswith('_range') or key in ('size', 'difficulty_range')):
            converted[key] = tuple(value)
        else:
            converted[key] = value
    return converted

def splitdrive(p):
    """Split a pathname into drive and path specifiers. Returns a 2-tuple
"(drive,path)";  either part may be empty"""
    if p[1:2] == ':':
        return (p[0:2], p[2:])
    return ('', p)

def _compute_track_prompt_fields(model_type: str, is_drum_track: bool, v: dict):
    """Shared attrs/bar_attrs/is_ar/is_ignored computation, given a dict of
    raw 0-based values (0 = Any/unset) from the dashboard's per-track
    combo/slider values."""
    attrs = {}
    bar_attrs = {}
    is_ar = bool(round(v.get('autoregressive', 0)))
    is_ignored = bool(round(v.get('ignore', 0)))
    density = int(v.get('density', 0))
    min_poly = int(v.get('min_polyphony_q', 0))
    max_poly = int(v.get('max_polyphony_q', 0))
    min_dur = int(v.get('min_note_duration_q', 0))
    max_dur = int(v.get('max_note_duration_q', 0))
    if model_type == 'yellow':
        if density > 0 and is_drum_track:
            attrs['note_density'] = density - 1
        if min_poly > 0 and (not is_drum_track):
            attrs['min_polyphony'] = min_poly - 1
        if max_poly > 0 and (not is_drum_track):
            attrs['max_polyphony'] = max_poly - 1
        if min_dur > 0 and (not is_drum_track):
            attrs['min_note_duration'] = min_dur - 1
        if max_dur > 0 and (not is_drum_track):
            attrs['max_note_duration'] = max_dur - 1
        return (attrs, bar_attrs, is_ar, is_ignored)
    key_sig = int(v.get('key_signature', 0))
    pitch_rng = int(v.get('pitch_range', 0))
    silence = int(v.get('silence_proportion', 0))
    pcs = int(v.get('pitch_class_set', 0))
    if key_sig > 0 and (not is_drum_track):
        attrs['key_signature'] = key_sig - 1
    if pitch_rng > 0 and (not is_drum_track):
        attrs['pitch_range'] = pitch_rng - 1
    if silence > 0:
        attrs['silence_proportion'] = silence - 1
    if min_dur > 0 and (not is_drum_track):
        attrs['min_note_duration'] = min_dur - 1
    if max_dur > 0 and (not is_drum_track):
        attrs['max_note_duration'] = max_dur - 1
    if density > 0 and is_drum_track:
        bar_attrs['bar_note_density'] = density - 1
    if min_poly > 0 and (not is_drum_track):
        bar_attrs['bar_min_polyphony'] = min_poly - 1
    if max_poly > 0 and (not is_drum_track):
        bar_attrs['bar_max_polyphony'] = max_poly - 1
    if pcs > 0 and (not is_drum_track):
        bar_attrs['pitch_class_set'] = pcs - 1
    if model_type == 'expressive':
        nomml = int(v.get('nomml', 0))
        if nomml > 0:
            attrs['nomml'] = nomml - 1
    return (attrs, bar_attrs, is_ar, is_ignored)

def display_name(name: str | None) -> str | None:
    """A `--- `/`+++ ` line's file name for display: a/ or b/ dropped, None for /dev/null."""
    if name is None:
        return None
    name = name.rstrip('\r')
    if not name.startswith('"'):
        name = name.split('\t', 1)[0]
    if name == '/dev/null':
        return None
    if name.startswith(('"a/', '"b/')):
        return '"' + name[3:]
    return name[2:] if name[:2] in {'a/', 'b/'} else name

def _slower(row: dict) -> bool:
    """Median-loses to the baseline, and -- where fresh-process spreads exist --
    the spread cannot explain the loss away."""
    (ours, base) = (row.get('step_ms'), row.get('baseline_step_ms'))
    if ours is None or base is None:
        return False
    ours_spread = row.get('step_ms_spread') or [ours]
    base_spread = row.get('baseline_step_ms_spread') or [base]
    if len(ours_spread) > 1 and min(ours_spread) < min(base_spread):
        return False
    return statistics.median(ours_spread) >= statistics.median(base_spread)

def _x_merged_lines(wsf):
    """For each merged region, note the cell holding the visible text (an xlsx merge always stores the value in the top-left cell)."""
    try:
        rs = []
        for r in sorted((str(r) for r in wsf.merged_cells.ranges)):
            origin = r.split(':')[0]
            rs.append(f'{r} (value at {origin})')
    except Exception:
        rs = []
    return ('merged', rs)

def _industry_overlap_ratio(theme_a: dict, theme_b: dict) -> float:
    """Calculate industry name overlap ratio between two themes.

    Returns the Jaccard-like ratio: |intersection| / |smaller set|.
    """
    names_a = {ind.get('name') for ind in theme_a.get('matching_industries', [])}
    names_b = {ind.get('name') for ind in theme_b.get('matching_industries', [])}
    if not names_a or not names_b:
        return 0.0
    intersection = names_a & names_b
    smaller = min(len(names_a), len(names_b))
    return len(intersection) / smaller if smaller > 0 else 0.0

def fix_date(date):
    """
    fix date value from user input

    Args:
        date: date value - user input

    Returns:
        an array with fixed date value or original date
    """
    if date:
        if date.count(':') == 2:
            return [date, '{0} 23:59:59'.format(date.rsplit()[0])]
        elif date.count('|') == 1 and date.count(':') == 4:
            return date.rsplit('|')
        elif date.count('|') == 1 and date.count(':') == 0:
            return ['{0} 00:00:00'.format(date.rsplit('|')[0]), '{0} 23:59:59'.format(date.rsplit('|')[1])]
        else:
            return '{0} 00:00:00|{0} 23:59:59'.format(date).rsplit('|')
    return date

def confidence_for(origin: str, has_artifact: bool, corroborated: list[str], tier: int | None) -> tuple[str, str]:
    """Return certainty that the finding is real, and the sentence that justifies it."""
    if origin == 'layer0-scanner':
        return ('high', 'high because a deterministic scanner decided this mechanically. There is no judgement in the decision to reproduce.')
    if corroborated:
        return ('high', f"high because a deterministic scanner independently flagged an overlapping span: {', '.join(corroborated)}.")
    if not has_artifact:
        return ('low', 'low because the procedure returned convicted but recorded no artifact, so the work it did is not on the page and cannot be rechecked.')
    if tier == 3:
        return ('low', 'low because the procedure showed its work but the only thing that routed it here was a Tier 3 folklore marker.')
    return ('medium', 'medium because the procedure showed its work and the artifact is on the page, but no second mechanism corroborates it.')

def duration_to_seconds(d):
    """Convert a duration to float seconds.

    :param d: The duration specification, which is one of:
        * A string formatted as fz where f is a valid floating-point value
          and z is either omitted, 's', 'm', 'h', 'd'.
        * An integer in seconds.
        * A floating-point value in seconds.
    """
    if d is None:
        raise ValueError('cannot convert None')
    if isinstance(d, str):
        if not len(d):
            raise ValueError('cannot convert empty string')
        if d[-1] == 's':
            return float(d[:-1])
        elif d[-1] == 'm':
            return 60 * float(d[:-1])
        elif d[-1] == 'h':
            return 60 * 60 * float(d[:-1])
        elif d[-1] == 'd':
            return 60 * 60 * 24 * float(d[:-1])
        else:
            return float(d)
    else:
        return float(d)

def should_skip_self_loops(data_object, context=''):
    """Return True if data_object contains self-loops in edge_index.

    Optionally prints a context string to help identify the source.
    """
    if not hasattr(data_object, 'edge_index') or data_object.edge_index is None:
        return False
    if torch.all(data_object.edge_attr > 1e-12):
        return False
    msg = 'Skipping sample: self-loops detected in edge_index.'
    if context:
        msg = f'{msg} Context: {context}'
    print(msg, flush=True)
    return True

def _unresolvable_line(r: dict) -> str:
    """The cause, then its citation: when the entry carries a structured
    unresolvable_reason (signal axis today), lead with it and keep the evidence
    label as a bracketed source rather than dropping it. Other axes are
    unchanged (evidence, then evidence_label, then unresolvable_reason)."""
    reason = r.get('unresolvable_reason')
    if reason:
        label = r.get('evidence_label')
        return f'{reason} [{label}]'.strip() if label else reason.strip()
    text = r.get('evidence') or r.get('evidence_label') or r.get('unresolvable_reason') or ''
    return text.strip()

def _png_to_pdf_path(path: str) -> str:
    """Convert a .png path to a .pdf path (best-effort).

    Used for optional dual outputs (PNG + PDF) without changing existing defaults.
    """
    if not isinstance(path, str):
        path = str(path)
    if path.lower().endswith('.png'):
        return path[:-4] + '.pdf'
    return path + '.pdf'

def fib_basic(n):
    """
    Simple Fibonacci function, defined recursively.
    :param n: A non-negative integer.
    :return: The Fibonacci number for n.
    """
    if n < 0:
        raise ValueError('Argument must be non-negative')
    if n < 2:
        return n
    else:
        return fib_basic(n - 1) + fib_basic(n - 2)

def doBytes(bytes_or_str):
    """
    Make sure you're working with a bytes object
    bytes_or_str may be a bytes or a str object,
    either way we return bytes
    """
    if type(bytes_or_str) == str:
        return bytes_or_str.encode('utf-8')
    return bytes_or_str

def filter_services(data: dict, service_names: list[str]) -> dict:
    """Filter data to only include the specified services.

    Matching is case-insensitive. Exits with an error if any requested
    service is not found in the data.
    """
    available = {k.lower(): k for k in data}
    filtered = {}
    missing = []
    for name in service_names:
        key = name.lower()
        if key in available:
            original_key = available[key]
            filtered[original_key] = data[original_key]
        else:
            missing.append(name)
    if missing:
        print(f"Warning: services not found in data: {', '.join(missing)}")
        print(f"Available services: {', '.join(sorted(data.keys()))}")
    return filtered

def compute_spl_offline(success: bool, path_length: float, shortest_path: float) -> float:
    """Compute SPL for a single episode (offline).

    SPL = L / max(P, L) if success else 0

    Args:
        success: Whether the episode was successful
        path_length: Actual path length taken
        shortest_path: Shortest path length

    Returns:
        SPL value for this episode in [0, 1]
    """
    if not success:
        return 0.0
    if shortest_path <= 0:
        return 0.0
    if path_length > 0:
        return shortest_path / max(path_length, shortest_path)
    elif shortest_path > 0:
        return 1.0
    else:
        return 0.0

def extract_vulns_for_file(results, target_file):
    """Extract list of (cvi_id, lineno, file_path) from scan results for a specific file."""
    if not results:
        return []
    vulns = []
    items = []
    if isinstance(results, list):
        items = results
    elif isinstance(results, dict):
        for key in ('results', 'vulnerabilities', 'data'):
            if key in results and isinstance(results[key], list):
                items = results[key]
                break
    for item in items:
        if not isinstance(item, dict):
            continue
        file_val = item.get('file') or item.get('file_path') or item.get('file_name') or ''
        if target_file in file_val:
            cvi = item.get('cvi_id') or item.get('cvi') or item.get('vuln_class') or ''
            cvi_str = str(cvi)
            if cvi_str.isdigit():
                cvi_str = 'CVI-' + cvi_str
            lineno = None
            if ':' in str(file_val):
                parts = str(file_val).rsplit(':', 1)
                if parts[-1].isdigit():
                    lineno = int(parts[-1])
            if 'CVI' in cvi_str:
                vulns.append((cvi_str, lineno))
    return vulns

def _get_module_names_tied_with_embedding(model) -> list[str]:
    """
    Get the list of the fully qualified names of the modules that are tied to the input embeddings. In case of a
    source-target-mapping `_tied_weights_keys`, it will attempt to identify the input embedding weights from the
    mapping and return the list of tied modules accordingly. This gives a unified interface to both transformers v4
    tied weights and v5 mapped tied weights.

    For example: For models which have `embed_tokens` and `lm_head` as the tied keys, this function will return
    [`lm_head`]. The PEFT model is assumed to be transparent: returned names will be relative to the base model, so
    even though `model.base_model.lm_head` is tied, the returned name is `lm_head` since such attributes are forwarded
    to the base model anyway. Non-transformer models have to provide a `_tied_weights_keys` attribute for this function
    to work.

    If the model's config has `tie_word_embeddings` set to `False`, this function returns an empty list, as weight
    tying is explicitly disabled for that model checkpoint.
    """
    tied_weights: list[str] = []
    if hasattr(model, 'get_base_model'):
        model = model.get_base_model()
    if hasattr(model, 'tuner_layer_cls'):
        model = model.model
    model_config = getattr(model, 'config', None)
    if model_config is not None and hasattr(model_config, 'tie_word_embeddings') and (model_config.tie_word_embeddings is False):
        return []
    if not hasattr(model, '_tied_weights_keys'):
        return []
    base_layer_pattern = re.compile('[^.]+\\.base_layer\\.')
    if isinstance(model._tied_weights_keys, dict):
        if not hasattr(model, 'get_input_embeddings'):
            raise ValueError("The supplied model implements `_tied_weights_keys` as a dict but doesn't implement 'get_input_embeddings' so we can't determine which weights are tied to embeddings.")
        tied_weights_keys: dict[str, str] = {}
        for (module_name, module) in model.named_modules():
            module_tied_weights_keys = getattr(module, '_tied_weights_keys', None)
            if module_tied_weights_keys and (not module_name):
                tied_weights_keys.update(module_tied_weights_keys)
            elif module_tied_weights_keys:
                tied_weights_keys.update({f'{module_name}.{k}': f'{module_name}.{v}' for (k, v) in module_tied_weights_keys.items()})
        input_embedding_params = set(model.get_input_embeddings().parameters())
        candidates = [n for (n, p) in model.named_parameters(remove_duplicate=False) if p in input_embedding_params]
        peft_reverse_mapping = {base_layer_pattern.sub('', name): name for name in candidates}
        peft_reverse_mapping.update(**{name.replace('base_layer.', ''): name for name in candidates})
        tied_weights.extend((peft_reverse_mapping.get(k, k) for (k, v) in tied_weights_keys.items() if peft_reverse_mapping.get(v, v) in candidates))
    elif model._tied_weights_keys is not None:
        tied_weights.extend(model._tied_weights_keys)
    return sorted({name.rpartition('.')[0] for name in tied_weights})

def _extract_last_user_instruction(messages: list[dict]) -> str:
    """Return the most recent user message text from the current turn context."""
    for msg in reversed(messages):
        if isinstance(msg, dict) and msg.get('role') == 'user':
            text = _flatten_message_content(msg.get('content'))
            if text:
                return text
    return ''

def map_refs_on_du_cps(refs, nsd, vnfs, mapping, vnf_id=None):
    """
    This method returns a list of du cps, that map on the cp references in the
    refs input.
    """
    cps = []
    for ref in refs:
        if ':' in ref:
            (vnf_ref, cp_ref) = ref.split(':')
            for vnf_nsd in nsd['network_functions']:
                if vnf_nsd['vnf_id'] == vnf_ref:
                    for vnf in vnfs:
                        if not vnf_id or vnf['id'] == vnf_id:
                            vnfd = vnf['vnfd']
                            if vnf_nsd['vnf_name'] == vnfd['name'] and vnf_nsd['vnf_version'] == vnfd['version'] and (vnf_nsd['vnf_vendor'] == vnfd['vendor']):
                                du_cp_list = map_vnf_cp_on_du_cps(cp_ref, vnfd)
                                for du_cp in du_cp_list:
                                    du_cp['vnf_id'] = vnf['id']
                                    du_cp['vim_id'] = mapping[vnf['id']]['vim_id']
                                cps.extend(du_cp_list)
                    break
    return cps

def declared_software_refs(project_name: str, config) -> list[str]:
    """The software an object declares, as fully qualified '<package>:<name>'.

    Accepts the one-entry short form ('software: firmware') as well as a list.
    Order is the author's, duplicates are dropped: the list says what the object
    ships with, and saying it twice does not make it two things.
    """
    if not isinstance(config, dict):
        return []
    refs = config.get('software')
    if not refs:
        return []
    if isinstance(refs, str):
        refs = [refs]
    resolved: list[str] = []
    for ref in refs:
        if not isinstance(ref, str) or not ref.strip():
            continue
        normalized = normalize_resource_path(project_name, ref.strip())
        if normalized not in resolved:
            resolved.append(normalized)
    return resolved

def _get_alloc_cmd(nodes: int, time: str | None=None, account: str | None=None, options: dict[str, str] | None=None) -> list[str]:
    """Return the command to request an allocation from Slurm with
    the class variables as the slurm options.
    """
    salloc_args = ['--no-shell', '-N', str(nodes), '-J', 'SmartSim']
    if time:
        salloc_args.extend(['-t', _validate_time_format(time)])
    if account:
        salloc_args.extend(['-A', str(account)])
    arguments = set(options.keys() if options is not None else {})
    invalid = {'t', 'time', 'N', 'nodes', 'A', 'account'}
    if (valid := arguments.intersection(invalid)):
        raise SSReservedKeywordError(f'Expecting time, nodes, account as an argument. Also received: {valid}')
    for (opt, val) in (options or {}).items():
        short_arg = bool(len(str(opt)) == 1)
        prefix = '-' if short_arg else '--'
        if not val:
            salloc_args += [prefix + opt]
        elif short_arg:
            salloc_args += [prefix + opt, str(val)]
        else:
            salloc_args += ['='.join((prefix + opt, str(val)))]
    return salloc_args

def default_state_and_entry_point(query: str=None) -> tuple[dict, str]:
    """Returns the default state and entry point for the application."""
    if query is None:
        query = "Fetch the UK's GDP over the past 5 years, then draw a line graph of it. Once the python code has been written and the graph drawn, the task is complete."
    return ({'messages': [], 'query': query, 'sender': '', 'parsed_tool_calls': []}, 'researcher')

def _sorted(items):
    """
    Returns a sorted version of the given items (if they are dicts/strings).
    """
    sorted_items = items
    if len(items) > 1:
        if isinstance(items[0], str):
            sorted_items = sorted(items)
        elif isinstance(items[0], dict):
            sort_key = _sort_key(items[0])
            if sort_key is not None:
                sorted_items = sorted(items, key=lambda x: x[sort_key])
    return sorted_items

def apply_labels(__data__, labels):
    """
    Filters out the tests whose label doesn't match the labels given when running audit and returns a new data structure with only labelled tests.
    """
    labelled_data = {}
    if labels:
        labelled_data['mount'] = {}
        for topkey in ('blacklist', 'whitelist'):
            if topkey in __data__.get('mount', {}):
                labelled_test_cases = []
                for test_case in __data__['mount'].get(topkey, []):
                    if isinstance(test_case, dict) and test_case:
                        test_case_body = test_case.get(next(iter(test_case)))
                        if set(labels).issubset(set(test_case_body.get('labels', []))):
                            labelled_test_cases.append(test_case)
                labelled_data['mount'][topkey] = labelled_test_cases
    else:
        labelled_data = __data__
    return labelled_data
